(window.GIM_TS=window.GIM_TS||{})["Chullin.4"]={"from":96,"a":[["\u0003ולדידן\u0004 \u0005[ולפי שיטתנו שלנו]\u0006 בבבל הריהו חלב גמור עד ש\u0003מיסתם נמי לא סתים\u0004 \u0005[לסתום אינו סותם]?!\u0006 אלא למרות שאנו מחמירים ואיננו אוכלים אותו, אין זה משום שהוא אסור מן התורה, ולכן גם לשיטתנו הוא סותם.","ומסבירים: הקיבה עשויה כמין קשת, שצידה החיצון מעוגל, והפנימי ישר יחסית, כיתר (חוט) של הקשת. \u0003דאקשתא\u0004 \u0005[\u0006החלב שנמצא \u0005על הקשת\u0006 של הקיבה\u0005]\u0006 — \u0003כולי עלמא לא פליגי דאסיר\u0004 \u0005[הכל אינם חולקים ש\u0006הוא \u0005אסור],\u0006 וגם בני ארץ ישראל, והוא איפוא, אותו \"חימצא\" שאמר רב נחמן בעמוד הקודם שאינו סותם. \u0003כי פליגי דאייתרא\u0004 \u0005[כאשר הם חולקים\u0006 הרי \u0005זה\u0006 בחלב שנמצא \u0005על היתר],\u0006 שהוא הקרוי \"בר חימצא\", שבני ארץ ישראל אוכלים אותו, ובני בבל אינם אוכלים אותו, אבל גם לדעתם הוא סותם את הנקב, כפי שאמר רב נחמן לעיל.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003דאייתרא\u0004 \u0005[\u0006החלב \u0005שעל היתר],\u0006 הקרוי \"בר חימצא\" — \u0003כולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חולקים שהוא מותר],\u0006 וגם בני בבל. \u0003כי פליגי דאקשתא\u0004 \u0005[כאשר הם חלוקים\u0006 הרי זה בחלב \u0005שעל הקשת],\u0006 שבני ארץ ישראל אוכלים גם אותו, ובני בבל אוסרים אותו באכילה.","ומעירים: מה שנאמר שבני ארץ ישראל מקילים בחלב שעל היתר, הוא \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב אויא,\u0004 שכך \u0003אמר ר' אמי\u0004 מחכמי ארץ ישראל: \u0003מקמצין\u0004 \u0005[מסירים מעט]\u0006 חלב מעל החלב שעל היתר (מפני שאותו חלב הוא חלב שעל הקרב, שהוא אסור), ואת החלב שעל היתר אוכלים. \u0003וכן אמר ר' ינאי,\u0004 שהיה מחכמי ארץ ישראל, \u0003משום\u0004 (בשם) \u0003זקן אחד: מקמצין. אמר רב אויא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003ר' אמי, קמצו והבו ליה\u0004 \u0005[הסירו מעט ונתנו לו]\u0006 מן החלב שעל היתר, \u0003ואכל.\u0004","עוד מסופר, \u0003שמעיה\u0004 \u0005[שמשו]\u0006 של \u0003ר' חנינא\u0004 מחכמי ארץ ישראל, \u0003הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003ר' חנינא, אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003קמוץ, הב לי דאיכול\u0004 \u0005[הסר מעט, תן לי שאוכל],\u0006 \u0003חזייה דהוי קמחסם\u0004 \u0005[ראה אותו,\u0006 את השמש, \u0005שהוא מהסס],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בבלאה את\u0004 \u0005[בבלי אתה],\u0006 ואתה רגיל לנהוג בזה איסור, וכיון שכך \u0003גום שדי\u0004 \u0005[חתוך וזרוק\u0006 את הכל\u0005],\u0006 וגם את החלב שעל היתר.","ובענין ששנינו במשנתנו, שאם ניקבו דקין (בני מעיים) הרי זו טריפה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: בני מעיין שניקבו, וליחה סותמתן\u0004 — \u0003כשרה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003ליחה\u0004 זו שאמרנו? \u0003אמר רב כהנא: שירקא דמעייא דנפיק אגב דוחקא\u0004 \u0005[הליחה שעל\u0006 דופן \u0005המעיים שיוצאת בדוחק],\u0006 על ידי גירוד בסכין.","מסופר, \u0003גמירי חבריא\u0004 \u0005[למדו חביריו]\u0006 של \u0003ר' אבא מר' אבא, ומנו\u0004 \u0005[ומיהם\u0006 החברים\u0005]?\u0006 \u0003ר' זירא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שלמדו דבר זה \u0003חבריא\u0004 \u0005[חביריו]\u0006 של \u0003ר' זירא מר' זירא, ומנו\u0004 \u0005[ומיהם\u0006 חבריו\u0005]?\u0006 \u0003ר' אבא. אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הלכה כרבן שמעון בן גמליאל בטרפה, והלכה כר' שמעון ב\u0004הלכות \u0003אבל.\u0004","ומפרטים: \u0003הלכה כרבן שמעון בן גמליאל בטרפה\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו],\u0006 שבני המעיים שניקבו וליחה סותמתם — כשרה. הלכה \u0003כר' שמעון באבל, מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 \u0003דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 אחד מקרובי המת שלא ידע מפטירת המת, והצטרף רק מאוחר יותר לשאר האבלים, \u0003כל שלשה ימים הראשונים\u0004 של אבלות, אם \u0003בא ממקום קרוב\u0004 — הרי הוא \u0003מונה עמהן,\u0004 וגומר יחד איתם את שבעת ימי האבילות, אף על פי שהחל אותה מאוחר יותר.","אם בא \u0003ממקום רחוק\u0004 — \u0003מונה לעצמו\u0004 שבעה ימים. \u0003מכאן ואילך,\u0004 אם הצטרף אליהם לאחר שלושה ימים הראשונים, \u0003אפילו בא ממקום קרוב\u0004 — \u0003מונה\u0004 שבעה \u0003לעצמו. ר' שמעון אומר: אפילו\u0004 בא \u0003ביום השביעי,\u0004 אם \u0003בא ממקום קרוב\u0004 — \u0003מונה עמהן.\u0004 ובענין זה אמר ר' יוחנן שהלכה כמותו.","מסופר, \u0003אמר מאן דהוא\u0004 \u0005[מי שהוא]\u0006 שלא הוזכר שמו: \u0003איזכי ואיסק ואגמרה לשמעתא מפומיה דמרה\u0004 \u0005[אזכה ואעלה\u0006 לארץ ישראל \u0005ואלמד את ההלכה\u0006 הזו \u0005מפי בעליה].\u0006 \u0003כי סליק אשכחיה\u0004 \u0005[כאשר עלה מצא את]\u0006 \u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא,\u0004 שמשמו נאמרה שמועה זו, \u0003אמר ליה\u0004 \u0005[לו],\u0006 האם \u0003אמר מר\u0004 \u0005[אדוני]\u0006 ש\u0003הלכה כרבן שמעון בן גמליאל בטרפה,\u0004 שמעיים שניקבו וליחה סותמתם — כשרה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין הלכה\u0004 כמותו \u0003אמרי\u0004 \u0005[אמרתי].\u0006","שאל אותו: \u0003כר' שמעון באבל, מאי\u0004 \u0005[מה הדין]?\u0006 מה אמרת בזה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 בענין זה גם כן לא אמרתי הלכה, אלא \u0003פלוגתא נינהו\u0004 \u0005[דעות חלוקות הן].\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר],\u0006 \u0003רב חסדא אמר: הלכה\u0004 כר' שמעון באבל, \u0003וכן אמר ר' יוחנן\u0004 שכך \u0003הלכה, ורב נחמן אמר: אין הלכה. ו\u0004מסכמים:","\u0003ואין הלכה כרבן שמעון בן גמליאל\u0004 המיקל \u0003בטרפה,\u0004 אלא בני מעיים שניקבו, גם אם ליחה סותמתם — טריפה היא. \u0003והלכה כר' שמעון באבל,\u0004 שאפילו בא ביום השביעי מונה עמהם, מדוע? משום שאנו הולכים על פי הכלל ש\u0003אמר שמואל: הלכה כדברי המיקל באבל.\u0004","\u0003אמר רב שימי בר חייא: מקיפים\u0004 \u0005[מקרבים\u0006 ומשווים\u0005]\u0006 \u0003בבני מעיים,\u0004 אם בא לפנינו נקב במעיים ואין ידוע אם קודם שחיטה נעשה והיא טריפה, או לאחריה — עושים בהם נקב נוסף ומשווים, ואם מראה הנקבים דומה — כשרה, שוודאי לאחר שחיטה נעשה.","מסופר, \u0003הנהו\u0004 \u0005[אותם]\u0006 \u0003בני מעיים\u0004 שניקבו \u0003דאתו לקמיה\u0004 \u0005[שהובאו לפני]\u0006 \u0003רבא\u0004 שיפסוק בעניינם, עשה נקב אחר, \u0003אקפינהו ולא אידמו\u0004 \u0005[קירב\u0006 והשווה \u0005אותם\u0006 את \u0005הנקבים\u0006 \u0005ולא היו דומים].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב משרשיא בריה\u0004 \u0005[בנו],\u0006 היה \u0003ממשמש בהו\u0004 \u0005[בהם]\u0006 בנקבים החדשים, \u0003ואידמו\u0004 \u0005[ונעשו\u0006 הנקבים \u0005דומים\u0006 לראשונים\u0005],\u0006 והכשיר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003מנא לך הא\u0004 \u0005[מנין לך דבר זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 זו היתה הסברה שלי: \u0003כמה ידי ממשמשו בהני מקמי דליתי לקמיה דמר\u0004 \u0005[כמה ידיים היו ממשמשות באלה\u0006 הראשונים לאחר שחיטה \u0005קודם שהגיעו לפני אדוני],\u0006 ואם נמשמש באלו ייתכן שיהיו דומים זה לזה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חכים ברי\u0004 \u0005[חכם בני]\u0006 \u0003ב\u0004הלכות \u0003טרפות כ\u0004מו \u0003ר' יוחנן!\u0004","ובענין דומה, \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מקיפים\u0004 \u0005[מקרבים\u0006 ומשווים\u0005]\u0006 נקבים \u0003בריאה,\u0004 שעושים נקב חדש לראות אם הנקב שנמצא דומה לו, ואירע לאחר שחיטה. \u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 שניתן לסמוך על השוואה זו \u0003אלא\u0004 כשעושים נקב \u0003באותה ערוגה\u0004 (שורת אונות) שבריאה, מימין או משמאל, \u0003אבל מערוגה לערוגה\u0004 — \u0003לא.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 משווים \u0003אפילו מערוגה לערוגה,\u0004 וכן משווים אפילו \u0003מ\u0004בהמה \u0003דקה ל\u0004בהמה \u0003דקה\u0004 אחרת, \u0003ומ\u0004בהמה \u0003גסה ל\u0004בהמה \u0003גסה\u0004 אחרת, \u0003אבל לא מגסה לדקה, ולא מדקה לגסה.\u0004","ובענין דומה \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מקיפין\u0004 \u0005[מקרבים,\u0006 עושים נקב ומשווים\u0005]\u0006 לנקב ש\u0003בקנה. אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כשעושים נקב \u0003באותה חוליא\u0004 שבקנה, \u0003אבל מחוליא לחוליא\u0004 — \u0003לא.\u0004 ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003אפילו מחוליא לחוליא\u0004 משווים, \u0003ומבר\u0004 \u0005[ומבן]\u0006 \u0003חוליא\u0004 (כעין חוליה דקה שבין החוליות) \u0003לבר\u0004 \u0005[לבן]\u0006 \u0003חוליא\u0004 אחרת משווים, \u0003אבל לא מחוליא לבר\u0004 \u0005[לבן]\u0006 \u0003חוליא, ולא מבר\u0004 \u0005[מבן]\u0006 \u0003חוליא לחוליא.\u0004","אגב הדיון בבני מעיים שניקבו מביאים מה ש\u0003אמר זעירי: חלחולת\u0004 (המעי הגס, המסתיים בפי הטבעת) \u0003שניקבה\u0004 — \u0003כשרה\u0004 הבהמה, \u0003הואיל ויריכים מעמידות אותה\u0004 וסותמות את הנקב. \u0003וכמה,\u0004 מהו המקום בחלחולת שדנים בו דין זה? \u0003אמר ר' אילעי אמר ר' יוחנן:\u0004 אם היה הנקב ב\u0003מקום הדבק,\u0004 במקום בו החלחולת דבוקה לירכיים, אפילו אם ניקב \u0003ברובו\u0004 — כשרה, אם ניקבה \u0003שלא במקום הדבק\u0004 אפילו \u0003במשהו\u0004 הריהי טריפה.","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו אותה חכמים לפני]\u0006 \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן, אמר\u0004 להם: \u0003לאו מי אמינא לכו לא תתלו ביה\u0004 \u0005[האם לא אמרתי לכם אל תתלו בו]\u0006 ברב נחמן"],["\u0003בוקי סריקי\u0004 \u0005[בקבוקים ריקים],\u0006 כלומר, דברים סתם! \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב נחמן: מקום הדבק, אפילו ניטל כולו\u0004 — \u0003כשר, והוא שנשתייר בו\u0004 במקום הדבק \u0003כדי תפיסה\u0004 (אחיזה). ושואלים: \u0003וכמה\u0004 הוא כדי תפיסה? \u0003אמר אביי: כמלא בטדא בתורא\u0004 \u0005[\u0006רוחב \u0005אצבע\u0006 אפילו \u0005בשור\u0006 גדול\u0005].\u0006","שנינו במשנה בין הטרפות: \u0003הכרס הפנימי\u0004 שניקבה או שנקרע רוב החיצונה. \u0003אמר רב יהודה אמר רב, העיד נתן בר שילא ריש טבחיא\u0004 \u0005[ראש הטבחים,\u0006 השוחטים\u0005]\u0006 של \u0003צפורי לפני רבי\u0004 עדות זו \u0003משום\u0004 (בשם) \u0003ר' נתן: אי זו היא כרס הפנימי?\u0004 זו שקוראים לה בארמית \u0003\"סניא דיבי\",\u0004 חלק מן המעיים, הקרוי בלשוננו \"המעי העיור\". \u0003וכן אמר ר' יהושע בן קרחה: סניא דיבי. ר' ישמעאל אמר:\u0004 כרס הפנימי הוא מה שנקרא \u0003איסתומכא דכרסא\u0004 \u0005[פתח הכרס].\u0006","\u0003רב אסי אמר ר' יוחנן: מקום צר יש בכרס,\u0004 שהוא קרוי כרס הפנימי, וכל השאר נכלל בכרס החיצונה, \u0003ואיני יודע איזהו. אמר רב נחמן בר יצחק: נפל כרסא בבירא\u0004 \u0005[הכרס בבור],\u0006 כלומר, כיון שאינו יודע מהו, נמצא שנקב בכל מקום בכרס אוסר! \u0003אמר רב אחא בר רב עוא,\u0004 כך \u0003אמר רב אסי\u0004 בפירוש הדבר: \u0003מן המיצר,\u0004 ממקום שהכרס הולכת ונעשית צרה לכיוון הוושט, \u0003ולמטה\u0004 לכיוון הוושט (כשהבהמה תלויה ברגליה) הוא הנקרא כרס הפנימי.","\u0003ר' יעקב בר נחמני אמר\u0004 בשם \u0003שמואל:\u0004 כרס הפנימי הוא ה\u0003מקום\u0004 בכרס \u0003שאין בו מילת,\u0004 בליטות כעין צמר שיש על דפנות הכרס. \u0003ר' אבינא אמר\u0004 בשם \u0003גניבא\u0004 שאמר \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 אותו \u0003טפח בוושט\u0004 שהוא \u0003סמוך לכרס\u0004 — \u0003זו היא כרס הפנימית.\u0004","\u0003אמרי במערבא משמיה\u0004 \u0005[אמרו בארץ ישראל משמו]\u0006 של \u0003ר' יוסי בר חנינא: כל הכרס כולו\u0004 — \u0003זו היא כרס הפנימית, ואיזהו\u0004 אם כן \u0003כרס החיצון?\u0004 אין זו הכרס עצמה, אלא זה \u0003בשר החופה\u0004 (המכסה) \u0003את רוב הכרס\u0004 מצידה התחתון של הבהמה. \u0003רבה בר רב הונא אמר:\u0004 הכרס הפנימית היא ה\u0003מפרעתה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003מפרעתה? אמר רב אויא: היכא דפרעי טבחי\u0004 \u0005[המקום,\u0006 הצד, \u0005שמגלים הטבחים\u0006 כשפותחים את הבהמה\u0005]\u0006 כלומר, צד הבטן.","מסופר, \u0003בנהרדעא עבדי\u0004 \u0005[היו עושים,\u0006 נוהגים להלכה\u0005]\u0006 \u0003כרבה בר רב הונא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר\u0004 שהיה מחכמי נהרדעא: \u0003כל הני שמעתתא מאי\u0004 \u0005[כל אותן השמועות\u0006 שאמרו חכמים לעיל בהגדרת כרס הפנימי \u0005מה הן]?\u0006 מה אתם עושים בהן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כולהו שייכן\u0004 \u0005[כולן שייכות,\u0006 כלולות\u0005]\u0006 \u0003ב\u0004מה שאמר \u0003רבה בר רב הונא,\u0004 שגם סניא דיבי, וגם איסותמכא דכרסא, וגם מקום שאין בו מילת, פונים לכיוון דופן בטן הבהמה, ה\"מפרעתה\".","ושאל אותו: \u0003ו\u0004מה שאמר \u0003רב אסי אמר ר' יוחנן,\u0004 שמקום צר יש בכרס ואינו יודע מהו, \u0003מאי\u0004 \u0005[מהו]?\u0006 הרי יש לחשוש לכל מקום בכרס! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כבר פירשה רב אחא בר עוא,\u0004 שהוא מן המיצר ולמטה. ושאל אותו: \u0003ו\u0004מה שאמר \u0003ר' אבינא\u0004 שרק הטפח הסמוך לוושט הוא הכרס הפנימית, \u0003ודבני מערבא מאי\u0004 \u0005[\u0006מה שאמרו \u0005בני ארץ ישראל,\u0006 שכל הכרס קרויה כרס הפנימית, \u0005מה\u0006 אתה עושה בהם\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הני ודאי פליגי\u0004 \u0005[אלה ודאי חלוקים]\u0006 על דברי רבה בר \u0003רב הונא, ואין אנו פוסקים כמותם.\u0004","שנינו במשנה: כרס החיצונה שנקרעה, \u0003ר' יהודה אומר: ב\u0004בהמה \u0003גדולה\u0004 אם נקרעה בשיעור טפח — טריפה, ובבהמה קטנה — אם נקרעה ברובה. \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: לא גדולה\u0004 — \u0003גדולה ממש, ולא קטנה\u0004 — \u0003קטנה ממש, אלא\u0004 הכלל הוא: \u0003כל שנקרע בה\u0004 בכרס החיצונה \u0003טפח ולא הוי רובא\u0004 \u0005[ואין זה רוב]\u0006 הכרס — \u0003זו היא ששנינו: בגדולה טפח,\u0004 וכל שהקרע הוא \u0003רובא\u0004 \u0005[\u0006ב\u0005רוב]\u0006 הכרס החיצונה \u0003ולא הוי\u0004 \u0005[ואינו מגיע לכדי]\u0006 \u0003טפח\u0004 — \u0003זו היא ששנינו: בקטנה ברובא.\u0004 כלומר, כל שיש בקרע או טפח, או רוב הכרס החיצונה — הרי זו טריפה.","ותמהים: \u0003רובא ולא הוי טפח, פשיטא\u0004 \u0005[פשוט]\u0006 שעושה טריפה, שהרי בכל מקום דינו של רובו ככולו! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו, אלא במקרה \u0003דהויא\u0004 \u0005[שיש בה]\u0006 \u0003טפח במשהו\u0004 יותר מרוב, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 במקרה זה, שאורך כולה הוא יותר מטפח, \u0003עד דמיקרע\u0004 \u0005[שנקרע]\u0006 \u0003בה טפח\u0004 שלם \u0003לא הוי טרפה, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם אם נקרע פחות מטפח בכל זאת טריפה היא, כיון שנקרעה ברובה.","\u0003אמר גניבא אמר ר' אסי:\u0004 אם \u0003נקדרה\u0004 הכרס החיצונה, נעשה בה חור עגול, שגודלו \u0003כ\u0004גודל מטבע הקרויה \u0003סלע\u0004 \u0003—\u0004 \u0003טרפה,\u0004 ומדוע? \u0003שאם תמתח\u0004 הקדירה הזו — \u0003תעמוד על הטפח\u0004 לאורכה, שכן הוא גודלו של סלע. \u0003אמר ר' חייא בר אבא, לדידי מפרשא לי מיניה דגניבא\u0004 \u0005[לי נתפרש הדבר מגניבא\u0006 עצמו\u0005]\u0006 כשהיינו \u0003אמברא\u0004 \u0005[על המעבורת]\u0006 של \u0003נהרדעא:\u0004 אם היה הנקב \u0003כסלע\u0004 — \u0003כשרה, יתר מכסלע\u0004 — \u0003טרפה.\u0004 ושואלים: \u0003וכמה יתר מכסלע? אמר רב יוסף: כגון דעיילן תלת קשייתא בציפא בדוחקא\u0004 \u0005[שנכנסים שלושה גרעיני תמר כשהם מצופים\u0006 בשיירי בשר הפרי \u0005בדוחק],\u0006 ושהן נמצאים \u0003בלא ציפא\u0004 \u0005[ציפוי]\u0006 שהם לגמרי נקיים — נכנסות \u0003ברווחא\u0004 \u0005[ברווח].\u0006","שנינו במשנה: \u0003המסס ובית הכוסות,\u0004 הסמוכים זה לזה, שניקבו לחוץ (לחלל הבטן), ולא זה לזה — טריפה. בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מחט שנמצאת\u0004 תחובה \u0003בעובי\u0004 דופן \u0003בית הכוסות, מצד אחד\u0004 — הרי היא \u0003כשרה,\u0004 נמצאה תחובה \u0003משני צדדים\u0004 — \u0003טרפה.\u0004 ומכל מקום, גם במקרה שהמחט נמצאת משני צדדים — אינה טריפה בכל אופן, אלא יש לבדוק: אם \u0003נמצא עליה\u0004 על חוד המחט \u0003קורט\u0004 (מעט) \u0003דם\u0004 —"],["\u0003בידוע שלפני שחיטה\u0004 נעשה הנקב, וטריפה. \u0003לא נמצא עליה קורט דם\u0004 — \u0003בידוע שלאחר שחיטה\u0004 אירע, כשאין זרימת דם בגוף הבהמה, וכשרה.","\u0003הגליד פי המכה,\u0004 שפת הנקב — \u0003בידוע ששלשה ימים קודם שחיטה\u0004 נעשה הנקב, שהוא פרק הזמן שלוקח לפצע להגליד, ואם קנה את הבהמה בתוך שלושה ימים אלה — נמצא שקנה טריפה, ומיקח טעות הוא, ועל המוכר להחזיר לו מעותיו (ונוטל את הבהמה השחוטה). \u0003לא הגליד פי המכה,\u0004 ויש איפוא ספק האם הנקב אירע קודם הקניה או לאחריה — יש ללכת אחרי הכלל שאמרו חכמים בספק ממון ש\u0003המוציא מחבירו\u0004 — \u0003עליו הראיה,\u0004 והקונה אינו יכול לבוא בטענת מיקח טעות, אלא אם יביא ראיה שהנקב אירע קודם שבאה לרשותו.","ושואלים: \u0003ומאי שנא מכל נקובי דעלמא\u0004 \u0005[ומה שונה\u0006 דין המחט \u0005מכל הנקבים המצוים]\u0006 בבהמה, \u0003דאף על גב דליכא\u0004 \u0005[שאף על פי שאין]\u0006 \u0003דם\u0004 בנקב \u0003טריף מר\u0004 \u0005[מטריף החכם],\u0006 ואין זה סימן שאירע לאחר מיתה? ומשיבים: \u0003התם ליכא מידי למיסרך\u0004 \u0005[שם,\u0006 בסתם נקב, \u0005אין דבר שיידבק בו]\u0006 הדם, וגם אם היה שם דם — הוא נבלע בלחלוחית הבשר, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003מחט, אי איתא\u0004 \u0005[אם אמנם]\u0006 \u0003קודם שחיטה הוא\u0004 שעשתה את הנקב — \u0003מיסרך הוה סריך\u0004 \u0005[נדבק היה\u0006 הדם במחט\u0005],\u0006 ולכן אם לא נמצא עליה קורט דם — בידוע שלאחר שחיטה ניקבה.","מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לאביי, חזי מר האי צורבא מרבנן דאתא ממערבא\u0004 \u0005[ראה אדוני תלמיד חכם אחד שבא מארץ ישראל],\u0006 \u0003ואמר: רב עוירא שמני\u0004 \u0005[שמי],\u0006 \u0003ואמר: מעשה ובא לפני רבי מחט שנמצאת בעובי בית הכוסות מצד אחד, וטרפה,\u0004 פסק שהבהמה טריפה. \u0003שלח ליה\u0004 \u0005[לו]\u0006 אביי לרב עוירא לקרוא לו כדי לברר את הענין היטב, שהרי שנינו בברייתא שרק אם המחט נראית משני הצדדים הריהי טריפה. \u0003לא אתא לגביה\u0004 \u0005[לא בא\u0006 רב עוירא \u0005אצלו],\u0006 \u0003אזל הוא לגביה\u0004 \u0005[הלך הוא,\u0006 אביי, \u0005אליו].\u0006 \u0003הוה קאי אאיגרא\u0004 \u0005[היה\u0006 רב עוירא \u0005עומד על הגג],\u0006 \u0003אמר\u0004 לו אביי: \u0003ניחות מר וניתי\u0004 \u0005[ירד אדוני ויבוא]!\u0006 \u0003לא נחית\u0004 \u0005[לא ירד].\u0006 \u0003סליק הוא לגביה\u0004 \u0005[עלה הוא,\u0006 אביי, \u0005אליו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי, גופא דעובדא היכי הוה\u0004 \u0005[גופו של המעשה כיצד היה]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפטיר כנסיות אנא\u0004 \u0005[אני],\u0006 מוציא ומביא בבית המדרש, והייתי עומד \u0003לעילא מרבי רבה\u0004 \u0005[למעלה מרבי הגדול],\u0006 \u0005ר' יהודה הנשיא,\u0006 \u0003והוה\u0004 \u0005[והיו]\u0006 \u0003רב הונא ציפוראה\u0004 (מציפורי) \u0003ור' יוסי מדאה\u0004 (ממדי) \u0003יושבין לפניו, ובאת\u0004 (ובאה) \u0003לפני רבי מחט שנמצאת בעובי בית הכוסות מצד אחד,\u0004 מן הצד הפנימי, וחזר \u0003והפכה רבי\u0004 את בית הכוסות, והסתכל בצידו החיצוני, \u0003ומצא עליה קורט\u0004 (מעט) \u0003דם\u0004 כנגד המקום בו היתה המחט תקועה מצידו הפנימי, \u0003וטרפה, ואמר: אם אין שם מכה\u0004 (פצע), נקב מפולש שעשתה המחט, \u0003קורט דם מנין? אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003טרח טרייה לההוא גברא\u0004 \u0005[הטריח את האיש הזה,\u0006 אותי, \u0005לחינם]!\u0006 והרי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא:\u0004 אלו טריפות — \u0003המסס ובית הכוסות שניקבו לחוץ,\u0004 ואין פה איפוא \u0003חידוש, שהרי רבי לא פסק כן אלא משום שהוכח שבית הכוסות ניקב לחוץ.\u0004","שנינו במשנה: \u0003נפלה מן הגג\u0004 הרי זו טריפה, שמא נתרסקו איבריה. \u0003אמר רב הונא: הניח בהמה למעלה\u0004 על הגג, \u0003ובא ומצאה למטה,\u0004 ולא ראה שנפלה — \u0003אין חוששין משום ריסוקי אברים,\u0004 שנפלה ונחבטה, אלא יש להניח שירדה מעצמה בקפיצה וכדומה.","מסופר, \u0003ההוא גדיא דהוה ליה\u0004 \u0005[גדי אחד שהיה לו]\u0006 \u0003לרבינא\u0004 \u0003דחזא חושלא באיפומא\u0004 \u0005[שראה שעורים קלופות מבעד לארובה\u0006 שבין הגג לבית\u0005],\u0006 \u0003דגר\u0004 \u0005[קפץ]\u0006 דרך הארובה, וכך \u0003נפל מאיגרא לארעא\u0004 \u0005[מן הגג לארץ],\u0006 \u0003אתיא לקמיה\u0004 \u0005[באה\u0006 שאלה \u0005זו\u0006 \u0005לפני]\u0006 \u0003רב אשי, אמר ליה\u0004 \u0005[לו]\u0006 רבינא, \u0003הא דאמר\u0004 \u0005[זה שאמר]\u0006 \u0003רב הונא: הניח בהמה למעלה ובא ומצאה למטה אין חוששין משום ריסוקי אברים,\u0004 האם היא \u0003משום דאית לה מידי למסרך\u0004 \u0005[ש\u0006בדרך כלל \u0005יש לה\u0006 לבהמה \u0005משהו להיאחז בו],\u0006 \u0003והאי לית ליה מידי למסרך\u0004 \u0005[ו\u0006גדי \u0005ה\u0006שקפץ ונפל דרך הארובה \u0005אין לו דבר להיאחז בו].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 טעמו \u0003משום\u0004 שבהמה \u0003אמדה נפשה\u0004 \u0005[אומדת את עצמה]\u0006 אם היא יכולה לקפוץ או לא, \u0003והאי נמי אמדה נפשה\u0004 \u0005[וזה גם כן,\u0006 הגדי, \u0005אמד את עצמו]\u0006 לפני שקפץ?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: טעמו של רב הונא הוא \u0003משום דאמדה נפשה\u0004 \u0005[שאומדת את עצמה],\u0006 \u0003והאי נמי אמדה נפשה\u0004 \u0005[וזה גם כן,\u0006 הגדי, \u0005אמד את עצמו].\u0006","מסופר, \u0003ההיא אימרתא דהוה בי\u0004 \u0005[כבשה אחת שהיתה בביתו]\u0006 של \u0003רב חביבא דהוו שדרן כרעיה בתרייתא\u0004 \u0005[שהיו נגררות רגליה האחוריות],\u0006 \u0003אמר רב יימר: האי שיגרונא נקטיה\u0004 \u0005[בהמה זו אחז בה שגרון],\u0006 ולכן היא גוררת את הרגלים. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003חוט השדרה איפסיק\u0004 \u0005[נפסק],\u0006 ולכן רגליה משותקות, וטריפה היא! \u0003בדקוה, אשכחוה\u0004 \u0005[מצאוה]\u0006 שנפסק חוט השדרה שלה, \u0003כרבינא. ואפילו הכי\u0004 \u0005[כך],\u0006 שמצאו במקרה זה כדברי רבינא — \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב יימר,\u0004 שבבהמה הגוררת את רגליה אין לחשוש שנפסק חוט השדרה שלה, שכן \u0003שגרונא שכיח\u0004 \u0005[שגרון מצוי],\u0006 ופסיקת \u0003חוט השדרה לא שכיח\u0004 \u0005[אינו מצוי].\u0006","ועוד \u0003אמר רב הונא\u0004 בעניינים אלה: \u0003זכרים\u0004 (אילים) \u0003המנגחין זה את זה\u0004 — \u0003אין חוששין\u0004 להם \u0003משום ריסוקי אברים.\u0004 ו\u0003אף על גב דמידוו וקיימי\u0004 \u0005[אף על פי שהם כואבים ועומדים\u0006 במקומם\u0005]\u0006 — \u0003צימרא בעלמא הוא דנקט להו\u0004 \u0005[חום בלבד הוא שאחז בהם],\u0006 ואין לחשוש ליותר מזה. אבל \u0003אי נפול לארעא\u0004 \u0005[אם נפלו לארץ]\u0006 מחמת הנגיחות — \u0003ודאי חיישינן\u0004 \u0005[חוששים אנו],\u0006 שמא היה כאן ריסוק איברים.","\u0003אמר רב מנשי: הני דכרי דגנבי גנבי\u0004 \u0005[אותם אילים שגונבים הגנבים]\u0006 ומשליכים אותם מעבר לגדר ונופלים על הארץ — \u0003אין חוששין\u0004 להם \u0003משום ריסוק אברים, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כי שדו להו\u0004 \u0005[כאשר הם זורקים אותם\u0006 מעבר לגדר\u0005],\u0006 \u0003אמתנייהו שדו להו\u0004 \u0005[על מתניהם הם זורקים אותם],\u0006 \u0003כי היכי דלירהטי קמייהו\u0004 \u0005[כדי שירוצו לפניהם],\u0006 ואין לחשוש שנעשו טריפה. \u0003אהדרינהו\u0004 \u0005[אם החזירו אותם]\u0006 הגנבים לבעליהם — \u0003ודאי חיישינן\u0004 \u0005[חוששים אנו]\u0006 לריסוק איברים, מפני שכשהם חוזרים ומשליכים אותם מעבר לגדר לא אכפת לגנבים מה יקרה להם. \u0003והני מילי\u0004 \u0005[ודברים אלה אמורים]\u0006 \u0003דאהדרינהו\u0004 \u0005[שהחזירו אותם]\u0006 \u0003מחמת יראה,\u0004 מפני שלא רצו שיתפסו אותם, או שהכריחו אותם להחזירם. \u0003אבל\u0004 אם החזירו אותם \u0003מחמת\u0004 שעשו \u0003תשובה\u0004 — ודאי \u0003תשובה מעלייתא הוא דעבדי\u0004 \u0005[תשובה מעולה היא שעשו],\u0006 וודאי דאגו שלא יינזקו הבהמות.","\u0003אמר רב יהודה אמר רב: הכה\u0004 בהמה \u0003על ראשה\u0004 במקל, \u0003והלכה לה\u0004 המקל \u0003כלפי זנבה,\u0004 והיכה אותה לאורך גבה, או היכה \u0003על זנבה והלכה לה\u0004 המקל \u0003כלפי ראשה,\u0004 והיכה \u0003כנגד כל השדרה כולה\u0004 — \u0003אין חוששין משום ריסוקי אברים, ואי שלים חוטרא אפלגי דגבא\u0004 \u0005[ואם נגמר המקל במחצית הגב]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 בגלל המכה שהיכה בגבה ראש המקל. \u0003ואי אית בה קיטרי\u0004 \u0005[ואם יש בו\u0006 במקל \u0005קשרים,\u0006 מקומות בולטים\u0005]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 לריסוק, גם אם היה המקל ארוך כנגד כל השדרה. \u0003ואי מחיי אפסקיה\u0004 \u0005[ואם הכה אותו כעין חיתוך,\u0006 לרוחב הגב\u0005]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שנשברה השדרה ונפסק חוט השדרה.","\u0003אמר רב נחמן: בית הרחם אין בו משום ריסוקי אברים,\u0004 אין חוששים שנתרסקו איבריו של הוולד בלידה, ושמא טריפה הוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן, תניא דמסייע לך\u0004 \u0005[שנויה ברייתא שמסייעת לך]:\u0006 ששנינו, \u0003תינוק בן יום אחד\u0004"],["\u0003מטמא בזיבה,\u0004 אם יצא ממנו זוב. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003יש בו\u0004 בבית הרחם \u0003משום ריסוקי אברים, איקרי\u0004 \u0005[נקרא]\u0006 \u0003כאן\u0004 הדבר מה שדרשו חכמים: \"זב \u0003מבשרו\"\u0004 (ויקרא טו, ב) — \u0003ולא מחמת אונסו,\u0004 שאם אירע לאדם אונס, כגון שנפל ונחלה וראה זוב — אינו מיטמא בזיבה. ואף תינוק זה שנתמעך בלידה עד שחוששים לריסוק איברים, אף שראה זוב — לא ייטמא! אלא מכאן שאין חוששים לכך.","ודוחים: יש לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שיצא דרך דופן\u0004 הבטן, שהוציאו את הוולד בניתוח, ולא יצא בדוחק דרך פתח הרחם.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003עגל שנולד ביום טוב\u0004 — \u0003שוחטין אותו\u0004 ואוכלים אותו \u0003ביום טוב,\u0004 והואיל ואין משהים אותו מעת לעת, כדין נפולה, משמע שאין חוששים שמא נתרסקו איבריו בלידה! ודוחים: יש לומר כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כגון שיצא דרך דופן.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא אחרת: \u0003ושוין, שאם נולד\u0004 בכור בהמה ביום טוב, \u0003הוא ומומו עמו,\u0004 שנולד בעל מום — \u0003שזה\u0004 נחשב \u0003מן המוכן,\u0004 כלומר, אינו מוקצה, ושוחטים אותו ביום טוב עצמו. הרי שאין צריך לשהות מעת לעת, ואין חוששים שנתרסקו איבריו בלידה! \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שיצא דרך דופן,\u0004 אם יצא \u0003דרך דופן מי\u0004 \u0005[האם]\u0006 \u0003קדוש\u0004 הוא בבכורה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: מודה היה ר' שמעון לענין\u0004 בכור ושאר \u0003קדשים\u0004 \u0003ש\u0004יוצא דופן \u0003אינו קדוש!\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 בוולד \u0003שהפריס על גבי קרקע,\u0004 שלאחר שנולד נעץ פרסותיו בקרקע ונעמד, ובמקרה זה רואים בבירור שלא נתרסקו איבריו.","\u0003ואמר רב נחמן:\u0004 מה שמפילים את הבהמה ב\u0003בית המטבחים\u0004 לצורך שחיטה — \u0003אין בו משום ריסוקי אברים.\u0004","וכן מסופר, \u0003ההוא תורא דנפל\u0004 \u0005[שור אחד שנפל]\u0006 בבית המטבחיים, \u0003ואישתמע קל נגיחותיה\u0004 \u0005[ונשמע קול גניחותיו]\u0006 מחמת המכה, ולמרות זאת \u0003על\u0004 \u0005[נכנס]\u0006 \u0003רב יצחק בר שמואל בר מרתא שקל משופרי שופרי\u0004 \u0005[לקח מהיפה יפה שבו],\u0006 ומכאן מוכח שלא חשש לטריפה. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003מנא לך הא\u0004 \u0005[מנין לך דבר זה]\u0006 שאין לחשוש לכך? \u0003אמר להו\u0004 \u0005[להם],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב:\u0004 כאשר מפילים את השור, \u0003צפרניו\u0004 הוא \u0003נועץ\u0004 בקרקע \u0003עד שמגיע לארץ,\u0004 ולכן אין חוששים שנפל נפילה קשה.","\u0003אמר רב יהודה אמר רב:\u0004 בהמה שנפלה ו\u0003עמדה\u0004 — \u0003אינה צריכה\u0004 המתנה \u0003מעת לעת\u0004 קודם שישחטוה, לראות אם היא חיה, כפי שנאמר במשנה (להלן נו,ב). אבל \u0003בדיקה\u0004 לאחר שחיטה, שמא היה איזה שבר בבהמה שעושה אותה טריפה — \u0003ודאי בעיא\u0004 \u0005[צריכה].\u0006 אבל אם לא רק נעמדה, אלא גם \u0003הלכה\u0004 אחר נפילה — \u0003אינה צריכה\u0004 אף \u0003בדיקה.\u0004 \u0003רב חייא בר אשי אמר: אחת זו ואחת זו,\u0004 גם זו שהלכה — \u0003צריכה בדיקה.\u0004","\u0003אמר רב ירמיה בר אחא אמר רב: פשטה ידה לעמוד, אף על פי שלא עמדה\u0004 ממש — הרי זו כאילו עמדה, ואינה צריכה שהייה מעת לעת, אלא די לה בבדיקה. \u0003עקרה רגלה להלך אף על פי שלא הלכה\u0004 — הרי זה כאילו הלכה, ואינה צריכה בדיקה (כשיטת רב). \u0003ורב חסדא אמר:\u0004 אפילו לא פשטה ידה לעמוד, אלא \u0003ניערה\u0004 (ננערה, עשתה מאמץ) \u0003לעמוד,\u0004 ו\u0003אף על פי שלא עמדה\u0004 — כאילו עמדה, ואינה צריכה שהייה מעת לעת.","ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה היא]:\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003נפלה\u0004 הבהמה \u0003מן הגג בדלא ידעה\u0004 \u0005[בלי שידעה]\u0006 שהיא עומדת ליפול או לקפוץ, \u0003ועמדה ולא הלכה\u0004 — \u0003צריכה בדיקה, ואינה צריכה\u0004 שהייה \u0003מעת לעת. ואם הלכה\u0004 — \u0003אפילו בדיקה נמי לא\u0004 \u0005[גם כן אינה]\u0006 \u0003צריכה.\u0004","\u0003אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב דימי מנהרדעא: נפולה שאמרו\u0004 שצריכה בדיקה — \u0003צריכה בדיקה כנגד בני מעיים,\u0004 באזור הבטן, שמא ניקב או נקרע אחד מן האיברים, והיא טריפה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא, הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003רב פפא: צריכה בדיקה כנגד בית החלל כולו,\u0004 כלומר, מכל הצדדים, שמא נשברו הצלעות, או נשברה השדרה ונפסק חוט השדרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הונא מר בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003רב נחמיה לרב אשי:\u0004 כשבודקים את איברי הבהמה לאחר שנפלה, \u0003סימנין,\u0004 הקנה והוושט, \u0003מאי\u0004 \u0005[מהו]\u0006 דינם, האם צריכים הם בדיקה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סימנין קשין\u0004 (עמידים) \u0003הן אצל נפילה,\u0004 ואין לחשוש לכך.","ובדיני נפילה בעוף, \u0003אמר רב יהודה אמר שמואל: עוף ש\u0004נפל ו\u0003נחבט על פני המים, כיון ששט\u0004 במים כ\u0003מלא קומתו\u0004 — \u0003דיו\u0004 כדי להוכיח שלא נתרסקו איבריו, וכדין בהמה שהלכה. \u0003ולא אמרן\u0004 \u0005[ולא אמרנו]\u0006 \u0003אלא\u0004 ששט \u0003ממטה למעלה,\u0004 כנגד כיוון הזרם, \u0003אבל\u0004 שט \u0003מלמעלה למטה\u0004 בכיוון הזרם — שמא \u0003מיא הוא דאשפלו\u0004 \u0005[המים הם שהורידו\u0006 והוליכו אותו\u0005],\u0006 וצריך בדיקה. \u0003ואי מיא קיימי\u0004 \u0005[ואם המים עומדים],\u0006 כגון באגם — \u0003לית לן בה\u0004 \u0005[אין לנו בכך חשש],\u0006 משום שרואים שהוא שוחה בעצמו. \u0003ואי שדא ציבי וקדמיה\u0004 \u0005[ואם היו מושלכים שם קיסמים בנהר והקדים אותם\u0006 העוף בשחייתו\u0005]\u0006 — \u0003הא קדמיה\u0004 \u0005[הרי הקדים אותם],\u0006 ורואים שהוא שוחה מעצמו.","נפל העוף על \u0003גלימא\u0004 (בגד) פרוש על גבי עמודים, אם הוא \u0003מתיח\u0004 \u0005[מתוח]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 לריסוק איברים מחמת החבטה, נפל על בגד \u0003דלא מתיח\u0004 \u0005[שאינו מתוח]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006 היה הבגד שנפל עליו העוף \u0003עוף ומעופף\u0004 \u0005[מקופל]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שאינו נמתח יפה. נפל העוף על \u0003איזלא ומקרבי קיטרי\u0004 \u0005[רשת\u0006 פרושה באויר \u0005שקרובים הקשרים]\u0006 שבה זה לזה — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שנחבט בהם ונתרסקו איבריו, \u0003לא מקרבי קיטרי\u0004 \u0005[אין הקשרים קרובים]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","נפל העוף על \u0003כיתנא דעביד בטוני\u0004 \u0005[פשתן שעשוי בחבילות]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 מפני שהוא קשה. אם נפל \u0003דהאי גיסא ודהאי גיסא\u0004 \u0005[מצד זה ומצד זה],\u0006 על צידי החבילה — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שהוא מתגלגל, והחבטה אינה כה חזקה. נפל על \u0003אסורייתא\u0004 \u0005[חבילות קנים]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006 נפל על \u0003כיתנא דדייק ונפיץ\u0004 \u0005[פשתן שנידוק,\u0006 שנכתש כדי להפריד את שברי הגבעולים מן הסיבים, \u0005ונופץ,\u0006 שעבר סירוק כדי להסיר את הפסולת הדבוקה בסיבים\u0005]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שאינו קשה. נפל על פשתן \u0003דייק ולא נפיץ\u0004 \u0005[\u0006ש\u0005נידוק ולא נופץ]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 בגלל שברי הגבעולים הדבוקים בו. נפל על פשתן \u0003דעביד ביזרי\u0004 \u0005[שעשוי אגודות],\u0006 לאחר שנידוק ונופץ, \u0003כיון דאיכא ביה קטרי\u0004 \u0005[שיש בו קשרים]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 לריסוק איברים. אם נפל העוף על \u0003דקתא\u0004 \u0005[נעורת הפשתן],\u0006 שברי הגבעולים שהופרדו ממנו על ידי הסירוק — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006 אבל אם נפל על ערימת \u0003דקדקתא\u0004 \u0005[נעורת דקה מאד]\u0006 הנופלת מן הנעורת — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 מפני שהיא רכה.","נפל העוף על \u0003נברא\u0004 \u0005[הסיב הגדל סביב הדקל]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 על \u0003תימחתא\u0004 \u0005[קליפה דקל שנחתכה לרצועות]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006 נפל על \u0003קיטמא נהילא\u0004 \u0005[אפר מנופה]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 מפני שהוא נכבש ונעשה קשה. נפל על אפר \u0003לא נהילא\u0004 \u0005[לא מנופה]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 מפני שהוא רך ומתפזר בשעת הנפילה."],["נפל עוף על \u0003חול הדק\u0004 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 לריסוק איברים, מפני שכשהעוף נופל עליו הוא מחליק לצדדים, וכך נמנעת חבטה חזקה. אבל נפל על \u0003חול הגס\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 בגלל האבנים הגדולות שמעורבות בו. נפל העוף על \u0003אבק דרכים\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 לריסוק איברים, מפני שאבק דרכים נכבש ומתקשה. נפל על \u0003תיבנא ועביד בזגא\u0004 \u0005[תבן,\u0006 קש \u0005שעשוי בחבילה]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים],\u0006 מפני שהוא מהודק וקשה. \u0003לא עביד בזגא\u0004 \u0005[אינו עשוי בחבילה]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","נפל על \u0003חיטי וכל דמינייהו\u0004 \u0005[חיטים וכל\u0006 מה \u0005שממינם],\u0006 כגון כוסמין ושיפון שהם קשים — \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 וכן אם נפל על \u0003שערי וכל דמינייהו\u0004 \u0005[שעורים וכל שממינם]\u0006 כגון שבולת שועל — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006 \u0003כל מיני קטניות\u0004 שנפל עליהם עוף — \u0003אין בהם משום ריסוקי אברים,\u0004 מפני שבשעה שנופל עליהם העוף הם מחליקים זה מזה, בגלל צורתם העגולה, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מן רוביא\u0004 \u0005[תלתן,\u0006 חילבה\u0005].\u0006 \u0003חימצי\u0004 \u0005[אפונה]\u0006 — \u0003אין בו משום ריסוק אברים,\u0004 אבל \u0003חפצי\u0004 \u0005[חומוס]\u0006 — \u0003יש בו משום ריסוק אברים. כללא דמלתא\u0004 \u0005[כללו של דבר]:\u0006 \u0003כל מידי דמשריק\u0004 \u0005[דבר שמחליק]\u0006 לצדדים כשהעוף נופל עליו — \u0003אין בו משום ריסוק אברים, לא משריק\u0004 \u0005[אינו מחליק]\u0006 — \u0003יש בו משום ריסוק אברים.\u0004","אם נפל העוף על הקרקע כשהוא מחובר ל\u0003דבוק,\u0004 לוח מצופה דבק שמניחים כמלכודת, וכשהעוף נדבק אליו ומנסה לעוף הוא נופל עם הלוח — \u0003רב אשי שרי\u0004 \u0005[התיר],\u0006 \u0003אמימר אסר.\u0004 ומפרטים, אם נדבק העוף ללוח \u0003בחד גפא\u0004 \u0005[בכנף אחת]\u0006 — \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חולקים שהוא מותר],\u0006 מפני שהעוף פורח קצת בכנף אחת, ואינו נופל בחבטה. \u0003כי פליגי\u0004 \u0005[כאשר הם חלוקים]\u0006 הרי זה כשנדבק \u0003בתרי גפי\u0004 \u0005[בשתי כנפיים].\u0006 \u0003מאן דאסר אמר לך\u0004 \u0005[מי שאוסר אומר לך]:\u0006 \u0003היכי ניקום\u0004 \u0005[איך יחזיק\u0006 העוף \u0005מעמד]\u0006 שלא להיחבט חבטה גמורה בקרקע? \u0003ומאן דשרי אמר לך\u0004 \u0005[ומי שמתיר אומר לך]:\u0006 \u0003אפשר דניקום אעיקבי דגפי\u0004 \u0005[יכול להחזיק מעמד בקצות הכנפיים].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 לשון אחרת: \u0003בתרי גפי כולי עלמא לא פליגי דאסיר\u0004 \u0005[\u0006אם נדבק \u0005בשתי כנפיים הכל אינם חלוקים שהוא אסור],\u0006 שאין בידו להמעיט את עוצמת החבטה, \u0003כי פליגי בחד גפא\u0004 \u0005[כאשר הם חלוקים הרי זה\u0006 כשנדבק \u0005בכנף אחת],\u0006 \u0003מאן דשרי אמר לך\u0004 \u0005[מי שמתיר אומר לך]:\u0006 \u0003אפשר דפרח בחד גפא\u0004 \u0005[יכול הוא לעוף בכנף אחת],\u0006 \u0003ומאן דאסר\u0004 \u0005[ומי שאסר]:\u0006 \u0003כיון דבהאי לא מצי פרח בהאי נמי לא מצי פרח\u0004 \u0005[כיון שב\u0006כנף \u0005זו אינו יכול לעוף, בזו גם כן אינו יכול לפרוח].\u0006 \u0003והילכתא\u0004 \u0005[והלכה היא]:\u0006 נדבק \u0003בתרי גפי אסיר\u0004 \u0005[בשתי כנפיים אסור],\u0006 \u0003בחד גפא שרי\u0004 \u0005[בכנף אחת מותר].\u0006","שנינו במשנה: \u0003נשתברו רוב צלעותיה\u0004 של בהמה — הריהי טריפה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אלו הן רוב צלעות\u0004 לענין זה: \u0003שש מכאן ושש מכאן,\u0004 מכל צד של השדרה, שהוא רוב של עשרים ושתים צלעות, אחת עשרה לכל צד, \u0003או אחת עשרה מכאן ואחת מכאן.\u0004","\u0003אמר זעירי: ו\u0004היא טריפה כאשר נשברו הצלעות \u0003מחציין כלפי שדרה,\u0004 ולא בחצי המרוחק מן השדרה. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ו\u0004מדובר כאן \u0003ב\u0004אותן עשרים ושתים \u0003צלעות גדולות שיש בהן מוח,\u0004 שאם נשברו הרי זו טריפה, ולא \u0003בצלעות הקטנות.\u0004","\u0003אמר עולא, בן זכאי אמר:\u0004 אם \u0003נעקרו\u0004 הצלעות מחיבורן בשדרה — די אם היה זה \u0003ברוב\u0004 הצלעות של \u0003צד אחד,\u0004 כלומר, אם נעקרו שש צלעות בסך הכל, כדי לעשות טריפה. ודווקא אם \u0003נשתברו\u0004 הצלעות — שנינו שהיא טריפה רק \u0003ברוב שני צדדין,\u0004 כלומר, שיישברו שתים עשרה צלעות. \u0003ר' יוחנן אמר: בין נעקרו, בין נשתברו\u0004 — אינה נעשית טריפה אלא \u0003ברוב שני צדדין.\u0004","בענין זה מביאים, \u0003אמר רב: נעקרה צלע וחוליא\u0004 שהיא מחוברת אליה \u0003עמה,\u0004 שנעקרה מן החוליות שלפניה ושלאחריה — הרי זו \u0003טרפה,\u0004 למרות שלא נפסק חוט השדרה. \u0003אמרי ליה\u0004 \u0005[אמרו לו,\u0006 שאלוהו\u0005]\u0006 \u0003רב כהנא ורב אסי לרב: נעקרה צלע מכאן\u0004 מצד אחד של החוליה, \u0003וצלע מכאן\u0004 מצידה השני, \u0003וחוליא\u0004 עצמה \u0003קיימת\u0004 במקומה, \u0003מהו?\u0004 האם היא טריפה? \u0003אמר להו\u0004 \u0005[להם]\u0006 בתמיהה: \u0003גיסטרא קאמריתו\u0004 \u0005[חתוכה לשנים אתם אומרים]?!\u0006 בהמה כזו נחשבת כמתה, וכיצד אתם שואלים האם היא טריפה!","ומתקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נמי\u0004 \u0005[גם כן]\u0006 שאמר שאם נעקרה צלע וחוליה עמה טריפה היא, \u0003גיסטרא קאמר\u0004 \u0005[חתוכה לשתים אמר],\u0006 שכיון שנעקרה חוליא וצלע שעמה — הצלע השניה נופלת מאליה, ומדוע תמה עליהם? ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 שהיא טריפה — הרי זה כשנעקרה \u0003צלע בלא חוליא.\u0004","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003צלע וחוליא\u0004 עמה \u0003קאמר\u0004 \u0005[אמר]!\u0006 ומשיבים: כוונתו היתה \u0003ל\u0004\u0003צלע וחצי חוליא,\u0004 כלומר, עם מקצת מן החוליא שאליו היא מחוברת, אבל הצלע שכנגדה מחוברת לחוליא כראוי.","ותמהים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003רב כהנא ורב אסי,\u0004 כשנעקרה \u0003צלע\u0004 מכאן ומכאן \u0003בלא חוליא אמרי\u0004 \u0005[אמרו,\u0006 שאלו\u0005]\u0006 את רב האם היא טריפה, \u0003ו\u0004על כך \u0003אמר להו\u0004 \u0005[להם]\u0006 בתמיהה: \u0003גיסטרא קאמריתו\u0004 \u0005[חתוכה לשתים אומרים אתם],\u0006 שנבילה היא? וכיצד ניתן לומר כן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא, בן זכאי אמר: נעקרו\u0004 צלעות \u0003ברוב צד אחד,\u0004 כלומר, רק אם נעקרו שש צלעות — הרי זו טריפה, \u0003נשתברו\u0004 — \u0003ברוב שני צדדין.\u0004 הרי שאם נעקרה צלע אחת בלבד אינה טריפה!","ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 רב: \u0003התם\u0004 \u0005[שם]\u0006 שצריך שייעקרו שש צלעות כדי לעשותה טריפה, מדובר בצלעות שנעקרו \u0003זה שלא כנגד זה. הכא\u0004 \u0005[כאן]\u0006 שאמר שאם נעקרו שתים הרי זו נבילה — כשנעקרו שתים \u0003זה כנגד זה,\u0004 משני צידיה של אותה חוליא.","ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן,\u0004 אינה טריפה עד שייעקרו \u0003ברוב שני צדדין, וברוב שני צדדין אי אפשר דלא קיימא חד מינייהו\u0004 \u0005[שלא תעמוד צלע אחת מהן]\u0006 \u0003זה כנגד זה,\u0004 וטריפה היא ולא נבילה!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בדברי ר' יוחנן, מדובר שנעקרה ה\u0003בוכנא בלא אסיתא\u0004 \u0005[העלי בלי המכתש],\u0006 כלומר, הצלע עצמה, בלי הגומה שהיא יושבת בתוכה, ואם נעקרה צלע מכאן ומכאן באופן זה — הרי זו טריפה. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 כששאלוהו רב כהנא ורב אסי אם היא טריפה ואמר שהיא נבילה, מדובר שנעקרו \u0003בוכנא ואסיתא\u0004 \u0005[העלי והמכתשת עמו],\u0006 כלומר, צלע ומקצת חוליא מכאן ומכאן.","ומתקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדוע הוצרכו לשאול את רב על כך? \u0003היינו\u0004 \u0005[זהו]\u0006 הדין שאמר \u0003רב\u0004 מתחילה, שאם ניטלה צלע אחת ומקצת חוליא עמה הריהי טריפה, וכל שכן כשניטלה צלע מכאן ומכאן עם מקצת חוליא! ומשיבים: רב כהנא ורב אסי \u0003לא שמיע להו\u0004 \u0005[לא שמעו]\u0006 מה שאמר \u0003רב,\u0004 ולכן שאלוהו.","ושואלים: אם כן, \u0003וליבעו מיניה\u0004 \u0005[ושישאלו אותו]\u0006 את רב, \u0003כ\u0004דברי \u0003רב\u0004 עצמו — במקרה שניטלה צלע אחת וחצי חוליא! ומשיבים, \u0003סברי\u0004 \u0005[סבורים היו]:\u0006 \u0003ליבעי מיניה חדא דפריש לן תרתי\u0004 \u0005[נשאל אותו שאלה אחת שיפרש לנו\u0006 על ידה \u0005שתים].\u0006 \u0003דאי בעינן מיניה חדא\u0004 \u0005[ש\u0006הרי \u0005אם נשאל אותו\u0006 תחילה \u0005בצלע אחת]\u0006 שנעקרה עם מקצת החוליא — \u0003הניחא אי אמר לן\u0004 \u0005[זה\u0006 יהיה \u0005נוח אם יאמר לנו]\u0006 שהיא \u0003טרפה,\u0004 שאז נבין מכך כי \u0003כל שכן\u0004 כשנעקרו \u0003תרתי\u0004 \u0005[שתיים]\u0006 עם מקצת חוליא מכאן ומכאן, שהיא טריפה. אבל \u0003אי אמר לן\u0004 \u0005[אם יאמר לנו]\u0006 כשנעקרה אחת היא \u0003כשרה\u0004 — \u0003אכתי תרתי קא מיבעיא לן\u0004 \u0005[עדיין בשתים תישאל לנו השאלה].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם זהו השיקול, \u0003השתא נמי דקא בעי מיניה תרתי\u0004 \u0005[עכשיו גם כן, ששאלו ממנו\u0006 על \u0005שתים],\u0006 אין זה בטוח שיקבלו תשובה על שני המקרים, שכן \u0003הניחא אי אמר להו\u0004 \u0005[זה נוח אם יאמר להם]\u0006 שאם נעקרו שתים היא \u0003כשרה\u0004 — \u0003כל שכן\u0004 אם נעקרה \u0003חדא\u0004 \u0005[אחת].\u0006 אבל \u0003אי אמר להו\u0004 \u0005[אם יאמר להם]\u0006 בשתים \u0003טרפה\u0004 — \u0003אכתי חדא מיבעיא להו\u0004 \u0005[עדיין\u0006 ב\u0005אחת תישאל להם],\u0006 שמא היא כשרה!","ומשיבים, \u0003סברי\u0004 \u0005[סבורים\u0006 היו\u0005]:\u0006 \u0003אם כן,\u0004 אם לדעתו בנעקרה אחת טריפה היא, לא יהיה להם צורך לחזור ולשאול על כך, מפני שיקבלו על כך תשובה כשישאלוהו על שתים, שכן \u0003מירתח קא רתח\u0004 \u0005[יכעס\u0006 ויאמר\u0005]:\u0006 \u0003חדא טרפה תרתי מיבעיא\u0004 \u0005[\u0006והרי בצלע \u0005אחת\u0006 שנעקרה \u0005טריפה היא,\u0006 על \u0005שתים אתם שואלים]?!\u0006","ומקשים: \u0003והא קא אמרי ליה ולא רתח\u0004 \u0005[והרי אמרו לו\u0006 שאלה \u0005זו,\u0006 מה דין שתי חוליות שנעקרו, \u0005ולא כעס]!\u0006 ומשיבים: \u0003כיון דקאמר להו\u0004 \u0005[שאמר להם]\u0006 בתמיהה \u0003\"גיסטרא קאמריתו\"\u0004 \u0005[חתוכה לשתים אתם אומרים]\u0006 — \u0003היינו ריתחיה\u0004 \u0005[זהו כעסו],\u0006 שכוונתו לומר: אין כלל מקום לשאלתכם, שזו נבילה היא, אלא רק אם נעקרה אחת הרי זו טריפה.","\u0003אמר רבה בר רב שילא אמר רב מתנא אמר שמואל: נעקרה צלע מעיקרה, ו\u0004כן \u0003גולגולת שנחבסה\u0004 (נמעכה) \u0003ברובה, ו\u0004כן \u0003בשר החופה את רוב הכרס\u0004 שנחתך \u0003ברובו\u0004 — הרי זו \u0003טרפה.\u0004","ושואלים: \u0003נעקרה צלע מעיקרה\u0004 — \u0003טרפה? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים \u0005על כך]\u0006 ממה ששנינו:"],["\u0003כמה חסרון\u0004 יהיה \u0003בשדרה\u0004 של אדם מת, ולא תטמא באוהל כשדרה שלמה של מת? \u0003בית שמאי אומרים:\u0004 אם חסרות לה \u0003שתי חוליות, ובית הלל אומרים: חוליא אחת. ואמר רב יהודה אמר שמואל: וכן\u0004 הם חלוקים \u0003ל\u0004ענין \u0003טרפה,\u0004 שלדעת בית שמאי, רק אם נחסרו שתי חוליות הרי זו טריפה, ולדעת בית הלל (שהלכה כמותם) — אפילו אם נחסרה חוליא אחת. ומשמע שדווקא אם נחסרה חוליא טריפה היא, אבל אם רק נעקרה צלע מן החוליא — כשרה, בניגוד למה שנאמר כאן בשמו!","ומשיבים: אין כאן סתירה, מפני שמדובר בשני מקרים שונים, \u0003הכא\u0004 \u0005[כאן]\u0006 שאמר שמואל שאם נעקרה צלע מעיקרה טריפה — מדובר שנעקרה \u0003צלע בלא\u0004 ה\u0003חוליא\u0004 שלה, \u0003התם\u0004 \u0005[שם],\u0006 במחלוקת בית שמאי ובית הלל, מדובר שנחסרה \u0003חוליא בלא צלע,\u0004 וממילא אין לדייק מכך שאם נעקרה הצלע אינה טריפה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003צלע בלא חוליא\u0004 — \u0003משכחת לה\u0004 \u0005[מוצא אתה],\u0006 שהצלע נעקרת מן החוליא, \u0003אלא חוליא בלא צלע\u0004 — \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006 ומשיבים: \u0003בשילהי כפלי\u0004 \u0005[בסוף הכסלים,\u0006 המתניים\u0005],\u0006 שם יש חוליות בלא צלעות.","על דברי שמואל, שבית שמאי ובית הלל נחלקו בחסרון חוליא גם לענין טריפה, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אושעיא: ולתנייה\u0004 \u0005[ושישנה]\u0006 התנא הלכה זו \u0003גבי\u0004 \u0005[אצל]\u0006 רשימת \u0003קולי בית שמאי וחומרי בית הלל\u0004 ששנינו במסכת עדויות, שהרי בית הלל מחמירים ומטריפים אפילו בחסרון חוליא אחת, ואילו לדעת בית שמאי אינה טריפה עד שיחסרו שתים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: כי איתשל\u0004 \u0005[כאשר נשאלה\u0006 שאלה \u0005זו]\u0006 שדנו בה בית שמאי ובית הלל — \u0003לענין טומאה איתשיל\u0004 \u0005[נשאלה],\u0006 \u0003דהוו להו\u0004 \u0005[שנמצאים]\u0006 \u0003בית שמאי\u0004 הולכים בענין זה \u0003לחומרא,\u0004 ומה שאמר רב יהודה בשם שמואל שמחלוקתם נוגעת גם לענין טריפה, לא נאמר דבר זה במפורש במשנה או בברייתא, ולכן לא הוזכר באותה רשימה. ושבים למה שאמר שמואל ש","\u0003גולגולת שנחבסה\u0004 (נמעכה) \u0003ברובה\u0004 — טריפה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה\u0004 האם רובה כוונתו ל\u0003רוב גובהה, או\u0004 ל\u0003רוב היקיפה?\u0004 שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","עוד אמר שמואל: \u0003ובשר החופה\u0004 (המכסה) \u0003רוב הכרס\u0004 מלמטה \u0003ברובו\u0004 — טריפה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 האם שמואל דיבר \u0003ברוב קרוע,\u0004 שאם יש קרע לרוב אורכו הרי זו טריפה, וכל שכן אם ניטל רובו, \u0003או\u0004 דווקא \u0003ברוב נטול,\u0004 אבל רוב קרוע אינו עושה טריפה?","ומשיבים: \u0003תפשוט ליה מדתנן\u0004 \u0005[תפתור אותה\u0006 את השאלה, \u0005ממה ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כרס הפנימית שניקבה, או שנקרע רוב החיצונה\u0004 טריפה היא; \u0003ואמרי במערבא משמיה\u0004 \u0005[ואמרו בארץ ישראל משמו]\u0006 של \u0003ר' יוסי בר' חנינא\u0004 בפירוש הדברים: \u0003כל הכרס כולו זו היא כרס הפנימי, ואי זהו כרס החיצונה\u0004 שאם נקרעה ברובה הרי זו טריפה? זהו \u0003בשר החופה את רוב הכרס.\u0004 הרי שדי שייקרע בשר זה ברובו כדי לעשות טריפה.","ודוחים: \u0003מידי הוא טעמא\u0004 \u0005[כלום היא הטעם],\u0006 כלומר, הרי לא נשאלה כאן השאלה \u0003אלא\u0004 כדי \u0003ל\u0004ברר את דעת \u0003שמואל,\u0004 והרי שמואל עצמו אינו סבור כן, ש\u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יעקב בר נחמני אמר שמואל:\u0004 כרס החיצונה ששנינו במשנה אינו בשר החופה את רוב הכרס, אלא הוא \u0003מקום\u0004 בכרס עצמה \u0003שאין בו מילת\u0004 (מעין צמר רך, המכסה את דופן הכרס), ואם כן אין להביא ראיה לשיטתו ממשנתנו.","שנינו במשנה: \u0003ודרוסת הזאב,\u0004 שנעץ בה ציפורניו — טריפה היא. \u0003אמר רב יהודה אמר רב:\u0004 דרוסה \u0003בבהמה\u0004 — הריהי טריפה אם נדרסה \u0003מן הזאב ולמעלה,\u0004 על ידי זאב או חיות גדולות יותר ממנו, כגון אריה. \u0003ובעופות\u0004 — אם נדרסו \u0003מן הנץ ולמעלה.\u0004","ושואלים, מה שאמר רב: בבהמה מן הזאב ולמעלה, \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 הוא בא? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003חתול\u0004 שדרס בהמה — הלוא כבר \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003ודרוסת הזאב,\u0004 ומשמע: ולא חתול! \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 רב, שלדעת משנתנו \u0003זאב ב\u0004בהמה \u0003גסה נמי דריס\u0004 \u0005[גם כן דורס],\u0006 ולא בא למעט חתול — דבר זה אינך יכול לומר, \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: דרוסת הזאב\u0004 היא דווקא \u0003ב\u0004בהמה \u0003דקה,\u0004 כגון כבשים, \u0003ודרוסת ארי\u0004 \u0003ב\u0004בהמה \u0003גסה\u0004 כגון שוורים!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' יהודה מפלג פליג\u0004 \u0005[חולק הוא],\u0006 ולדעת חכמים זאב עושה דרוסה גם בבהמה גסה, וכמותם פסק רב — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' בנימין בר יפת אמר ר' אלעא: לא בא ר' יהודה\u0004 במשנתנו \u0003אלא לפרש דברי חכמים!\u0004","ודוחים: \u0003גברא אגברא קא רמית\u0004 \u0005[מאדם על אדם אתה מקשה]?\u0006 יתכן שר' אלעא סבור שהוא בא לפרש, ורב סבור שבא לחלוק! \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם\u0004 הכל סבורים שדרוסת זאב היא דווקא בבהמה דקה, ודברי רב באו \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חתול\u0004 שדרס בהמה דקה. ויש בכך חידוש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 מה ששנה התנא: ודרוסת הזאב בדקה — \u0003אורחא דמלתא קתני\u0004 \u0005[דרכו של עולם הוא שונה],\u0006 שדרכו של זאב לדרוס, ובאמת גם חתול עושה דרוסה בבהמה דקה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב שזאב דווקא.","\u0003אמר רב עמרם אמר רב חסדא: דרוסת חתול ונמייה\u0004 הריהי טריפה \u0003בגדיים וטלאים,\u0004 הקטנים שבבהמה הדקה, ו\u0003דרוסת חולדה\u0004 הריהי טריפה \u0003בעופות\u0004 דווקא. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003דרוסת חתול, נץ ונמייה\u0004 אינה טריפה \u0003עד שתינקב לחלל\u0004 הגוף, שינקבו בציפורניים את המעיים ושאר אברים, שנקב בהם עושה טריפה. ונדייק: \u0003אבל דרוסה\u0004 ממש, שעושה טריפה בעצם הדריסה והטלת הארס, \u0003לית להו\u0004 \u0005[אין להם]!\u0006","ותחילה תוהים על מה ששנינו בברייתא זו: \u0003ותסברא\u0004 \u0005[וסבור אתה]\u0006 ש\u0003נץ לא דריס\u0004 \u0005[אינו דורס]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ודרוסת הנץ!\u0004 ודוחים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה]:\u0006 \u0003כאן\u0004 ששנינו שנץ עושה דרוסה — הרי זה \u0003בעופות,\u0004 \u0003כאן\u0004 ששנינו בברייתא שאינו עושה דרוסה — \u0003בגדיים וטלאים.\u0004","ואומרים: \u0003מכל מקום, לרב חסדא\u0004 שאמר שיש דרוסה לחתול בגדיים וטלאים, \u0003קשיא\u0004 \u0005[קשה]\u0006 הברייתא, שדייקנו ממנה שאינו עושה דרוסה! ומשיבים: \u0003הוא\u0004 רב חסדא ש\u0003אמר כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 החכם \u0003בריבי אומר: לא אמרו\u0004 ש\u0003אין דרוסה\u0004 לחתול \u0003אלא במקום שאין מצילין\u0004 לגדי, \u0003אבל במקום שיש מצילין,\u0004 שמנסים להציל את הגדי מידו — \u0003יש דרוסה,\u0004 שהוא משתולל ומטיל ארס, ובמקרה זה דיבר רב חסדא.","ומקשים: \u0003ובמקום שאין מצילין אין\u0004 החתול עושה \u0003דרוסה? והא ההיא תרנגולת דהואי בי\u0004 \u0005[והרי אותה תרנגולת שהיתה בביתו]\u0006 של \u0003רב כהנא, דרהט חתול בתרה ועל לאידרונא\u0004 \u0005[שרץ חתול אחריה\u0006 לטורפה \u0005ונכנס\u0006 החתול \u0005לחדר קטן],\u0006 \u0003ואיתחיד דשא באפיה, ומחייה לדשא בסיחופיה\u0004 \u0005[ונסגרה הדלת בפניו, והיכה\u0006 מרוב \u0005כעס\u0006 על \u0005הדלת בכפו],\u0006 \u0003ואשתכח עלה חמשה קורטי דמא\u0004 \u0005[ונמצא עליה חמש טיפות דם,\u0006 ארס\u0005],\u0006 משמע שיש דרוסה גם במקום שאין מצילים! ומשיבים:","\u0003הצלת עצמה\u0004 של החתול \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003כהצלת אחרים דמי\u0004 \u0005[נחשבת],\u0006 שהיא חשה מאויימת. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 ששנו בברייתא שאין חתול עושה דרוסה כלל, כיצד הם מסבירים מעשה זה? ומשיבים: \u0003זיהרא אית ליה, ולא קלי זיהריה\u0004 \u0005[ארס יש לו,\u0006 לחתול, \u0005ו\u0006אולם \u0005אין הארס שלו שורף]\u0006 עד כדי לעשות טריפה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הסוגיא באופן אחר: לאחר שהקשו על רב חסדא, שאמר שחתול עושה דרוסה בגדיים וטליים, ממה שדייקנו מן הברייתא שאינו עושה דרוסה, השיבו כי \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כדעת מי\u0006 היא\u0005]?\u0006 שיטת \u0003בריבי, היא, דתניא\u0004 \u0005[ששנויה ברייתא],\u0006 \u0003בריבי אומר: לא אמרו\u0004 ש\u0003יש דרוסה\u0004 לחתול \u0003אלא במקום שיש מצילין\u0004 לגדי מידו, \u0003אבל במקום שאין מצילין\u0004 — \u0003אין דרוסה.\u0004 ואילו רב חסדא פוסק כשיטת חכמים החולקים עליו, וסבורים כי גם כשאין מצילים — חתול עושה דרוסה.","ושואלים על כך: \u0003ובמקום שאין מצילין אין דרוסה? והא ההיא תרנגולת דהואי בי\u0004 \u0005[והרי אותה תרנגולת שהיתה בביתו]\u0006 של \u0003רב כהנא, דרהט חתול בתרה ועל לאידרונא\u0004 \u0005[שרץ חתול אחריה ונכנס לחדר קטן],\u0006 \u0003ואיתחיד דשא באפיה ומחייה לדשא בסיחופיה\u0004 \u0005[ונסגרה הדלת בפניו והיכה את הדלת בכפו],\u0006 \u0003ואישתכח עליה חמשה קורטי דמא\u0004 \u0005[ונמצא עליה חמישה\u0006 \u0005טיפות דם]!\u0006 והשיבו: \u0003הצלת עצמה נמי\u0004 \u0005[גם כן]\u0006 \u0003כהצלת אחרים דמיא\u0004 \u0005[נחשבת].\u0006","מסופר, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב כהנא מרב:\u0004"],["\u0003יש דרוסה לחתול או אין דרוסה לחתול? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף לחולדה,\u0004 שהיא קטנה מהחתול, \u0003יש דרוסה.\u0004 שאל אותו רב כהנא: \u0003יש דרוסה לחולדה, או אין דרוסה לחולדה? אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אף לחתול אין דרוסה.\u0004","ועוד שאל: \u0003לחתול ולחולדה, יש להן דרוסה או אין להן דרוסה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לחתול יש דרוסה, לחולדה אין דרוסה.\u0004 ומעירים: \u0003ולא קשיא\u0004 \u0005[ואין זה קשה],\u0006 אין הדברים סותרים, אלא כל תשובה מתייחסת לענין אחר.","\u0003הא דאמר ליה\u0004 \u0005[זה שאמר לו]:\u0006 \u0003אף לחולדה יש דרוסה\u0004 הוא \u0003בעופות, הא דאמר ליה\u0004 \u0005[זה שאמר לו]:\u0006 \u0003אף לחתול אין דרוסה\u0004 — \u0003באימרי רברבי\u0004 \u0005[בכבשים גדולים],\u0006 \u0003הא דאמר ליה\u0004 \u0005[זה שאמר לו]:\u0006 \u0003לחתול יש דרוסה, לחולדה אין דרוסה\u0004 — \u0003בגדיים וטלאים.\u0004","שנינו במשנה: דרוסת הנץ בעוף הדק — טריפה. ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: שאר עופות, טמאין\u0004 מלבד הנץ, \u0003יש להן\u0004 דין \u0003דרוסה,\u0004 שאם דרסו עוף הריהם עושים טריפה, \u0003או אין להן דרוסה? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הלל לרב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו של\u0005]\u0006 \u0003רב כהנא אמר: שאר עופות טמאין יש להן דרוסה.\u0004","ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ודרוסת הנץ בעוף הדק,\u0004 ומשמע שרק הנץ ולא שאר עופות! ומשיבים: \u0003דרוסת הנץ\u0004 היא אפילו \u0003בדכוותיה\u0004 \u0005[ב\u0006עוף \u0005דק\u0006 גדול \u0005כמוהו],\u0006 \u0003ואינך בדזוטרא מינייהו\u0004 \u0005[ואלו,\u0006 שאר עופות טמאים, דווקא \u0005בקטנים מהם].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003דרוסת הנץ\u0004 אפילו \u0003בדרבי מיניה\u0004 \u0005[בגדולים ממנו],\u0006 \u0003ואינך בדכוותייהו\u0004 \u0005[ואלו,\u0006 שאר עופות טמאים, \u0005ב\u0006עופות \u0005שכמותם].\u0006","\u0003אמר רב כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב שימי בר אשי: אין\u0004 דין \u0003דרוסה לשועל.\u0004 ותוהים: \u0003איני\u0004 \u0005[כן היא]!\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר, מעשה ודרס שועל רחל\u0004 (כבשה) \u0003במרחץ של בית היני, ובא מעשה\u0004 זה \u0003לפני חכמים, ואמרו: יש\u0004 כאן דין \u0003דרוסה! אמר רב ספרא: ההיא\u0004 \u0005[ההוא]\u0006 לא שועל, אלא \u0003חתול הוה\u0004 \u0005[היה].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ענין זה באופן אחר, \u0003אמר רב כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב שימי בר אשי: יש דרוסה לשועל.\u0004 ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר, מעשה ודרס שועל רחל במרחץ של בית היני, ובא מעשה לפני חכמים, ואמרו: אין דרוסה! אמר רב ספרא: ההוא\u0004 \u0005[אותו]\u0006 ששאלו עליו, \u0003כלב הוה\u0004 \u0005[היה]\u0006 ולא שועל. ובענין זה \u0003אמר רב יוסף: נקטינן\u0004 \u0005[מוחזקים אנו]:\u0006 \u0003אין דרוסה לכלב.\u0004","ובהגדרה המדוייקת של דין דרוסה \u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 \u0003אין\u0004 דין \u0003דרוסה אלא\u0004 כשדרס \u0003ביד,\u0004 ברגלים הקדמיות, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 אם דרס ב\u0003רגל,\u0004 ברגלים האחוריות, ש\u0003לא,\u0004 שאין בזה דין דרוסה. וכן \u0003אין דרוסה אלא\u0004 שדרס \u0003בצפורן, לאפוקי\u0004 \u0005[להוציא]\u0006 אם דרס ב\u0003שן\u0004 ש\u0003לא,\u0004 שאין לחיה ארס בשיניה. ועוד, \u0003אין דרוסה אלא\u0004 כשדרס \u0003מדעת, לאפוקי\u0004 \u0005[להוציא]\u0006 שנעץ ציפורניו \u0003שלא מדעת,\u0004 וכגון שנפל על הטרף, וננעצו בו ציפורניו — ש\u0003לא,\u0004 שאין בזה דין דרוסה. וכן \u0003אין דרוסה אלא\u0004 כשנעץ ציפורנו \u0003מחיים\u0004 בחיי הדורס, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 שננעצה הציפורן בטרף \u0003לאחר מיתה\u0004 של הדורס, ש","\u0003לא,\u0004 שאין בזה דין דרוסה. \u0003אמרי\u0004 \u0005[אומרים]\u0006 על כך בתמיהה: ומדוע הוצרך לומר דין זה? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003שלא מדעת אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003לא,\u0004 שאין לה דרוסה, \u0003לאחר מיתה מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 שאין לה דרוסה? ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו אלא במקרה \u0003דדריס ופסקוה לידיה\u0004 \u0005[שדרס\u0006 בעודו בחיים \u0005וחתכו את ידו]\u0006 כשהיתה נעוצה בטרף, \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 \u0003בהדי דדריס שדי זיהריה\u0004 \u0005[בתוך שהוא דורס מטיל את ארסו],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 אביי כי \u0003בהדי דשליף שדי זיהריה\u0004 \u0005[בזמן שהוא שולף את ציפורניו]\u0006 אז הוא מטיל את ארסו, והואיל וחתכו את ידו לא הספיק לעשות כן.","\u0003אמר רבה בר רב הונא אמר רב: ארי שנכנס לבין השוורים, ו\u0004לאחר מכן \u0003נמצא צפורן\u0004 תחובה \u0003בגבו של אחד מהן\u0004 — \u0003אין חוששין שמא ארי דרסו. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 כי אף ש\u0003רוב אריות דורסין ו\u0004רק \u0003מיעוטן אין דורסין,\u0004 ואם כן היה מקום לחשוש, \u0003ו\u0004אולם מוחזק בידינו ש\u0003כל הדורס\u0004 — \u0003אין צפרנו נשמטת\u0004 (נעקרת) כשהוא דורס. \u0003ו\u0004לכן \u0003זאת,\u0004 שור זה, \u0003הואיל וצפורן יושבת לו בגבו\u0004 — \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003בכותל נתחכך,\u0004 וציפורן זו היתה נעוצה בכותל.","ומקשים: \u0003אדרבה\u0004 \u0005[\u0006אמור \u0005להיפך],\u0006 אמנם \u0003רוב שוורים מתחככין\u0004 בכותל, \u0003ו\u0004רק \u0003מיעוטן אין מתחככין, ו\u0004אולם מוחזק בידינו ש\u0003כל המתחכך\u0004 — \u0003אין צפורן יושבת לו בגבו. ו\u0004לכן שור \u0003זה, הואיל וצפורן יושבת לו בגבו, אימר\u0004 \u0005[אמור]\u0006 ש\u0003ארי\u0004 שנכנס לשם \u0003דרסו!\u0004","ומשיבים: \u0003איכא למימר הכי\u0004 \u0005[אפשר לומר כך],\u0006 \u0003ואיכא למימר הכי\u0004 \u0005[ואפשר לומר כך]\u0006 — \u0003אוקי מילתא אחזקיה\u0004 \u0005[העמד את הדבר על חזקתו]\u0006 שהשור אינו טריפה, \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003ספק דרוסה; ורב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: אין חוששין לספק דרוסה.\u0004","בהמשך לדברים \u0003אמר אביי: לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין חוששים שארי דרסו, \u0003אלא\u0004 כשמצא שם \u0003צפורן\u0004 בגבו של השור, משום שהציפורן שתחובה בגבו מלמדת שלא היתה זו דריסה, שהרי כל הדורס אין ציפורנו נשמטת, \u0003אבל\u0004 אם מצא רק \u0003מקום\u0004 (נקב) של \u0003צפורן\u0004 — \u0003חוששין\u0004 שהארי שנכנס לשם דרס שור זה. \u0003ו\u0004ביחס ל\u0003צפורן\u0004 שתחובה בגבו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שמסתמכים על כך שכל הדורס אין ציפורנו נשמטת, \u0003אלא\u0004 כשהיתה הציפורן \u0003לחה,\u0004 שמורה הדבר שהיתה מחוברת כראוי לבשר, \u0003אבל\u0004 ציפורן \u0003יבשה\u0004 — \u0003עבדה דמשתמטא\u0004 \u0005[עשויה שנשמטת\u0006 מכף היד\u0005]\u0006 כשהוא דורס, ויש לחשוש לכך.","\u0003ו\u0004ביחס לציפורן \u0003לחה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 שתולים את הדבר בכך שנתחכך בכותל ולא בדריסה, \u0003אלא\u0004 כשהיתה שם ציפורן \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003אבל\u0004 אם היו \u0003תרתי ותלת\u0004 \u0005[שתים ושלוש]\u0006 ציפורניים נעוצות בגבו של השור — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 לדריסה, \u0003והוא דקיימא בדרא דסיחופיה\u0004 \u0005[שהן נמצאות בשורה,\u0006 כמו ב\u0005כפו]\u0006 של הארי.","ובענין ספק דרוסה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה זו, \u0003רב אמר: אין חוששין לספק דרוסה, ושמואל אמר: חוששין לספק דרוסה,\u0004 וצריכה בדיקה.","ומפרטים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 וגם לדעת שמואל, במקרה ש\u0003ספק על\u0004 \u0005[נכנס]\u0006 בעל החיים הדורס למקום, \u0003ספק לא על\u0004 \u0005[נכנס],\u0006 וכגון ספק אם נכנס חתול ללול תרנגולות — \u0003אימא לא על\u0004 \u0005[אמור שלא נכנס].\u0006 וכן אם ידוע שנכנס ואולם \u0003ספק\u0004 אם \u0003כלבא\u0004 \u0005[כלב]\u0006 הוא שנכנס, שאינו עושה דרוסה, \u0003ספק שונרא\u0004 \u0005[חתול]\u0006 הוא שנכנס — \u0003אימא כלבא\u0004 \u0005[אמור\u0006 ש\u0005כלב]\u0006 נכנס. \u0003על\u0004 \u0005[נכנס]\u0006 הטורף, \u0003שתיק ואיתוב בינייהו\u0004 \u0005[שתק וישב ביניהם]\u0006 — \u0003אימר שלמא שוי\u0004 \u0005[אמור\u0006 ש\u0005שלום עשה\u0006 עמהם\u0005],\u0006 כדרך חיות מתורבתות, ולא דרסם. וכן אם \u0003קטע רישיה דחד מינייהו\u0004 \u0005[את ראשו של אחד מהם]\u0006 — \u0003נח מריתחיה\u0004 \u0005[מכעסו],\u0006 ושוב אין חוששים שהוא דורס. היה \u0003איהו קא מעואי ואינהו קמקרקרן\u0004 \u0005[הוא נוהם והם מקרקרים]\u0006 — \u0003בעותי קא מבעתי\u0004 \u0005[להפחיד הם מפחידים]\u0006"],["\u0003אהדדי\u0004 \u0005[זה את זה],\u0006 ואין חשש שדרס. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במקרה \u0003דאיהו קא שתיק ואינהו קמקרקרן\u0004 \u0005[שהוא שותק והם מקרקרים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 שמואל, \u0005סבור]:\u0006 דבר זה מלמד ש\u0003מעשה קא עביד בהו\u0004 \u0005[הוא עושה בהם],\u0006 שהוא דורס, ולכן הם מקרקרים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003מחמת בעתותיה הוא דקא עבדן\u0004 \u0005[מחמת שהם פוחדים ממנו הוא שהם עושים כך],\u0006 שמקרקרים, ואין להסיק מכאן שהוא דורס.","\u0003אמר אמימר, הלכתא\u0004 \u0005[הלכה היא]:\u0006 \u0003חוששין לספק דרוסה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: האי\u0004 \u0005[זה]\u0006 שאמר \u0003רב,\u0004 שאין חוששים לספק דרוסה, \u0003מאי\u0004 \u0005[מהו]?\u0006 מה אתה אומר על כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיע לי\u0004 \u0005[לא שמעתי],\u0006 \u0003כלומר, לא סבירא לי\u0004 \u0005[איני סבור כן].\u0006","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רב לגבי שמואל,\u0004 וגם הוא אוסר. והראיה, \u0003דההוא שרקפא\u0004 \u0005[שאותו סל עופות]\u0006 של \u0003ספק\u0004 עופות \u0003דרוסות,\u0004 שנכנס נץ ביניהם, \u0003דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רב, שדרינהו לקמיה\u0004 \u0005[שלח אותם לפני]\u0006 \u0003שמואל\u0004 שיפסוק בדינם, \u0003חנקינהו ושדנהו בנהרא\u0004 \u0005[חנק אותם\u0006 שמואל \u0005וזרק אותם בנהר].\u0006 \u0003ואי סלקא דעתך לא הדר ביה\u0004 \u0005[ואם עולה על דעתך שלא חזר בו רב]\u0006 — \u0003לישרינהו\u0004 \u0005[שיתיר אותם],\u0006 ומדוע שלחם לשמואל?","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר, \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 רב? \u0003ליסרינהו\u0004 \u0005[שיאסור אותם]\u0006 בעצמו, ומדוע שלחם לשמואל? \u0003אלא\u0004 צריך לומר כי \u0003אתריה\u0004 \u0005[מקומו]\u0006 של \u0003שמואל הוה\u0004 \u0005[היה],\u0006 ולא רצה לפסוק הלכה במקומו של שמואל, שאין זו דרך ארץ, ואין מכאן ראיה.","ושואלים: \u0003למה לי למיחנקינהו\u0004 \u0005[למה לו\u0006 לשמואל \u0005לחנוק אותם]?\u0006 \u0003לישדינהו הכי בנהרא\u0004 \u0005[שיזרוק אותם כך בנהר]!\u0006 ומשיבים: חשש שמואל שמא \u0003מפרחן וסלקן\u0004 \u0005[יפרחו ויעלו\u0006 מן הנהר\u0005].\u0006","ושואלים: \u0003ולשהינהו\u0004 \u0005[ושיישהה אותם]\u0006 \u0003שנים עשר חודש,\u0004 ואם יישארו בחיים הוכחה היא שאינם טריפה, ויתירם! ומשיבים: חשש שמא \u0003אתי בהו\u0004 \u0005[יבואו בהם]\u0006 \u0003לידי תקלה,\u0004 שמא בתוך הזמן ישכחו את הדבר ויאכלו אותם. ושואלים: \u0003וליזבנינהו\u0004 \u0005[ושימכרם]\u0006 \u0003לגוים!\u0004 ומשיבים: שמואל חשש שמא \u0003אתו לזבנינהו\u0004 \u0005[יבואו\u0006 אותם גוים \u0005למוכרם]\u0006 \u0003לישראל.\u0004","ושואלים: \u0003וליחנקינהו ולישדינהו\u0004 \u0005[ושיחנוק אותם ויזרקם]\u0006 \u0003לאשפה,\u0004 למה לנהר? ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה שואל שאלה זו, \u0003נישדינהו\u0004 \u0005[שיזרוק אותם]\u0006 \u0003לכלבים,\u0004 ויהיה בזה גם תועלת מסויימת! \u0003אלא\u0004 שמואל עשה כן \u0003לפרסומי מלתא דאיסורא\u0004 \u0005[\u0006כדי \u0005לפרסם את דבר האיסור],\u0006 שכאשר הוא הולך לנהר ומשליכם יש בכך פרסום גדול.","מסופר, \u0003ההוא בר אווזא דהוה בי\u0004 \u0005[ברווז אחד שהיה בביתו]\u0006 של \u0003רב אשי, על לביני קניא\u0004 \u0005[נכנס לבין הקנים],\u0006 \u0003נפק אתא כי ממסמס קועיה דמא\u0004 \u0005[יצא ובא כאשר מלוכלך גרונו בדם].\u0006 \u0003אמר רב אשי:\u0004 וכי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 במקרה של \u0003ספק כלבא\u0004 \u0005[כלב]\u0006 טרף \u0003ספק שונרא\u0004 \u0005[חתול]\u0006 דרס — \u0003אימר כלבא\u0004 \u0005[אמור שכלב היה זה],\u0006 שאין בו דין דרוסה? \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 הואיל ו\u0003ספק קניא\u0004 \u0005[קנה]\u0006 פצע את גרונו, \u0003ספק שונרא\u0004 \u0005[חתול]\u0006 דרס אותו — \u0003אימר קניא מחייה\u0004 \u0005[אמור שקנה היכה\u0006 ופצע \u0005אותו].\u0006","\u0003אמרי\u0004 \u0005[אמרו]\u0006 \u0003בני ר' חייא,\u0004 יהודה וחזקיה: \u0003דרוסה שאמרו\u0004 — \u0003צריכה בדיקה כנגד בני מעיים,\u0004 ואם בדק והאדים הבשר שכנגד בני המעיים — טריפה היא, שסוף הארס לחלחל ולעשות נקב בבני המעיים עצמם.","\u0003אמר רב יוסף, הא\u0004 \u0005[זו]\u0006 שאמרו \u0003בני ר' חייא\u0004 — \u0003כבר פירשה שמואל,\u0004 ש\u0003אמר שמואל משום\u0004 (בשם) \u0003ר' חנינא בן אנטיגנוס: דרוסה שאמרו\u0004 — \u0003צריכה בדיקה כנגד בני מעיים.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אילפא:\u0004 האם \u0003יש דרוסה לסימנים\u0004 (קנה וושט), \u0003או אין דרוסה לסימנים?\u0004 האם הארס מחלחל ונוקב את הסימנים כמו שהוא נוקב את בני המעיים, או לא? \u0003אמר ר' זירא: הא דבעי\u0004 \u0005[זו ששאל]\u0006 \u0003אילפא\u0004 — \u0003כבר פירשה רב חנן בר רבא,\u0004 ש\u0003אמר רב חנן בר רבא אמר רב: דרוסה שאמרו\u0004 — \u0003צריכה בדיקה כנגד בית החלל\u0004 של הבהמה \u0003כולו, ואפילו בסימנין.\u0004","אגב כך מביאים מה ש\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אילפא: סימנין שנדלדלו,\u0004 שנעקרו במקומות הרבה, \u0003בכמה\u0004 עושה הדבר טריפה? \u0003אמר ר' זירא: הא דבעי\u0004 \u0005[זו ששאל]\u0006 \u0003אילפא\u0004 — \u0003כבר פירשה רבה בר בר חנה,\u0004 ש\u0003אמר רבה בר בר חנה אמר שמואל: סימנים שנדלדלו\u0004 — טריפתן \u0003ברובן.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אמי: המסמסה\u0004 (רקבון) שנדרסה ונרקב הבשר שלא כנגד חלל הגוף, אלא כגון ברגל, \u0003מהו? אמר ר' זירא: הא דבעי\u0004 \u0005[זו ששאל]\u0006 \u0003רב אמי\u0004 — \u0003כבר פירשה רב יהודה,\u0004 ש\u0003אמר רב יהודה אמר רב: בדרוסה\u0004 הכלל הוא, שאינה דרוסה \u0003עד שיאדים בשר\u0004 ש\u0003כנגד בני מעיים,\u0004 אבל אם \u0003נתמסמס\u0004 (נרקב) \u0003הבשר\u0004 — \u0003רואין אותו,\u0004 את המקום שנתמסמס, \u0003כאילו אינו,\u0004 ואם היה ניטל היתה זו טריפה — גם כשנתמסמס טריפה היא.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003נתמסמס? אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כל\u0004 שהוא במצב \u0003שהרופא גורדו\u0004 (מגרדו) \u0003ומעמידו על בשר חי,\u0004 כדי שיחזור ויתרפא. \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב כהנא אייתו קמן ההיא ריאה\u0004 \u0005[הביאו לפנינו ריאה אחת],\u0006 \u0003דכי הוו מיתבי לה\u0004 \u0005[שכאשר היו מושיבים אותה]\u0006 כמו שהיא \u0003—\u0004 \u0003יתבה שפיר\u0004 \u0005[היתה יושבת כראוי],\u0006 כלומר, לא היה קורה לה דבר, \u0003וכי הוו מדלו לה\u0004 \u0005[וכאשר היו מרימים אותה]\u0006 \u0003הוה תלחה ונפלה תילחי תילחי\u0004 \u0005[היתה מתפרקת ונופלת חלקים חלקים],\u0006 \u0003וטריפנא לה\u0004 \u0005[והטרפנו אותה]\u0006 \u0003מ\u0004תוך דברי \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שכל שהבשר נרקב עד כדי שהרופא צריך להסיר אותו — הרי זה כאילו ניטל, וכל שכן כאשר הוא נופל מעצמו, והרי זה כאילו חסרה הריאה, שהוא טריפה (לעיל מב,א).","\u0003רב נחמן אמר:\u0004 נקב שנעשה \u0003בקוץ\u0004 — אינה טריפה \u0003עד שתינקב לחלל\u0004 הגוף, \u0003בדרוסה\u0004 — \u0003משיאדים\u0004 ה\u0003בשר כנגד בני מעיים. רב זביד מתני הכי\u0004 \u0005[היה שונה\u0006 דבר זה \u0005כך]:\u0006 \u0003בדרוסה\u0004 בגופה — \u0003משיאדים בשר כנגד בני מעיים\u0004 הרי זו טריפה, אבל כשנדרסה \u0003בסימנים\u0004 אינה טריפה \u0003עד שיאדימו\u0004 ה\u0003סימנים עצמם,\u0004 אבל אם הבשר שכנגדם מאדים — אינה טריפה, שאין ודאות שהארס מחלחל לסימנים.","\u0003אמר רב פפי, בעי\u0004 \u0005[שאל]\u0006 \u0003רב ביבי בר אביי:\u0004 טעם שאין לומר כהסברו זה של רבה בר אבוה, שגזרו חכמים בטלית שאינה טבולת יום על קריעת רובה, שלא תטהר משום החשש שיבואו לקרוע רק מחציתה,"],["\u0003וושט,\u0004 יודעים אנו ממשנתנו (מב,א) ש\u0003נקובתו\u0004 (אם יש בו נקב) הרי הוא טריפה \u0003במשהו,\u0004 ולכן \u0003דרוסתו,\u0004 כשהאדים בשרו — גם היא \u0003במשהו. קנה,\u0004 אנו יודעים מן המשנה להלן בעמוד זה ש\u0003נקובתו\u0004 לאסור היא \u0003ב\u0004נקב שגודלו \u0003כאיסר, דרוסתו בכמה? בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל\u0006 את השאלה \u0005חזר ופתר אותה\u0006 בעצמו\u0005]:\u0006 \u0003אחד זה ואחד זה במשהו, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003זיהריה מקלא קלי ואזיל\u0004 \u0005[הארס שלו שורף והולך]\u0006 סביב למקומו ומרחיב את הנקב.","מסופר, \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יצחק בר שמואל בר מרתא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר]:\u0006 \u0003דרוסה שאמרו\u0004 חכמים — \u0003צריכה בדיקה\u0004 אם האדים הבשר \u0003כנגד בני מעיים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 בלשון שבועה: \u0003האלהים!\u0004 \u0003מורי\u0004 \u0005[מורה היה]\u0006 \u0003בה רב\u0004 למעשה שיבדוק בחלל גופה \u0003מכפא ועד אטמא\u0004 \u0005[מן\u0006 המקום שכנגד \u0005הכף ועד\u0006 כנגד \u0005הירך]\u0006 הרגל האחורית.","ושואלים: \u0003מאי כפא\u0004 \u0005[מהי הכף]?\u0006 \u0003אילימא כפא דידא\u0004 \u0005[אם תאמר כף היד,\u0006 כף הרגל הקדמית\u0005],\u0006 כלומר, עצם הכתף, שהיא נראית כמין כף — \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003כנגד בני מעיים,\u0004 שאמר רב יצחק בר שמואל, ומה חידש רב נחמן? \u0003אלא\u0004 הכוונה היא \u0003מכפא דמוחא\u0004 \u0005[מכף המוח,\u0006 מן הגולגולת, שהיא עגולה\u0005]\u0006 \u0003עד אטמא\u0004 \u0005[עד הירך].\u0006","מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רב חייא בר יוסף\u0004 מבבל לארץ ישראל, \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 את \u0003ר' יוחנן וריש לקיש דיתבי וקאמרי\u0004 \u0005[שיושבים ואומרים]:\u0006 \u0003דרוסה שאמרו\u0004 — \u0003צריכה בדיקה כנגד בני מעיים. אמר להו\u0004 \u0005[להם]\u0006 בלשון שבועה: \u0003האלהים! מורי\u0004 \u0005[מורה\u0006 היה\u0005]\u0006 \u0003בה רב\u0004 שיבדוק \u0003מכפא ועד אטמא\u0004 \u0005[מן הכף עד הירך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש: מנו\u0004 \u0005[מיהו]\u0006 \u0003רב\u0004 זה, \u0003ומנו\u0004 \u0005[ומיהו]\u0006 \u0003רב? ולא ידענא ליה\u0004 \u0005[ואין אני יודע מיהו]!\u0006","\u0003אמר\u0004 לו \u0003ר' יוחנן: ולא נהירא ליה\u0004 \u0005[ואין\u0006 אתה \u0005זוכר אותו]\u0006 \u0003לאותו תלמיד ששימש את רבי\u0004 ר' יהודה הנשיא \u0003רבה\u0004 \u0005[הגדול],\u0006 \u0003ו\u0004את \u0003ר' חייא\u0004 ולמד מפיהם? \u0003והאלהים! כל אותן שנים ששימש אותו תלמיד בישיבה,\u0004 שהיה נחשב מהתלמידים החשובים, והיתה לו רשות לשבת בשעת הלימוד, \u0003אני\u0004 קטן הייתי ממנו ו\u0003שמשתי בעמידה, ומאן\u0004 \u0003גבר\u0004 \u0005[ומי\u0006 היה \u0005גדול]?\u0006 \u0003הוא\u0004 היה \u0003גבר בכולא\u0004 \u0005[גדול בכל],\u0006 בכל דבר, בתורה ובחסידות.","\u0003מיד פתח ריש לקיש ואמר: ברם\u0004 (אמנם), \u0003זכור אותו האיש\u0004 כלומר, רב, \u0003לטוב, שאמרו שמועה\u0004 זו \u0003מפיו:\u0004 אם הובאה לפנינו בהמה שהגרגרת (הקנה) שלה \u0003שמוטה,\u0004 שנעקרה ונשמטה מחיבורה בבית הבליעה, \u0003ו\u0004היתה הגרגרת \u0003שחוטה,\u0004 ואין ידוע אם נשמטה קודם שחיטה, וטריפה היא, או רק לאחר השחיטה והריהי כשרה — הרי זו \u0003כשרה,\u0004 ומדוע? \u0003שאי אפשר ל\u0004גרגרת \u0003שמוטה שתיעשה שחוטה,\u0004 שמפני שהיא נשמטת למטה אי אפשר לשוחטה, וכיון שהיא שחוטה לפנינו ודאי נשמטה לאחר השחיטה.","\u0003ור' יוחנן אומר:\u0004 אין הדבר ברור, וכדי לבדוק אימתי נשמטה \u0003יביא\u0004 את הגרגרת ויעשה בה חתך נוסף, \u0003ויקיף,\u0004 ישווה את החתך לחתך השחיטה, ואם הם דומים — סימן הוא שהחתך של השחיטה נעשה לאחר שהגרגרת נשמטה, וטריפה היא, ואם אינם דומים — סימן שנעשה קודם שנשמטה, וכשרה.","\u0003אמר רב נחמן: לא שנו\u0004 שאי אפשר לשמוטה שתיעשה שחוטה, \u0003אלא\u0004 כ\u0003שלא תפס בסימנים\u0004 (בקנה ובוושט) בשעת שחיטה, \u0003אבל תפס בסימנים ושחט\u0004 — \u0003אפשר לשמוטה שתיעשה שחוטה,\u0004 שהרי באופן זה שהוא מחזיק בה אינה נשמטת.","שנינו בסוף המשנה: \u0003זה הכלל,\u0004 כל שאין כמוה חיה — טריפה. ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא את מה]\u0006 נאמר כלל זה? ומשיבים: \u0003לאתויי שב שמעתתא\u0004 \u0005[להביא\u0006 אותן \u0005שבע שמועות]\u0006 שנאמרו מפי האמוראים (לעיל מב,ב), ולא נזכרו במשנה.","מסופר, \u0003דבי\u0004 \u0005[\u0006אנשי \u0005ביתו]\u0006 של \u0003יוסף רישבא\u0004 \u0005[הצייד]\u0006 \u0003מחו בגידא נשיא וקטלי\u0004 \u0005[היו מכים,\u0006 יורים חץ \u0005בגיד הנשה\u0006 של חיה \u0005והורגים],\u0006 שהיתה מתה בכך. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יהודה בן בתירא,\u0004 לשאול אותו האם אין זו טריפה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003וכי להוסיף על הטרפות יש\u0004 בידינו? \u0003אין לך אלא מה שמנו חכמים!\u0004","וכן אנשי \u0003רב פפא בר אבא רישבא\u0004 \u0005[הצייד]\u0006 \u0003מחו בכוליא וקטלי\u0004 \u0005[היו מכים\u0006 את הבהמה \u0005בכליה והורגים],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבי אבא\u0004 לשאול אותו מה הדין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003וכי להוסיף על הטרפות יש? אין לך אלא מה שמנו חכמים.\u0004","ושואלים: \u0003והא קא חזינן דקא\u0004 \u0005[והרי אנו רואים שהיא]\u0006 \u0003מתה,\u0004 ואם כן הרי זה סימן מובהק של טריפה! ומשיבים: \u0003גמירי\u0004 \u0005[למודים אנו במסורת]\u0006 בכל המקרים הללו, \u0003דאי בדרי לה סמא חייא\u0004 \u0005[שאם היו מפזרים לה סם,\u0006 רפואה, על הפצע \u0005היתה חיה],\u0006 ולא נחשבו טריפות אלא אלה שאין להם תקנה.","\u0003ואלו כשרות בבהמה,\u0004 אף על פי שלקו בגופן: אם \u0003ניקבה הגרגרת\u0004 (הקנה) \u0003או שנסדקה\u0004 לאורכה. \u0003עד כמה תחסר\u0004 הגרגרת שניקבה ועדיין כשרה היא? \u0003רבן שמעון בן גמליאל אומר: עד כ\u0004גודל המטבע \u0003איסר האיטלקי. נפחתה\u0004 (נשברה) \u0003הגולגולת, ו\u0004אולם \u0003לא ניקב קרום של מוח\u0004 — הרי זו כשרה. \u0003ניקב הלב ולא\u0004 הגיע הנקב עד \u0003לבית חללו\u0004 לתוך חלל הלב. \u0003נשברה השדרה ולא נפסק החוט שלה\u0004 שעובר בתוכה. \u0003ניטלה הכבד ונשתייר הימנה\u0004 (ממנה) \u0003כזית.\u0004","\u0003המסס ובית הכוסות,\u0004 שתי קיבות צמודות זו לזו במערכת העיכול של הבהמה, \u0003שניקבו זה לתוך זה,\u0004 ולא לחוץ, לחלל הבטן. \u0003ניטל הטחול, ניטלו הכליות, ניטל לחי\u0004 (לסת) \u0003התחתון,\u0004 נקבה ש\u0003ניטלה האם\u0004 (הרחם) \u0003שלה, וחרותה\u0004 שריאתה הצטמקה \u0003בידי שמים,\u0004 כל אלה כשרות. \u0003הגלודה\u0004 שניטל עורה מעליה — \u0003ר' מאיר מכשיר, וחכמים פוסלין\u0004 (מטריפים).","שנינו בתחילת המשנה \"ואלו כשרות\", וכן שנינו באופן זה בראש הפרק \"אלו טרפות\", ועל כך \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים, \u0003ר' יוחנן אמר:\u0004 מה ששנה התנא בתחילת הפרק \u0003\"אלו טרפות\"\u0004 הוא \u0003דוקא,\u0004 שכוונתו למעט מקרה אחר ולומר שאינו טריפה, אבל מה ששנה כאן \"ואלו כשרות\" לא בא למעט, אלא נשנה אגב כך. \u0003ור' שמעון בן לקיש אמר:\u0004 מה ששנה התנא כאן \u0003\"אלו כשרות\"\u0004 הוא ב\u0003דוקא,\u0004 למעט מקרה אחר, שבו אין הבהמה כשרה, ואגב כך שנה \"אלו טרפות\".","ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה מקרה, \u0005הם חולקים]?\u0006 — \u0003ב\u0004דברי \u0003רב מתנא,\u0004 ש\u0003אמר רב מתנא: האי בוקא דאטמא דשף מדוכתיה\u0004 \u0005[ראש עצם הירך שיצא ממקומו]\u0006 — הרי זו \u0003טרפה.\u0004 ומפרטים: \u0003ר' יוחנן\u0004 ש\u0003אמר: \"אלו טרפות\" דוקא;\u0004 לשיטתו \u0003תנא\u0004 \u0005[שנה]\u0006 התנא מתחילה רשימת \u0003טרפות, ותנא\u0004 \u0005[ושנה]\u0006 אחר כך \u0003\"זה הכלל\"\u0004 להוסיף את אלו שלא נשנו במפורש,"],["\u0003וחזייה\u0004 \u0005[וראה\u0006 התנא \u0005את זו]\u0006 שאמר \u0003רב מתנא\u0004 שיצא ראש עצם הירך ממקומו, \u0003דאתיא\u0004 \u0005[שהיא באה,\u0006 נכנסת\u0005]\u0006 לכאורה \u0003ב\u0004תוך \u0003\"זה הכלל\"\u0004 שבסוף המשנה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 משום \u0003דדמיא לנטולי\u0004 \u0005[שהיא דומה לנטולים],\u0006 כמו לניטל הכבד ששנינו במשנה שהוא טריפה, לכן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"אלו טרפות\"\u0004 להדגיש: \u0003הני הוא\u0004 \u0005[אלו הם]\u0006 \u0003טרפה, הא\u0004 \u0005[אבל]\u0006 זו של \u0003רב מתנא כשרה,\u0004 ואגב ששנה \"אלו טרפות\" — שנה גם \"אלו כשרות\". זו שיטת ר' יוחנן.","\u0003ור' שמעון בן לקיש אמר:\u0004 מה ששנינו \u0003\"אלו כשרות\" דוקא,\u0004 כיצד? \u0003תנא\u0004 \u0005[שנה]\u0006 התנא רשימת \u0003טרפות, ותנא\u0004 \u0005[ושנה]\u0006 \u0003\"זה הכלל\"\u0004 להוסיף טריפות דומות להן, \u0003וחזייה\u0004 \u0005[וראה את]\u0006 ההלכה של \u0003רב מתנא,\u0004 שיצא ראש עצם הירך ממקומו, \u0003דלא אתיא\u0004 \u0005[שאינה באה,\u0006 נכנסת\u0005]\u0006 לכאורה \u0003ב\"זה הכלל\", מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו לנקובי דמיא\u0004 \u0005[לא לנקובים\u0006 כגון נקובת הוושט, \u0005היא דומה],\u0006 שהרי אין בה נקב, \u0003ולא לפסוקי דמיא\u0004 \u0005[ולא לחתוכים\u0006 כגון פסוקת הגרגרת, \u0005היא דומה],\u0006 שהרי לא נחתכה, \u0003ולנטולי נמי לא דמיא\u0004 \u0005[ולנטולים גם כן אינה דומה],\u0006 שהרי לא ניטלה, לכן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"אלו כשרות\"\u0004 — להדגיש: \u0003הני הוא\u0004 \u0005[אלה הן]\u0006 שהן \u0003כשרות,\u0004 ואולם \u0003הא\u0004 \u0005[זו]\u0006 של \u0003רב מתנא\u0004 היא \u0003טרפה.\u0004 ואגב כך שנה \"אלו טרפות\".","\u0003גופא\u0004 \u0005[\u0006ודנים ל\u0005גופה]\u0006 של אותה הלכה שהבאנו, \u0003אמר רב מתנא: האי בוקא דאטמא דשף מדוכתיה\u0004 \u0005[ראש הירך שיצא ממקומו]\u0006 בשקע שבעצם האליה — \u0003טרפה. ורבא אמר: כשרה, ואי איפסיק ניביה\u0004 \u0005[ואם נפסק,\u0006 נחתך \u0005הניב שלו],\u0006 הגיד המחבר אותו למקומו — הריהי \u0003טרפה. והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003איפסיק\u0004 \u0005[נפסקו]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003כשרה, עד דמתעכלא אתעכולי\u0004 \u0005[שמתעכל,\u0006 נרקב\u0005]\u0006 אותו ניב, אז היא טריפה.","שנינו במשנה בענין גרגרת שניקבה: \u0003עד כמה תחסר\u0004 ותהא כשרה? עד כגודל איסר האיטלקי. \u0003אמר זעירי\u0004 שבא מארץ ישראל: \u0003אתון דלא מיתחמי לכון שיעורא\u0004 \u0005[אתם שאינכם יכולים לראות את השיעור]\u0006 של איסר האיטלקי, שאינו מצוי בבבל — \u0003שיעוריה בדינרא קורדינאה\u0004 \u0005[שיעורו\u0006 לגביהם \u0005בדינר כורדי].\u0006 \u0003והוי כפשיטא זוטרתי\u0004 \u0005[והוא כמו מעה קטנה],\u0006 \u0003ומשתכחא ביני פשיטי\u0004 \u0005[והיא מצויה בין הפרוטות]\u0006 של \u0003פומבדיתא.\u0004","\u0003אמר ר' חנא פתוראה\u0004 \u0005[השולחני,\u0006 חלפן הכספים\u0005]:\u0006 \u0003עילא מינאי הוה קאי\u0004 \u0005[למעלה ממני היה עומד]\u0006 \u0003בר נפחא,\u0004 ר' יוחנן, \u0003ובעא מיני דינרא קורדינאה לשערי ביה טריפתא\u0004 \u0005[וביקש ממני דינר כורדי לשער בו טריפות]\u0006 כמו שאמר זעירי, \u0003ובעי למיקם מקמיה ולא שבקני\u0004 \u0005[ורציתי לעמוד מפניו,\u0006 מפני כבודו, \u0005ולא הניחני],\u0006 \u0003אמר לי: שב בני שב! אין בעלי אומניות\u0004 (בעלי מלאכה) \u0003רשאין לעמוד מפני תלמידי חכמים בשעה שעסוקין במלאכתם.\u0004","ושואלים: \u0003ולא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 כאשר היו מביאים את הביכורים לירושלים \u0003כל בעלי אומניות\u0004 שבירושלים היו \u0003עומדים מפניהם, ושואלין בשלומן, ואומרין להם: אחינו אנשי מקום פלוני בואכם בשלום!\u0004","\u0003אמר ר' יוחנן: מפניהם\u0004 אמנם \u0003עומדין,\u0004 שצריך להרבות בכבודם, אבל \u0003מפני תלמידי חכמים אין עומדין.\u0004 \u0003אמר ר' יוסי בר אבין: בא וראה כמה חביבה מצוה בשעתה!\u0004 \u0003שהרי מפניהם,\u0004 מפני מביאי הביכורים — \u0003עומדין, מפני תלמידי חכמים\u0004 — \u0003אין עומדין.\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]?\u0006 מכאן אין ראיה, \u0003דילמא\u0004 \u0005[שמא]\u0006 עומדים מפניהם לא בגלל חשיבותם היתרה, אלא \u0003כדי שלא תהא נמצא מכשילן לעתיד לבא,\u0004 שאם לא ינהגו בהם כבוד מרובה יימנעו מלהביא ביכורים, מפני טורח הדרך.","שנינו במשנתנו: עד כמה תחסר הגרגרת ועדיין תהיה הבהמה כשרה — עד כאיסר האיטלקי. ובענין זה מביאים מה ש\u0003אמר רב נחמן:\u0004 כשאמרו חכמים על דבר ששיעורו \u0003כסלע,\u0004 וכגון שאם נחסרה גולגולת כסלע הרי זו טריפה, דינו של חסרון כסלע מצומצם הריהו כ\u0003יתר מכסלע.\u0004 וכששנו \u0003כאיסר,\u0004 כגון במשנתנו, שאם נחסרה הגרגרת עד כאיסר האיטלקי הריהי כשרה — דינו של חסרון כאיסר מצומצם הריהו \u0003כיתר מכאיסר,\u0004 שהוא עושה טריפה.","ואומרים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 \u0003רב נחמן\u0004 שבכל מקום שאומרים חכמים \u0003\"עד\"\u0004 כוונתם \u0003ולא עד בכלל,\u0004 שהרי שנינו במשנתנו שאם נחסרה הגרגרת עד כאיסר האיטלקי הריהי כשרה, ובוודאי אינו כולל חסרון בגודל איסר מדוייק, שהרי הוא טריפה לדברי ר' נחמן, כיתר מאיסר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו בדיני טומאה וטהרה: \u0003חבל היוצא מן המטה\u0004 (מיטת חבלים) לאחר שסירגו בו את המיטה, אם אורכו \u0003עד חמשה טפחים\u0004 — \u0003טהור,\u0004 שאם נטמאה המיטה — אינו נטמא איתה, מפני שאינו ראוי לכלום, ואינו נחשב חלק ממנה. \u0003מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 שאם היו בו \u0003חמשה\u0004 טפחים בדיוק הרי הוא \u0003כלמטה,\u0004 כפחות מחמישה טפחים, ואינו מקבל טומאה? ואם כן \"עד\" — ועד בכלל! ודוחים: \u0003לא,\u0004 אם היו בו \u0003חמשה\u0004 דינו \u0003כלמעלה\u0004 מחמישה, ומקבל טומאה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו שם: היו בחבל \u0003מחמשה\u0004 טפחים \u0003ועד עשרה\u0004 טפחים — \u0003טמא, מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שאם היו בו \u0003עשרה\u0004 טפחים דינו \u0003כלמטה,\u0004 כפחות מעשרה, וטמא? ודוחים: \u0003לא, עשרה\u0004 דינו \u0003כלמעלה\u0004 מעשרה, שאם נטמאה המיטה הריהו טהור.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003הדקין\u0004 (הקטנים) \u0003שבכלי חרס,\u0004 בין \u0003הן\u0004 עצמם, \u0003ו\u0004בין אם נשברו ונשארו \u0003קרקרותיהן\u0004 (התחתיות שלהם), או \u0003דופנותיהם,\u0004 ואותם שוליים או דפנות שנשארו \u0003יושבין שלא מסומכין,\u0004 שאין צורך להשעין אותם על משהו אחר, ויש בהם עדיין בית קיבול —"],["\u0003שיעורן\u0004 לקבל טומאה \u0003בכדי סיכת קטן,\u0004 שיש בו כדי להכיל שמן לסוך בו תינוק. \u0003ו\u0004שיעור זה הוא בכלים שהיה בהם מתחילה \u0003עד לוג,\u0004 אבל כלים גדולים מכך שיעור שבריהם לקבל טומאה גדול יותר. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 דין כלים המכילים \u0003לוג\u0004 בדיוק \u0003כלמטה,\u0004 כדין הכלים הקטנים מלוג? ואם כן מוכח מכאן שכשנאמר \"עד\" — עד בכלל? ודוחים: \u0003לא,\u0004 דינו של כלי המכיל \u0003לוג\u0004 בדיוק — \u0003כלמעלה\u0004 ממנו, ואם נשבר צריך שיהיה בו שיעור גדול יותר כדי לקבל טומאה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו באותה משנה: כלים שהיה בהם מתחילה \u0003מלוג עד סאה\u0004 ונשברו — שיעור שבריהם לקבל טומאה \u0003ברביעית, מאי לאו\u0004 \u0005[האם אין]\u0006 דין כלי המכיל \u0003סאה\u0004 בדיוק \u0003כלמטה\u0004 מסאה? ודוחים: \u0003לא,\u0004 דין כלי של \u0003סאה כלמעלה\u0004 ממנו, ששבריו מקבלים טומאה רק אם היה בהם יותר מכך, חצי לוג.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: כלים \u0003מסאה ועד סאתים\u0004 שנשברו, שיעורם לקבל טומאה \u0003בחצי לוג, מאי לאו\u0004 \u0005[האם אין]\u0006 דין כלי שמכיל \u0003סאתים\u0004 בדיוק \u0003כלמטה\u0004 ממנו, ושבריו מקבלים טומאה בשיעור חצי לוג? ודוחים: \u0003לא,\u0004 דין כלי שיש בו \u0003סאתים כלמעלה\u0004 ממנו, ששבריו מקבלים טומאה רק אם היה בהם לוג שלם.","ומקשים: כיצד יכול אתה לתרץ כך את המשנה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 מפורשת: דין כלי שיש בו \u0003לוג\u0004 — \u0003כלמטה,\u0004 וכן דין כלי שיש בו \u0003סאה\u0004 — \u0003כלמטה,\u0004 וכן דין כלי שיש בו \u0003סאתים\u0004 — \u0003כלמטה.\u0004 ואם כן, מוכח משם ש\"עד\" ועד בכלל, שלא כדברי רב נחמן, שאמר בענין גרגרת שנחסרה עד כאיסר כשרה, ש\"עד\" — ולא עד בכלל, ואם נחסרה כאיסר — טריפה!","ומתרצים: \u0003התם לחומרא\u0004 \u0005[שם\u0006 נאמר עד ועד בכלל \u0005להחמיר]\u0006 ולטמא, אבל אם היה בזה להקל היינו אומרים: עד — ולא עד בכלל, וכדברי רב נחמן בענין גרגרת שנחסרה. והוא כדרך שאמר ר' אבהו אמר ר' יוחנן: \u0003כל שיעורי חכמים\u0004 שאמרו — צריך לדון בהם \u0003להחמיר, חוץ מ\u0004שיעור \u0003כגריס של כתמים\u0004 של דם אשה, ששיעורו \u0003להקל,\u0004 שאם היה הכתם כגריס מדוייק אינו מטמא.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר, שהולכים בענין \"עד\" לחומרה, ממה \u0003דקתני עלה דההיא\u0004 \u0005[ש\u0006התנא \u0005שונה על אותה\u0006 משנה\u0005]\u0006 בענין חבל היוצא מן המטה, ששנינו בה שעד חמישה טפחים טהור, ומחמישה ועד עשרה טמא. ועל כן אמרו בברייתא: דין חבל בן \u0003חמשה\u0004 טפחים בדיוק — \u0003כלמעלה,\u0004 כדין חבל ארוך יותר, והוא נטמא, הרי ש\"עד\" אינו בכלל. ומצד אחר אמרו שדין חבל בן \u0003עשרה\u0004 טפחים בדיוק — \u0003כלמטה,\u0004 כדין חבל קצר ממנו, להיטמא, הרי ש\"עד\" — ועד בכלל. אלא מכאן שהולכים בענין זה להחמיר.","שנינו במשנה: \u0003ניטל הטחול\u0004 כשרה. \u0003אמר רב עוירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא שנו\u0004 שהיא כשרה \u0003אלא\u0004 כש\u0003ניטל\u0004 כולו, \u0003אבל\u0004 אם \u0003ניקב\u0004 הטחול — \u0003טרפה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' יוסי בר אבין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יוסי בר זבידא,\u0004 ממה ששנינו במשנה להלן: אם היה \u0003חותך מעובר שבמעיה\u0004 של בהמה חיה — מה שחתך \u0003מותר באכילה,\u0004 ואינו אסור כדין אבר מן החי. אבל היה חותך \u0003מן הטחול ומן הכליות\u0004 שבמעי בהמה חיה — מה שחתך \u0003אסור באכילה.\u0004 ונדייק מכאן: דווקא מה שחתך מן הטחול והכליות אסור באכילה, \u0003הא\u0004 \u0005[הרי]\u0006 ה\u0003בהמה גופא\u0004 \u0005[עצמה]\u0006 שחתך חלק מן הטחול שלה — \u0003שריא\u0004 \u0005[מותרת],\u0006 ואינה נחשבת טריפה!","ומשיבים: \u0003הוא הדין\u0004 ש\u0003אפילו\u0004 ה\u0003בהמה נמי אסירא\u0004 \u0005[גם כן אסורה],\u0006 אלא \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילה]\u0006 בענין עובר \u0003מותר באכילה\u0004 — \u0003תנא נמי סיפא\u0004 \u0005[שנה גם כן בסוף]\u0006 בענין חותך מן הטחול \u0003אסור באכילה,\u0004 שהישווה אותם זה לזה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 יש לחלק, \u0003ניקב לחוד, ונחתך לחוד,\u0004 שאם ניקב עושה טריפה, ואם נחתך לא עושה טריפה.","שנינו במשנה: \u0003ניטלו הכליות\u0004 כשרה. \u0003אמר רכיש בר פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: לקתה\u0004 (חלתה) בהמה אפילו \u0003בכוליא\u0004 (כליה) \u0003אחת\u0004 — \u0003טרפה. אמרי במערבא\u0004 \u0005[אמרו בארץ ישראל]\u0006 בביאור הדבר: \u0003והוא דמטאי לקותא\u0004 \u0005[שהגיעה הלקות]\u0006"],["\u0003למקום\u0004 ה\u0003חריץ, והיכא\u0004 \u0005[והיכן]\u0006 \u0003מקום\u0004 ה\u0003חריץ?\u0004 הכוונה היא \u0003לחיורא דתותי מתני\u0004 \u0005[ללבן שתחת המתניים].\u0006 \u0003אמר ר' נחוניא: שאילתינהו לכולהו טרופאי דמערבא\u0004 \u0005[שאלתי את כל פוסקי דיני הטריפות שבארץ ישראל],\u0006 \u0003ואמרי\u0004 \u0005[ואמרו]\u0006 \u0003לי: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרכיש בר פפא\u0004 בשם רב, שכוליא שלקתה — טריפה. \u0003ולית הלכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003כרב עוירא\u0004 בענין הטחול, שאמר שאם ניקב טריפה, אלא כשרה היא.","ומוסיפים, שעל דברי \u0003רב עוירא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 שהיא כשרה \u0003אלא בקולשיה\u0004 \u0005[כאשר\u0006 ניקב הטחול \u0005בחלקו הדק],\u0006 התחתון, \u0003אבל\u0004 ניקב \u0003בסומכיה\u0004 \u0005[בצד העבה שלו],\u0006 העליון — הלכה כמותו והריהי \u0003טרפה. ואי\u0004 \u0005[ואם]\u0006 כשניקב חלקו העבה נקב שאינו מפולש, \u0003אישתייר ביה\u0004 \u0005[נשאר בו]\u0006 בטחול \u0003כעובי דינר זהב\u0004 שלא ניקב — \u0003כשרה.\u0004","\u0003אמרי במערבא\u0004 \u0005[אמרו בארץ ישראל]:\u0006 \u0003כל הפוסל בריאה\u0004 — \u0003כשר בכוליא\u0004 (כליה), וראיה לדבר, \u0003שהרי נקב פסול בריאה,\u0004 כפי ששנינו במשנה בראש הפרק, \u0003וכשר בכוליא,\u0004 שלא שנינו אותה בין האיברים שנקב פוסל בהם. \u0003ו\u0004מכאן יש ללמוד כי \u0003כל שכן היכא\u0004 \u0005[במקום]\u0006 שהדבר ה\u0003כשר בריאה\u0004 — שהוא \u0003כשר בכוליא.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' תנחומא: וכללא הוא\u0004 \u0005[וכי כלל הוא זה]?\u0006 \u0003הרי מוגלא\u0004 ש\u0003כשר בריאה ופסול בכוליא! והרי מים זכין\u0004 ש\u0003כשרים הכא והכא\u0004 \u0005[כאן וכאן],\u0006 בריאה ובכוליא! \u0003אלא אמר רב אשי: טרפות קא מדמית להדדי\u0004 \u0005[אתה מדמה זו לזו]?\u0006 \u0003אין אומרים בטרפות זו דומה לזו! שהרי\u0004 בגוף בהמה יש מקומות שונים, \u0003חותכה מכאן ומתה, חותכה מכאן וחיתה,\u0004 ויתכן איפוא שיש דבר שפוסל בכוליא וכשר בריאה, ודבר אחר שפוסל בריאה וכשר בכוליא!","אגב כך מעירים: \u0003ו\u0004ביחס ל\u0003מים זכין\u0004 המצויים בריאה או בכוליא, שהם \u0003כשרים, לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 במקרה \u0003דצילי\u0004 \u0005[שהם צלולים],\u0006 \u0003אבל\u0004 אם הם \u0003עכירי\u0004 \u0005[עכורים]\u0006 — \u0003טרפה. וכי צילי נמי לא אמרן\u0004 \u0005[וכאשר הם צלולים גם כן לא אמרנו]\u0006 שהיא כשרה, \u0003אלא דלא סריח\u0004 \u0005[שאינם מסריחים],\u0006 \u0003אבל\u0004 אם הם \u0003סריח\u0004 \u0005[מסריחים]\u0006 — \u0003טרפה.\u0004","ועוד בדיני טריפות הכוליא: \u0003הכוליא שהקטינה\u0004 (שנעשתה קטנה), \u0003ב\u0004בהמה \u0003דקה,\u0004 אם היתה קטנה \u0003עד\u0004 שהיא \u0003כ\u0004גודל \u0003פול\u0004 הריהי טריפה, \u0003ב\u0004בהמה \u0003גסה\u0004 — אם היתה קטנה \u0003עד כענבה בינונית\u0004 הריהי טריפה.","שנינו במשנה: \u0003ניטל לחי התחתון\u0004 כשרה. \u0003אמר ר' זירא: לא שנו אלא שיכולה לחיות\u0004 בכל זאת \u0003על ידי לעיטה\u0004 או \u0003המראה,\u0004 שתוחבים אוכל לפיה או למעיה, \u0003אבל\u0004 אם \u0003אינה יכולה לחיות על ידי לעיטה והמראה\u0004 — \u0003טרפה.\u0004","שנינו במשנה: \u0003ניטלה האם\u0004 (הרחם) \u0003שלה\u0004 כשרה. \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 \u0003היא האם, היא\u0004 הקרויה \u0003טרפחת, והיא\u0004 הקרויה לעיתים \u0003שלפוחית,\u0004 כלומר, פעמים נקראת כך ופעמים נקראת כך.","שנינו במשנה: \u0003וחרותה בידי שמים\u0004 — \u0003כשרה. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003איזוהי חרותה? כל שצמקה ריאה שלה.\u0004 ואם היה הדבר \u0003בידי שמים,\u0004 וכגון שנבעתה מברקים ורעמים — \u0003כשרה;\u0004 אם היה הדבר \u0003בידי אדם,\u0004 שהבהיל אותה, וכגון שראתה אותו שוחט בהמה אחרת — \u0003טרפה. ר' שמעון בן אלעזר אומר: אף בידי כל הבריות,\u0004 כגון ששמעה שאגת אריה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ר' שמעון בן אלעזר ארישא קאי ולקולא\u0004 \u0005[על ראש\u0006 הברייתא \u0005הוא עומד,\u0006 מתייחס, \u0005ולהקל],\u0006 שאם היה הדבר בידי שמים, או בידי שאר הבריות חוץ מבידי אדם — כשרה. \u0003או\u0004 האם \u0003אסיפא קאי ולחומרא\u0004 \u0005[על סופה הוא עומד,\u0006 מתייחס, \u0005ולהחמיר],\u0006 שלא רק בידי אדם היא טריפה, אלא בידי כל הבריות?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חרותה בידי אדם\u0004 — \u0003טרפה, ר' שמעון בן אלעזר אומר: אף בידי כל הבריות\u0004 טריפה.","מסופר, \u0003רבה בר בר חנה הוה קאזיל במדברא\u0004 \u0005[היה הולך במדבר],\u0006 \u0003אשכח הנהו דיכרי דצמיק ריאה דידהו\u0004 \u0005[מצא אילים\u0006 שנשחטו ונמצא \u0005שצמקה הריאה שלהם].\u0006 \u0003אתא שאיל בי מדרשא\u0004 \u0005[הלך\u0006 ו\u0005שאל בבית המדרש]\u0006 כיצד יודעים אם נעשה הדבר בידי שמים. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בקייטא\u0004 \u0005[בקיץ]\u0006 \u0003אייתי משיכלי חיורי\u0004 \u0005[הבא כלים לבנים],\u0006 \u0003ומלינהו מיא קרירי\u0004 \u0005[ומלא אותם מים קרים],\u0006 \u0003ואנחינהו\u0004 \u0005[והנח אותם]\u0006 את הריאות בתוכם \u0003מעת לעת\u0004 (עשרים וארבע שעות), \u0003אי הדרן בריין\u0004 \u0005[אם הריאות חוזרות ומבריאות],\u0006 כלומר, מתרחבות — \u0003בידי שמים היא וכשרה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 התרחבו — \u0003טרפה. בסיתוא\u0004 \u0005[בחורף],\u0006 \u0003אייתי משיכלי שיחומי\u0004 \u0005[הבא כלים כהים],\u0006 \u0003ומלינהו מיא פשורי\u0004 \u0005[ומלא אותם מים פושרים],\u0006 \u0003ואנחינהו\u0004 \u0005[והנח אותם]\u0006 את הריאות בתוכם \u0003מעת לעת, אי הדרא בריא\u0004 \u0005[אם חוזרת ומבריאה]\u0006 — \u0003כשרה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003טרפה.\u0004","שנינו במשנה: \u0003הגלודה,\u0004 שנפשט עורה — ר' מאיר מכשיר וחכמים פוסלים. ובענין זה מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הגלודה\u0004 — \u0003ר' מאיר מכשיר, וחכמים פוסלים. וכבר העיד אלעזר ספרא ויוחנן בן גודגדא\u0004 בפני חכמים \u0003על הגלודה שפסולה. אמר ר' שמעון בן אלעזר: חזר בו ר' מאיר.\u0004","ומתקשים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ל\u0004דעת \u0003ר' שמעון בן אלעזר פליג\u0004 \u0005[חולק]\u0006 \u0003ר' מאיר\u0004 בתחילה \u0003בגלודה,\u0004 אלא שחזר בו? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו ר' מאיר וחכמים על הגלודה, ש\u0004לדעת הכל היא \u0003פסולה. וכבר העיד ר' אושעיא בנו של ר' יהודה הבשם\u0004 (מוכר הבשמים) \u0003לפני ר' עקיבא משום\u0004 (בשם) \u0003רבי טרפון על הגלודה שפסולה. ואם נשתייר בו כסלע\u0004 שלא נגלד העור — \u0003כשרה.\u0004 ומן הלשון \"לא נחלקו\" אתה למד שלא נחלקו כלל! \u0003אמר רב נחמן בר יצחק: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא נחלקו\"?\u0004 כוונתו: אמנם נחלקו, אבל \u0003לא עמד ר' מאיר במחלוקתו,\u0004 אלא חזר בו.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ברייתא: \u0003אם נשתייר בו כסלע\u0004 — \u0003כשרה,\u0004 ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 אם נשתייר הוא מציל? \u0003אמר רב יהודה אמר שמואל:\u0004 אם נשתייר כסלע \u0003על פני השדרה כולה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: איך להבין את ההלכה הזו? האם הכוונה שנשתייר קטע \u0003דאריך וקטין\u0004 \u0005[שהוא ארוך וצר],\u0006 כעין רצועה דקה, \u0003דכי מצרף לה\u0004 \u0005[שכאשר הוא מצרף אותה]\u0006 \u0003הוי\u0004 \u0005[הריהי]\u0006 בסך הכל \u0003כ\u0004רוחב \u0003סלע, או דלמא\u0004 \u0005[שמא]\u0006 הכוונה \u0003ברוחב סלע על פני השדרה כולה?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דפריש\u0004 \u0005[שפירש]\u0006 \u0003ר' נהוראי משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל: ברוחב כסלע על פני כל השדרה כולה.\u0004","\u0003רבה בר בר חנה אמר:\u0004 צריך להיות כסלע ב\u0003ראשי פרקים,\u0004 בכל פרקי החוליות, וכן בפרקי עצמות השוק והירך. \u0003ר' אלעזר בן אנטיגנוס משום ר' אלעזר בר' ינאי אמר:\u0004 צריך להיות כסלע ב\u0003מקום טיבורו,\u0004 במרכז הבטן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ינאי בר' ישמעאל:\u0004 אם \u0003ניטל\u0004 העור של \u0003מקום השדרה, ו\u0004כל שאר העור \u0003כולו קיים,\u0004 או \u0003ניטל מקום טיבורו וכולו קיים,\u0004 או \u0003ניטלו ראשי פרקים וכולו קיים, מאי\u0004 \u0005[מה\u0006 יהיה דינו\u0005]?\u0006 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רב: כל העור כולו,\u0004 בכל מקום בגופה שנשתייר בו כסלע — \u0003מציל בגלודה, חוץ מעור בית הפרסות\u0004 בחלק התחתון של הרגל, שאינו נחשב כעור. \u0003ור' יוחנן אמר: אפילו עור בית הפרסות נמי\u0004 \u0005[גם כן]\u0006 \u0003מציל.\u0004","בענין זה מסופר, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אסי מר' יוחנן: עור בית הפרסות, מהו שיציל בגלודה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מציל. אמר ליה\u0004 \u0005[לו],\u0006 \u0003למדתנו רבינו\u0004 במשנה לענין טומאה: \u0003אלו\u0004 בעלי חיים \u0003שעורותיהן כבשרן,\u0004 שהעור שלהם נחשב כבשר לטמא טומאת נבלות (שסתם עור אינו מטמא), וביניהם מונים את \u0003עור בית הפרסות! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אל תקניטני,\u0004 אל תקשה עלי ותצערני ממשנה זו, \u0003שבלשון יחיד אני שונה אותה,\u0004 שדעת יחיד היא, שעור בית הפרסות דינו כבשר, וכפי שנאמר להלן בשם ר' שמעון, וחכמים חלוקים על כך, וסבורים שאין עור זה נחשב כבשר.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט את העולה\u0004 על מנת \u0003להקטיר כזית מעור של תחת האליה\u0004 (הזנב) של הכבש \u0003חוץ למקומו,\u0004 חוץ לעזרה — \u0003פסול\u0004 הקרבן, \u0003ו\u0004אולם \u0003אין בו כרת\u0004 אם אכלו. ואם שחט כדי להקטיר עור זה \u0003חוץ לזמנו,\u0004 למחרת — \u0003פגול, וחייבין עליו כרת\u0004 על אכילתו, מפני שעור זה רך הוא, ודינו כבשר הקרבן, שמחשבה בו פוסלת. זו היא דעת חכמים.","\u0003אליעזר בן יהודה איש איבלים אמר משום ר' יעקב, וכן היה ר' שמעון בן יהודה (איש)\u0004 כפר \u0003עיכוס אומר משום ר' שמעון: אחד עור בית הפרסות, ואחד עור הראש של עגל הרך, ואחד עור של תחת האליה, וכל שמנו חכמים גבי טומאה,\u0004 שאמרו ש\u0003אלו שעורותיהן כבשרן,\u0004"],["\u0003להביא\u0004 (לרבות) \u0003עור בית הבושת\u0004 של נקבה, שכל אלו נידונים כבשר, שאם בשעת עבודת הקרבן חישב להקטירו \u0003חוץ למקומו,\u0004 חוץ לעזרה — \u0003פסול, ו\u0004אם אכלו \u0003אין בו כרת.\u0004 ואם חישב להקטירו \u0003חוץ לזמנו,\u0004 למחרת — \u0003פיגול, וחייבים עליו כרת\u0004 על אכילתו. ומכאן שדעה זו, שעור בית הפרסות נחשב כבשר — דעת ר' שמעון היא, וחכמים חולקים עליו, וכמותם סבור ר' יוחנן.","\u0003ואלו טרפות בעוף: נקובת הוושט, ופסוקת הגרגרת,\u0004 שנחתכה הגרגרת (הקנה) שלה לרוחבה. \u0003הכתה חולדה על ראשה\u0004 ב\u0003מקום שעושה אותה טרפה,\u0004 שיש לחשוש שניקב קרום המוח. \u0003ניקב הקורקבן, ניקבו\u0004 המעיים \u0003הדקין. נפלה לאור\u0004 (לאש) \u0003ונחמרו\u0004 (ניכוו) \u0003בני מעיה,\u0004 איבריה הפנימיים, \u0003אם\u0004 נשתנה צבעם ונעשו \u0003ירוקים\u0004 — \u0003פסולים,\u0004 והעוף טריפה, \u0003אם אדומים\u0004 — \u0003כשרים. דרסה\u0004 אדם את העוף ברגליו, \u0003ו\u0004כן אם \u0003טרפה\u0004 הטיח אותה \u0003בכותל, או שריצצתה בהמה,\u0004 \u0003ו\u0004היא \u0003מפרכסת\u0004 — טריפה, שנתרסקו איבריה. \u0003ו\u0004אם \u0003שהתה מעת לעת, ו\u0004אחר כך \u0003שחטה\u0004 — הרי זו \u0003כשרה.\u0004","על מה ששנינו במשנה: הכתה חולדה על ראשה במקום שעושה אותה טריפה, שיש לחשוש שנעשה נקב בקרום המוח, \u0003רב ושמואל ולוי דאמרי\u0004 \u0005[שאומרים]:\u0006 כיצד בודקים אם ניקב הקרום? לאחר ששחט את העוף \u0003מכניס ידו לפנים\u0004 לפי העוף ודוחק את המוח באצבעו \u0003ובודק, אם מבצבץ ועולה\u0004 המוח דרך הנקב שבגולגולת — \u0003טרפה,\u0004 שסימן הוא שניקב קרום המוח, וכך יצא המוח לעבר הנקב שבגולגולת. \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003כשרה.\u0004","ושואלים: אופן זה של בדיקה, האם המוח יוצא דרך הנקב שבגולגולת, \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 לעיל (מה,א) שאם ניקב הקרום העליון, הסמוך לגולגולת, אינה טריפה \u0003עד דמנקיב קרמא תתאה\u0004 \u0005[שניקב\u0006 גם \u0005הקרום התחתון]\u0006 העוטף את המוח, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאפילו כאשר \u0003אינקיב עילאה אף על גב דלא אינקב תתאה\u0004 \u0005[ניקב העליון אף על פי שלא ניקב התחתון]\u0006 טריפה היא, מדוע היא כשרה? \u0003ניחוש דלמא עילאה אינקיב\u0004 \u0005[נחשוש שמא\u0006 הקרום \u0005העליון ניקב],\u0006 \u0003תתאה לא אינקיב\u0004 \u0005[התחתון לא ניקב],\u0006 ולכן המוח אינו מבצבץ! ומשיבים: \u0003אי איתא דאינקיב עילאה\u0004 \u0005[אם אכן ניקב הקרום העליון],\u0006 \u0003תתאה אגב רוככיה מיפקע פקע\u0004 \u0005[התחתון מחמת רכותו היה פוקע\u0006 באותו מקום\u0005]\u0006 והמוח היה מבצבץ, ומשלא ביצבץ מוכח שהקרום העליון לא ניקב.","בניגוד לרב ושמואל ולוי, \u0003אמר זעירי: אין בדיקה\u0004 זו מועילה \u0003ל\u0004נשיכת \u0003חולדה, מפני ששיניה\u0004 של החולדה \u0003דקות,\u0004 ואין המוח מבצבץ דרך נקבים דקים כל כך, אף כשניקב קרום המוח. ושואלים: \u0003וכי שיניה דקות, מאי הוי\u0004 \u0005[מה בכך]?\u0006 והרי אי אפשר שלא יבצבץ מעט! \u0003אמר רב אושעיא: מפני ששיניה דקות ועקומות,\u0004 והנקב שבגולגולת אינו עומד כנגד הנקב שבקרום, ואם כן, אף שניקב הקרום פעמים שהמוח אינו יוצא החוצה דרך הנקב שבגולגולת.","מסופר \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 זעירי \u0003לנהרדעא שלח להו\u0004 \u0005[להם]\u0006 לחכמים: \u0003דברים שאמרתי לפניכם\u0004 שאין בדיקה לחולדה — \u0003טעות הן בידי, ברם\u0004 \u0005[ובאמת]\u0006 \u0003כך אמרו משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' שמעון בן לקיש: בודקין לחולדה ביד,\u0004 שלוחצים את מוחו של העוף מבפנים לראות אם המוח יוצא דרך הנקב, \u0003אבל לא במסמר,\u0004 שאין מעבירים ראש מסמר על קרום המוח לאחר שפתחו את הגולגולת, לראות אם הוא מתעכב בנקב, שמא המסמר עצמו ינקב את הקרום. \u0003ור' יוחנן אמר: אף במסמר\u0004 בודקים.","ומעירים: \u0003ו\u0004בדיקה זו לנשיכת חולדה שנויה \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 תנאים, שמסופר על \u0003ר' יהודה ור' נחמיה, חד בדיק בידא\u0004 \u0005[אחד היה בודק ביד],\u0006 \u0003וחד בדיק במחטא\u0004 \u0005[ואחד היה בודק במחט],\u0006 כמו במסמר. ומסבירים את טעמיהם. \u0003מאן דבדיק בידא אמר ליה למאן דבדיק במחטא\u0004 \u0005[מי שבודק ביד אומר לו למי שבודק במחט]:\u0006 \u0003עד מתי אתה מכלה ממונן של ישראל,\u0004 שעל ידי כך פעמים שאתה מטריף שלא כדין, שהמחט עושה נקב שלא היה שם מתחילה! \u0003אמר ליה מאן דבדיק במחטא למאן דבדיק בידא\u0004 \u0005[אומר לו מי שבודק במחט למי שבודק ביד]:\u0006 \u0003עד מתי אתה מאכיל לישראל נבלות,\u0004 שאתה מכשיר שלא כדין!","ותוהים: \u0003נבלות? והא\u0004 \u0005[והרי]\u0006 \u0003שחוטה היא,\u0004 ואף שהיא טריפה, אינה נבילה! \u0003אלא:\u0004 עד מתי אתה מאכיל לישראל \u0003טרפות,\u0004 שכן יש לחשוש \u0003שמא ניקב קרום של מוח,\u0004 והבדיקה הנעשית ביד פעמים שאינה גורמת למוח לבצבץ, מפני ששיני החולדה דקות ועקומות.","ומעירים לענין זה: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' יהודה הוא דבדיק בידא\u0004 \u0005[שבדק ביד],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' יהודה: בודקין לחולדה ביד, אבל לא במסמר.\u0004 ועוד נאמר בברייתא: \u0003נשבר העצם אף על פי שלא ניקב קרום של מוח\u0004 — הרי זו טריפה. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכן הוא.","לגופה של אותה ברייתא שואלים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003בודקין לחולדה ביד אבל לא במסמר\u0004 — \u0003אלמא אית ליה בדיקותא\u0004 \u0005[מכאן\u0006 ש\u0005יש לה בדיקה],\u0006 \u0003והדר תני\u0004 \u0005[ואתה חוזר ושונה]\u0006 \u0003נשבר העצם\u0004 הרי זו טריפה \u0003אף על פי שלא ניקב קרום של מוח\u0004 — \u0003אלמא לית ליה בדיקותא\u0004 \u0005[מכאן\u0006 ש\u0005אין לה בדיקה],\u0006 שאם היתה לה בדיקה יתכן שהיתה נמצאת כשרה! ומסבירים: \u0003סיפא אתאן\u0004 \u0005[בסוף הגענו]\u0006 \u0003לעוף של מים,\u0004 שאין לו בדיקה אם נשבר העצם, \u0003הואיל ואין לו קרום\u0004 למוחו. ותוהים: \u0003אין לו קרום סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הרי ודאי יש לו קרום! \u0003אלא\u0004 אמור: \u0003הואיל וקרומו רך\u0004 לא יתכן שלא ניקב כשנשברה הגולגולת. בדומה לכך מסופר,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב ענן: מר אמר\u0004 \u0005[אדוני אומר]\u0006 ש\u0003שמואל בדיק בידא ומכשר\u0004 \u0005[בודק ביד\u0006 עוף שהכתה חולדה בראשו, \u0005ומכשיר]\u0006 אם לא ניקב קרום המוח, \u0003ו\u0004כן \u0003הונא חברין אמר\u0004 \u0005[חברנו אומר]\u0006 ש\u0003רב בדיק בידא ומכשר\u0004 \u0005[בודק ביד ומכשיר].\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003לוי\u0004 בברייתא שבידו: \u0003טרפות שמנו חכמים בבהמה\u0004 — \u0003כנגדן\u0004 טריפות גם \u0003בעוף, יתר עליהן\u0004 טריפה ב\u0003עוף\u0004 — ש\u0003נשבר העצם\u0004 של הגולגולת \u0003אף על פי שלא ניקב קרום של מוח,\u0004 ואם כן, מה טעם לבדיקה ביד? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ההוא,\u0004 מה ששנה לוי — \u0003בעוף של מים\u0004 נאמר, שאין לו בדיקה, \u0003הואיל ואין לו קרום.\u0004 ותוהים: \u0003אין לו קרום סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 \u0003אלא\u0004 אמור: \u0003הואיל וקרומו רך.\u0004","וכן מסופר, \u0003ההיא תרנגולתא דהואי בי\u0004 \u0005[תרנגולת אחת שהיתה בבית]\u0006 \u0003רב חנא\u0004 שהיה בה חשש טריפה, \u0003שדרה לקמיה\u0004 \u0005[שלח אותה לפני]\u0006 \u0003רב מתנא,\u0004 בדק אותה רב מתנא ומצא כי \u0003נשבר העצם ולא ניקב קרום של מוח הואי\u0004 \u0005[היה],\u0006 \u0003ואכשרה\u0004 \u0005[והכשיר אותה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חנא לרב מתנא, \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003לוי: טרפות שמנו חכמים בבהמה\u0004 — \u0003כנגדן בעוף\u0004 גם כן טריפות. \u0003יתר עליהן עוף\u0004 — \u0003נשבר העצם אף על פי שלא ניקב קרום של מוח! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בעוף של מים, הואיל ואין לו קרום.\u0004 ותוהים: \u0003אין לו קרום סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003הואיל וקרומו רך.\u0004","מסופר, \u0003רב שיזבי בדיק בשימשא\u0004 \u0005[היה בודק\u0006 את מוח העוף \u0005ב\u0006אור \u0005שמש]\u0006 \u0005אם יש נקב בקרום,\u0006 \u0003רב יימר בדיק במיא\u0004 \u0005[היה בודק במים],\u0006 שופך מים לגולגולת דרך הנקב, לראות אם הם יוצאים צלולים כבתחילה, או אם מעורב בהם נוזל המוח. \u0003רב אחא בר יעקב בדיק\u0004 \u0005[היה בודק]\u0006"],["\u0003בגילא דחיטתא\u0004 \u0005[בקש של חיטה],\u0006 שלאחר שחתך את הגולגולת העביר קש על המוח לראות אם הקש מתעכב בנקב שבקרום.","\u0003אמר רב שיזבי: הני אווזי דידן\u0004 \u0005[אותם אווזים שלנו],\u0006 \u0003כעוף של מים דמיין\u0004 \u0005[נחשבים],\u0006 שאם נשברה הגולגולת, למרות שלא ניקב קרום המוח — הרי זה טריפה.","שנינו במשנה: \u0003נפלה לאור\u0004 ונחמרו (נכוו) בני מעיה, אם נעשו ירוקים — פסולים, אם אדומים — כשרים. \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי בן יהושע: שיעור\u0004 (גודל) \u0003ירוקתן\u0004 של בני מעיים לעשות טריפה כשהפכו ירוקים — \u0003כשיעור נקובתן,\u0004 כמו שיעור הנקב העושה טריפה, \u0003מה נקובתן במשהו,\u0004 שבאיברים שהנקב בהם עושה טריפה — אפילו נקב כלשהו עושה טריפה — \u0003אף ירוקתן במשהו.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע בן לוי מר' יהושע בן לוי:\u0004 אם \u0003הוריקה\u0004 (נעשה ירוק) \u0003כבד\u0004 של תרנגולת בצד ש\u0003כנגד בני\u0004 ה\u0003מעיים, מהו\u0004 דין התרנגולת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003טרפה.\u0004 אמר לו: \u0003ולא יהא\u0004 דינו \u0003אלא\u0004 כדין \u0003ניטלה\u0004 הכבד ונשתייר ממנו כזית, שהיא כשרה (לעיל נד,א). ואם כן, רק אם לא נשאר בכבד כזית שאינו ירוק תיעשה טריפה! \u0003אמר רבא: כיון שהוריקה כבד כנגד בני מעיים\u0004 — \u0003בידוע שנפלה\u0004 התרנגולת \u0003לאור, ונחמרו\u0004 (נשרפו) \u0003בני מעיים\u0004 עצמם, \u0003ו\u0004לכן היא \u0003טרפה,\u0004 ולא בגלל הכבד עצמו.","מסופר, \u0003ר' יהושע בן לוי הויא ליה ההיא תרנגולת\u0004 \u0005[היתה לו תרנגולת אחת]\u0006 שנפלה לאור, ולאחר שנשחטה \u0003שדריה לקמיה\u0004 \u0005[שלח אותה לפני]\u0006 \u0003ר' אלעזר הקפר בריבי\u0004 (הגדול) ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ירוקין הוו\u0004 \u0005[היו]\u0006 בני המעיים, \u0003ואכשרה\u0004 \u0005[הכשיר אותה]\u0006 ר' אלעזר הקפר. הקשה לו ר' יהושע בן לוי: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ירוקין פסולין!\u0004 אמר לו: \u0003לא אמרו ירוקין פסולין אלא בקורקבן, בלב ובכבד,\u0004 שהם אדומים בדרך כלל, ונשתנה מראם. אבל בני המעיים האחרים של התרנגולת, כגון הדקים — ירוקים הם מתחילתם, ואין זו טריפה. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]:\u0006 \u0003באלו בני מעיים אמרו,\u0004 שאם נעשו ירוקים הרי זו טריפה? \u0003בקורקבן, בלב ובכבד,\u0004 ולא בשאר בני מעיים.","מסופר, \u0003ר' יצחק בר יוסף הוה ליה ההוא תרנגולתא\u0004 \u0005[היתה לו תרנגולת אחת]\u0006 שנפלה לאור, ולאחר שנשחטה \u0003שדרה לקמיה\u0004 \u0005[שלח אותה לפני]\u0006 \u0003רבי אבהו, ואמר ליה\u0004 \u0005[לו]\u0006 \u0003אדומין הוו\u0004 \u0005[היו]\u0006 בני המעיים, \u0003וטרפה\u0004 \u0005[והטריף אותה]\u0006 ר' אבהו. הקשה לו ר' יצחק בר יוסף, \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]:\u0006 \u0003אדומין כשרים! אמר ליה\u0004 \u0005[לו]\u0006 בני מעיים \u0003אדומין שהוריקו, וירוקין שהאדימו\u0004 — \u0003טרפה; לא אמרו\u0004 במשנה \u0003אדומין כשרים אלא בלב בקורקבן ובכבד\u0004 לפי שהם אדומים מעיקרם, אבל כגון הדקין, שירוקים הם מתחילתם, והאדימו — טריפה היא.","\u0003אמר רב שמואל בר חייא אמר ר' מני: אדומין שהוריקו ושלקן\u0004 (ובישל אותם) \u0003וחזרו והאדימו\u0004 — \u0003כשרין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 דבר זה מלמד שלא נשרפו ממש, אלא \u0003קוטרא עייל בהו\u0004 \u0005[עשן\u0006 בלבד \u0005נכנס בהם],\u0006 ושינה צבעם לפי שעה. \u0003אמר רב נחמן בר יצחק, אף אנן\u0004 \u0005[אנו]\u0006 \u0003נאמר\u0004 כהמשך לכך: \u0003אדומין שלא הוריקו, ושלקן והוריקו\u0004 — \u0003טרפה, מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003איגלאי בהתייהו\u0004 \u0005[התגלתה בושתם],\u0006 כלומר, התגלה על ידי הבישול שכבר נשרפו מתחילה. \u0003אמר רב אשי: הלכך\u0004 \u0005[מכאן]\u0006 יש להורות: \u0003לא ליכול אינש אלא בשלקא\u0004 \u0005[לא יאכל אדם\u0006 עוף שנפל לאור \u0005אלא בבישול],\u0006 למרות שהאיברים האדומים (לב, קורקבן וכבד) שבו לא הוריקו, שהרי רק באופן זה ניתן לומר בוודאות שלא נשרפו. ודוחים: \u0003ולא היא\u0004 \u0005[ואין הדבר כן],\u0006 שכן \u0003אחזוקי ריעותא לא מחזקינן\u0004 \u0005[להחזיק ריעות,\u0006 פגם \u0005בדבר אין אנו מחזיקים],\u0006 כשאין לפנינו סימן לדבר.","שנינו במשנה: \u0003דרסה\u0004 אדם את העוף ברגליו, \u0003ו\u0004כן אם \u0003טרפה\u0004 (חבט אותה) \u0003בכותל,\u0004 או שריצצתה בהמה, אם שהתה מעת לעת ושחטה — כשרה. \u0003אמר ר' אלעזר בן אנטיגנוס משום\u0004 (בשם) ר' אלעזר בר' ינאי: \u0003אחת זו ואחת זו,\u0004 כלומר, כל אחת מאלו ששנינו, אפילו שהתה מעת לעת — \u0003צריכה בדיקה\u0004 לאחר שחיטה, שמא נשברה השדרה ונפסק חוט השדרה, וכיוצא בזה.","\u0003ואלו כשרות בעוף: ניקבה הגרגרת\u0004 (הקנה), \u0003או שנסדקה\u0004 לאורכה. \u0003הכתה חולדה על ראשה\u0004 ב\u0003מקום שאינו עושה אותה טרפה,\u0004 שלא כנגד המוח. \u0003ניקב הזפק,\u0004 מעין כיס התלוי בתחתית הוושט, שהאוכל שוהה בו קודם שהוא עובר לקורקבן לצורך העיכול, \u0003רבי אומר: אפילו ניטל\u0004 הזפק — כשרה. \u0003יצאו בני מעיה\u0004 מדופן הבטן \u0003ולא ניקבו, נשתברו גפיה\u0004 (כנפיה), או \u0003נשתברו רגליה,\u0004 או \u0003נמרטו\u0004 נוצות \u0003כנפיה\u0004 — כשרה. \u0003ר' יהודה אומר: אם נטלה הנוצה\u0004 הדקה המכסה את גופה — \u0003פסולה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' סימאי ור' צדוק שהלכו לעבר שנה בלוד ושבתו ב\u0004עיר \u0003אונו, והורו בטרפחת\u0004 (ברחם) הבהמה שניטלה, \u0003כרבי\u0004 שהתיר במשנתנו \u0003בזפק\u0004 העוף שניטל.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים מה כוונת ברייתא זו: האם מדובר בשני מעשים שונים, \u0003ש\u0004\u0003הורו בטרפחת\u0004 שניטלה — \u0003לאיסורא\u0004 \u0005[לאיסור],\u0006 והורו \u0003כרבי בזפק\u0004 — \u0003להתירא\u0004 \u0005[להיתר].\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 מעשה אחד הוא, ש\u0003הורו בטרפחת\u0004 שניטלה \u0003להתירא\u0004 \u0005[להיתר]\u0006 \u0003כ\u0004שיטת \u0003רבי\u0004 שמתיר \u0003בזפק, אבל כרבי בזפק\u0004 עצמו \u0003לא סבירא להו\u0004 \u0005[אינם סבורים כן]?\u0006 שאלה זו לא נפתרה, ונשארה \u0003ב\u0004\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר רבה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: גגו\u0004 (חלקו העליון) \u0003של זפק נידון כוושט,\u0004 שנקב כלשהו בו עושה טריפה. ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 הוא הקרוי גגו של זפק? \u0003אמר רב ביבי בר אביי: כל שנמתח עמו,\u0004 עם הוושט.","שנינו במשנה: \u0003יצאו בני מעיה\u0004 של העוף ולא ניקבו — כשרה. \u0003אמר ר' שמואל בר רב יצחק: לא שנו\u0004 כן \u0003אלא\u0004 כ\u0003שלא היפך בהן\u0004 בבני המעיים, שהחזירם למקומם כמות שהן, \u0003אבל היפך בהן\u0004 — \u0003טרפה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הוא עשך ויכוננך\"\u0004 (דברים לב, ו) — \u0003מלמד שברא הקדוש ברוך הוא כונניות באדם,\u0004 איברים שיושבים כל אחד על מקומו באופן הראוי, \u0003שאם נהפך אחת מהן\u0004 — \u0003אינו יכול לחיות,\u0004 וכיוצא בזה ביצורים אחרים, שאם הופך את איבריהם אינם יכולים לחיות.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר\u0004 על אותו כתוב \u0003\"הוא עשך ויכוננך\"\u0004 שהוא מדבר על עם ישראל — \u0003כרכא דכולה ביה\u0004 \u0005[כרך שהכל בו],\u0006 \u0003ממנו כהניו, ממנו נביאיו, ממנו שריו, ממנו מלכיו, שנאמר: \"ממנו פנה ממנו יתד\u0004 ממנו קשת מלחמה\" (זכריה י, ד), כלומר, ממנו עצמו מצויים הדברים המחזיקים אותו ומגינים עליו.","מסופר, \u0003ההוא רומאה דחזייה לההוא גברא דנפל מאיגרא לארעא\u0004 \u0005[רומאי אחד שראה אדם שנפל מהגג לארץ],\u0006 \u0003פקעיה כרסיה ונפוק מעייניה\u0004 \u0005[\u0006ו\u0005פקעה כריסו\u0006 של הנופל \u0005ויצאו בני מעיו],\u0006 \u0003אתייה לבריה ושחטיה קמיה\u0004 \u0005[הביא\u0006 אותו רומאי \u0005את\u0006 בנו של אותו נופל \u0005ושחט אותו לפניו]\u0006"],["\u0003באחוזת עינים,\u0004 כלומר, איחז את עיני האב, כאילו הבן נשחט, \u0003אינגיד ואיתנח\u0004 \u0005[נמשך,\u0006 נמתח האב \u0005ונאנח],\u0006 \u0003עול למעייניה\u0004 \u0005[נכנסו בני המעיים]\u0006 על ידי התנועה הזו למקומם, \u0003וחייטיה לכרסיה\u0004 \u0005[ותפר את כריסו],\u0006 ונרפא.","שנינו במשנה: \u0003נשתברו רגליה\u0004 של העוף — כשרה. מסופר, \u0003ההוא צנא דאינקורי דאתיא לקמיה\u0004 \u0005[סל מלא עופות\u0006 שבורי רגלים \u0005שבאה לפני]\u0006 \u0003רבא, בדקיה\u0004 \u0005[בדק אותם]\u0006 \u0003רבא בצומת הגידין\u0004 הנמצא בתחתית עצם השוק, וראה שכל הגידים שלמים, \u0003ואכשריה\u0004","\u0005[והכשיר אותו].\u0006 \u0003אמר רב יהודה אמר רב: שמוטת יד\u0004 (הרגל הקדמית) \u0003בבהמה,\u0004 כלומר, שנקעה היד ממקומה בכתף — \u0003כשרה, שמוטת ירך\u0004 שיצאה עצם הירך ממקומה \u0003בעוף\u0004 — \u0003טרפה. שמוטת גף\u0004 (כנף) \u0003בעוף,\u0004 שיצאה ממקום חיבורה בגב העוף — \u0003טרפה,\u0004 ומדוע? \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא ניקבה הריאה,\u0004 שמקום חיבור הגף סמוך לריאה, וכשהיא ניתקת יש חשש שניתק עמה חלק מן הריאה. \u0003ושמואל אמר: תיבדק\u0004 הריאה, ואם יש בה נקב הריהי טריפה. \u0003וכן אמר ר' יוחנן: תיבדק.\u0004","ובענין זה מובאת מחלוקת, \u0003חזקיה,\u0004 בנו של ר' חייא, \u0003אמר: אין ריאה לעוף, ור' יוחנן אמר: יש לו\u0004 ריאה לעוף, \u0003וישנה\u0004 (והיא נראית) \u0003כעלה של וורד,\u0004 דקה ואדומה, \u0003בין אגפים\u0004 (הכנפיים). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין ריאה לעוף\u0004 שאמר חזקיה? \u0003אילימא דלית ליה\u0004 \u0005[אם תאמר שאין לו]\u0006 \u0003כלל\u0004 ריאה — \u0003והא\u0004 \u0003קא חזינא דאית ליה\u0004 \u0005[והרי אנו רואים שיש לו]\u0006 ריאה! \u0003אלא\u0004 תאמר שכוונתו היתה \u0003דלא מיטריף ביה\u0004 \u0005[שאין בה טריפה]\u0006 אם ניקבה — \u0003והתני\u0004 \u0005[והרי\u0006 שנה] \u0003לוי\u0004 בברייתא: \u0003טרפות שמנו חכמים בבהמה\u0004 — \u0003כנגדן\u0004 גם \u0003בעוף\u0004 טריפה, \u0003יתר עליהן עוף\u0004 — אם \u0003נשבר העצם\u0004 של הגולגולת, שהוא טריפה \u0003אף על פי שלא\u0004 ראינו ש\u0003ניקב קרום של מוח!\u0004","\u0003אלא\u0004 תאמר שהכוונה היא ש\u0003אין לו\u0004 לריאה של העוף, \u0003לא לינפל\u0004 \u0005[דין נפילה],\u0006 שאם נפל — אין חוששים שנתרסקה הריאה, ואינה צריכה בדיקה כפי שחוששים באיברים אחרים (לעיל נא,ב), \u0003ולא ליחמר\u0004 \u0005[דין נחמרה],\u0006 שאם נפל העוף לאש — אין חוששים שנכוותה הריאה, כמו בשאר בני מעיה שבודקים אם נעשו ירוקים (לעיל נו,א); \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב חנה:\u0004 \u0003הואיל ורוב צלעותיה\u0004 של העוף \u0003מגינות עליה\u0004 על הריאה;","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003מ\u0004מה ש\u0003אמר ר' יוחנן\u0004 בתגובה לדברי חזקיה: \u0003יש לו\u0004 לעוף ריאה, \u0003וישנה כעלה של וורד בין אגפיים\u0004 — \u0003מכלל\u0004 הדברים אתה למד ש\u0003חזקיה\u0004 שאמר אין לו ריאה \u0003סבר דלית ליה\u0004 \u0005[שאין לו]\u0006 כלל ריאה! \u0003אלא\u0004 צריך לומר, כמו ש\u0003אמרי במערבא משמיה\u0004 \u0005[אמרו בארץ\u0006 ישראל משמו] של \u0003ר' יוסי בר' חנינא: מדבריו של בריבי\u0004 (הגדול) חזקיה, \u0003ניכר שאינו בקי\u0004 (מורגל) \u0003בתרנגולין.\u0004","\u0003אמר רב הונא אמר רב: שמוטת ירך בעוף כשרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב הונא לרב הונא, והא רבנן דאתו\u0004 \u0005[והרי חכמים שבאו]\u0006 \u0003מפומבדיתא אמרו\u0004 ש\u0003רב יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר: שמוטת ירך בעוף טרפה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ברי\u0004 \u0005[בני],\u0006 \u0003נהרא נהרא ופשטיה\u0004 \u0005[נהר נהר והילוכו],\u0006 כלומר, מנהגים שונים יש למקומות שונים. ודעתו של רב היתה להיתר, אלא שבפומבדיתא נהגו איסור, וכך פסק להם רב.","ובענין זה מסופר, \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אבא, אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב ירמיה בר אבא דקא בדיק\u0004 \u0005[שהוא בודק]\u0006 בעופות \u0003בצומת הגידין,\u0004 לראות אם ניטל. \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003למה ליה למר כולי האי\u0004 \u0005[למה לו לאדוני כל זה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא אמר\u0004 בשם \u0003רב: שמוטת ירך בעוף כשרה,\u0004 ואם כשכל הירך ניטלה הריהי כשרה, כל שכן אם ניטל רק צומת הגידין, שהוא למטה מן הירך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא מתניתין ידענא\u0004 \u0005[אני\u0006 את \u0005משנתנו אני יודע]\u0006 ועליה אני סומך, ששנינו: \u0003בהמה שנחתכו רגליה מן הארכובה\u0004 (הברך) \u0003ולמטה\u0004 — \u0003כשרה, מן הארכובה ולמעלה\u0004 — הריהי \u0003פסולה\u0004 (טריפה), \u0003וכן שניטל צומת הגידין\u0004 הריהי טריפה, אפילו הארכובה קיימת; \u0003ואמר רב עלה\u0004 \u0005[עליה]:\u0006 \u0003וכן בעוף.\u0004","אמר לו: \u0003אי הכי קשיא\u0004 \u0005[אם כך קשה]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב,\u0004 שמצד אחד אמר ששמוטת הירך בעוף כשרה, ומצד אחר אמר שדין העוף כדין הבהמה, ואם נחתכה הרגל למעלה מן הארכובה — טריפה היא! \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב ירמיה בר אבא, ולא ענה על כך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא: \u0003דלמא שני ליה\u0004 \u0005[שמא שונה לו]\u0006 לרב בעוף \u0003בין שמוטה\u0004 \u0003לחתוכה,\u0004 שאם נשמטה הירך ממקומה — אין זה עושה טריפה, אבל אם נחתכה באמצעה, או אפילו למטה משם — הרי זה טריפה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואת מפרשת שמעתתיה\u0004 \u0005[ואתה הוא המפרש את הלכותיו]\u0006 של \u0003רב\u0004 מסברתך? \u0003בפירוש אמר רב\u0004 כך: \u0003שמוטה\u0004 — \u0003כשרה, חתוכה\u0004 — \u0003פסולה. ואל תתמה\u0004 כיצד יתכן דבר זה, \u0003שהרי\u0004 פעמים \u0003חותכה\u0004 את הבהמה או העוף \u0003מכאן ומתה,\u0004 ואילו \u0003חותכה מכאן\u0004 ממקום אחר \u0003וחיתה\u0004 (וחיה).","מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' אבא\u0004 מבבל לארץ ישראל \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003ר' זירא דיתיב וקאמר\u0004 \u0005[שיושב ואומר],\u0006 \u0003אמר רב הונא אמר רב: שמוטת ירך בעוף\u0004 — \u0003טרפה. אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא: \u0003חיי דמר\u0004 \u0005[בחיי אדוני],\u0006 \u0003מיומא דסליק מר להכא\u0004 \u0005[מיום שעלה אדוני לכאן]\u0006 לארץ ישראל"],["\u0003הוה לן\u0004 \u0005[היה לנו]\u0006 \u0003פתחון פה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא,\u0004 כלומר, היתה לי הזדמנות לשוחח עם רב הונא, \u0003ושאילניה\u0004 \u0005[ושאלתי אותו]\u0006 בענין זה, \u0003ואמר לן\u0004 \u0005[לנו]:\u0006 \u0003שמוטת ירך בעוף כשירה.\u0004","\u0003ואשכחתיה נמי\u0004 \u0005[ומצאתי אותו גם כן]\u0006 את \u0003ר' ירמיה בר אבא דיתיב וקא בדיק\u0004 \u0005[שיושב ובודק]\u0006 \u0003בצומת הגידין\u0004 של עוף האם ניטל, \u0003ואקשי ליה\u0004 \u0005[והקשיתי לו]:\u0006 וכי \u0003לא סבר לה מר הא\u0004 \u0005[אין אדוני סבור\u0006 את \u0005זו]\u0006 ש\u0003אמר רב הונא אמר רב: שמוטת ירך בעוף כשרה?\u0004 ואם נשמטה הירך כולה כשרה — כל שכן שניטל צומת הגידים! \u0003אמר לי: אנא מתניתין ידענא\u0004 \u0005[אני\u0006 את \u0005משנתנו אני יודע],\u0006 ששנינו בה: \u0003בהמה שנחתכו רגליה, מן הארכובה ולמטה\u0004 — \u0003כשרה, מן הארכובה ולמעלה\u0004 — \u0003פסולה, וכן\u0004 הדין כ\u0003שניטל צומת הגידין,\u0004 אפילו לא נחתכו רגליה; \u0003ואמר רב עלה\u0004 \u0005[עליה]:\u0006 \u0003וכן בעוף.\u0004","\u0003ואמרי ליה\u0004 \u0005[ואמרתי לו]:\u0006 \u0003אי הכי קשיא\u0004 \u0005[אם כך קשה]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב,\u0004 שאמר ששמוטת הירך בעוף כשרה, שהרי אפילו נחתכו רגליה למטה משם הריהי טריפה לדעתו! \u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' ירמיה בר אבא. \u0003ואקשי ליה\u0004 \u0005[והקשיתי לו]:\u0006 \u0003ודלמא שני ליה\u0004 \u0005[ושמא שונה לו]\u0006 \u0003לרב בין שמוטה לחתוכה,\u0004 ששמוטה כשרה, וחתוכה טריפה? \u0003ואמר לי: ואת מפרשת שמעתיה\u0004 \u0005[ואתה הוא המפרש את שמועתו]\u0006 של \u0003רב? בפירוש\u0004 כך \u0003אמר רב: שמוטה\u0004 — \u0003כשרה, חתוכה\u0004 — \u0003פסולה.\u0004","לאחר שסיפר דברים אלו לר' זירא, שאלו: \u0003ואת, מה בידך\u0004 \u0005[ואתה מה בידך]?\u0006 כלומר, מה שמעת בענין זה? \u0003אמר לו:\u0004 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חייא בר אשי אמר רב: שמוטת ירך בעוף טרפה, וכן אמר ר' יעקב בר אידי\u0004 ש\u0003אמר ר' יוחנן: שמוטת ירך בעוף טרפה. ו\u0004בענין זה","\u0003אמר ר' יעקב בר אידי: אילמלי הוה\u0004 \u0005[אילו היה]\u0006 \u0003ר' יוחנן באתרא דאורו בה חברוותא להתירא\u0004 \u0005[במקום שהורו בו בני החבורה להיתר]\u0006 \u0003לא פרכיס\u0004 \u0005[לא היה מפרכס],\u0006 לא היה מערער על כך, שהיו אלו גדולי הדור שלפניו. שכך \u0003אמר ר' חנינא אמר רבי: שמוטת ירך בעוף כשרה. ותרנגולת היתה לו לר' חנינא שנשמטה ירך שלה, והביאה לפני רבי והתירה לו. ומלחה ר' חנינא,\u0004 כדי לשמרה לזמן רב, \u0003והוה מורי\u0004 \u0005[והיה מורה]\u0006 \u0003בה הלכה לתלמידים,\u0004 שהיה מראה אותה להם ואומר: \u0003זה התיר לי רבי, זה התיר לי רבי.\u0004","ואומרים לסיכום: \u0003ולית הלכתא ככל הני שמעתתא\u0004 \u0005[ואין הלכה ככל השמועות הללו שאמרנו],\u0006 \u0003אלא כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003שאל ר' יוסי בן נהוראי את ר' יהושע בן לוי: קדירת\u0004 (נקיבת) \u0003קנה בכמה\u0004 עושה טריפה? \u0003אמר לו: משנה שלמה שנינו, עד כאיסר האיטלקי\u0004 היא כשרה, וביותר מכך — טריפה. \u0003אמר לו: והלא רחל\u0004 (כבשה) \u0003אחת היתה בשכונתנו שנקדר\u0004 (ניקב) \u0003קנה שלה\u0004 ביותר מכדי שיעור זה, \u0003ועשו לה\u0004 באותו מקום סתימה באמצעות \u0003קרומין\u0004 (קליפה) \u0003של קנה\u0004 \u0003וחיתה!\u0004","\u0003אמר לו: ועל דא את סמיך\u0004 \u0005[ועל\u0006 מעשה \u0005זה אתה סומך]\u0006 כדי להקשות ממנו? \u0003והלא הלכה רווחת\u0004 (נפוצה) \u0003בישראל: שמוטת ירך בעוף טרפה. ו\u0004עם כל זה ראינו ש\u0003תרנגולת היתה לו לר' שמעון בן חלפתא שנשמטה ירך שלה, ועשו לה\u0004 מעין קיבוע על ידי \u0003שפופרת של קנה\u0004 כדי לתמוך בירך, \u0003וחיתה! אלא, מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 לגבי המקרה הזה? ש\u0003תוך שנים עשר חדש\u0004 מזמן שנשמטה הירך \u0003הוה\u0004 \u0005[היה]\u0006 הדבר, ובסוף שנים עשר חודש מתה, שטריפה יכולה לחיות רק עד שנים עשר חודש. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במעשה שניקב קנה שלה, ועשו לה קרומין של קנה וחיתה — \u0003תוך שנים עשר חדש הוה\u0004 \u0005[היה].\u0006","אגב כך אומרים: אמרו עליו על ר' שמעון בן חלפתא \u0003שעסקן בדברים היה,\u0004 חוקר ובודק בעניינים שונים, \u0003והיה עושה דבר להוציא מלבו של ר' יהודה,\u0004 כלומר, ממה שהיה סבור ר' יהודה, \u0003שהיה ר' יהודה אומר: אם ניטלה הנוצה\u0004 (הפלומה) של העוף — \u0003פסולה,\u0004 וכפי ששנינו במשנתנו בשמו. \u0003ותרנגולת היתה לו לר' שמעון בן חלפתא שניטלה נוצה שלה, והניחה\u0004 את התרנגולת \u0003בתנור,\u0004 במקום חם, \u0003וטלה עליה\u0004 כיסה אותה \u0003במטלית של טרסיים\u0004 (צורפי נחושת), \u0003ו\u0004לאחר זמן \u0003גידלה כנפיים האחרונים יותר מן הראשונים.\u0004 ותוהים: מה הפירכה מכאן לדברי רב יהודה?","\u0003ודלמא קסבר\u0004 \u0005[ושמא סבור]\u0006 \u0003ר' יהודה\u0004 ש\u0003טרפה\u0004 לא רק שהיא חיה, אלא אפילו \u0003משבחת,\u0004 ייתכן שתהיה בריאה יותר מאשר היתה קודם! ודוחים: גם \u0003אם כן,\u0004 האם היה אומר כן גם \u0003במידי דמיטרפא בה\u0004 \u0005[באותו דבר\u0006 עצמו \u0005שנעשתה בה טריפה],\u0006 וכפי שהיה כאן, ש\u0003הגדילה כנפיים האחרונים יותר מן הראשונים?!\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 שנאמר על ר' שמעון בן חלפתא שהיה \u0003עסקן בדברים?\u0004 מהיכן בא לו כינוי זה? \u0003אמר רב משרשיא,\u0004 שראה מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לך אל נמלה עצל ראה דרכיה וחכם, אשר אין לה קצין שוטר ומושל, תכין בקיץ לחמה\"\u0004 (משלי ו, ו—ח), \u0003אמר: איזיל איחזי אי ודאי הוא דלית להו מלכא\u0004 \u0005[אלך ואראה אם ודאי הוא שאין להם מלך]!\u0006","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003בתקופת תמוז,\u0004 בקיץ, בשעה שהשמש מאירה בחוזק. והואיל והנמלים שונאות חום גדול, \u0003פרסיה לגלימיה אקינא דשומשמני\u0004 \u0005[פרס את גלימתו על חור של נמלים],\u0006 כדי להצל עליו, \u0003נפק אתא חד מינייהו\u0004 \u0005[יצא ובא אחד מהם,\u0006 מן הנמלים\u0005],\u0006 והבחין בצל. \u0003אתנח ביה סימנא\u0004 \u0005[הניח בו\u0006 ר' שמעון בן חלפתא \u0005סימן]\u0006 באותה נמלה. \u0003על, אמר להו נפל טולא\u0004 \u0005[נכנסה\u0006 אותה נמלה, \u0005אמרה להם\u0006 לשאר הנמלים: \u0005נפל צל],\u0006 \u0003נפקו ואתו\u0004 \u0005[יצאו ובאו]\u0006 כל הנמלים מן הקן לעבודתם. \u0003דלייה לגלימיה\u0004 \u0005[הרים\u0006 ר' שמעון בן חלפתא \u0005את גלימתו],\u0006 \u0003נפל\u0004 עליהם \u0003שמשא\u0004 \u0005[\u0006אור \u0005השמש],\u0006 \u0003נפלו עליה וקטליה\u0004 \u0005[התנפלו עליו השאר\u0006 על אותה נמלה \u0005והרגוה].\u0006 \u0003אמר\u0004 ר' שמעון: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבאמת \u0003לית להו מלכא\u0004 \u0005[אין להם מלך],\u0006 \u0003דאי אית להו\u0004 \u0005[שאם יש להם]\u0006 מלך, וכי \u0003הרמנא דמלכא לא ליבעו\u0004 \u0005[רשות, הוראה מן המלך לא היו צריכים]\u0006 להריגה זו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: ודלמא מלכא הוה בהדייהו\u0004 \u0005[ושמא המלך היה איתם]\u0006 ולא הכיר אותו? \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003הרמנא דמלכא הוו נקיטי\u0004 \u0005[רשיון של המלך היה בידם]\u0006 לעשות כן. \u0003אי נמי בין מלכא למלכא הוה\u0004 \u0005[או גם כן\u0006 בזמן ש\u0005בין מלך למלך היה]\u0006 אירוע זה, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 כיוצא בזה: \u0003\"בימים ההם אין מלך בישראל איש הישר בעיניו יעשה\"\u0004 (שופטים יז, ו)? \u0003אלא\u0004 בהכרח, \u0003סמוך אהימנותא\u0004 \u0005[\u0006צריכים אנו \u0005לסמוך על נאמנותו]\u0006 של \u0003שלמה,\u0004 שאמר דברים אלו.","ובענין שהוזכר לעיל, מביאים מה ש\u0003אמר רב הונא: סימן לטרפה\u0004 — \u0003שנים עשר חדש,\u0004 שבעל חיים שהוא ספק טריפה, אם לא מת בתוך שנים עשר חודש — סימן הוא שאינו טריפה. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003סימן לטרפה\u0004 — \u0003כל שאינה יולדת. רבן שמעון בן גמליאל אומר:\u0004 אם \u0003משבחת\u0004 (משתבחת) \u0003והולכת\u0004 — \u0003בידוע שהיא כשרה,\u0004 אם \u0003מתנוונה\u0004 (נחלשת) \u0003והולכת\u0004 — \u0003בידוע שהיא טרפה. רבי אומר: סימן לטרפה\u0004 — כל שלא חיה \u0003שלשים יום. אמרו לו: והלא הרבה\u0004 מן הטריפות ששנו חכמים \u0003מתקיימות שתים שלש שנים!\u0004 ועל כל פנים, אף לא אחד מן התנאים שבברייתא הזכיר שנים עשר חודש, כפי שאמר רב הונא!","ומשיבים: \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא,\u0004 ויש תנא הסבור כרב הונא. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ובגלגלת שיש בה נקב אחד ארוך,\u0004 או \u0003אפילו נקבים\u0004 קטנים \u0003הרבה\u0004 — \u0003מצטרפים\u0004 כל הנקבים \u0003ל\u0004שיעור \u0003של\u0004 \u0003מלא מקדח\u0004 של רופאים, שנקב בשיעור זה עושה טריפה. \u0003אמר ר' יוסי בן המשולם: מעשה ב\u0004מקום הקרוי \u0003ענבול, ב\u0004אדם \u0003אחד שנפחתה גלגלתו, ועשו לו\u0004 כיסוי באמצעות \u0003חידוק של קרויה\u0004 קליפה של דלעת, \u0003וחיה,\u0004 ומכאן שאינה טריפה! \u0003אמר לו ר' שמעון בן אלעזר:\u0004 וכי \u0003משם,\u0004 ממעשה זה, אתה מביא \u0003ראיה\u0004 שטריפה היא? והרי \u0003ימות החמה היה\u0004 \u0003כשאירע הדבר,\u0004 \u0003וכיון שעברו עליו ימות הצנה מיד מת.\u0004 הרי שלשיטת ר' אלעזר בר' שמעון, כל שמת בתוך שנתו — שעברו עליו ימות החמה וימות הגשמים — טריפה היא, וכשיטתו אמר רב הונא שסימן לטריפה שנים עשר חודש.","\u0003אמר רב אחא בר יעקב, הלכה: טרפה\u0004 גם \u0003יולדת ו\u0004גם \u0003משבחת.\u0004 ולכן, אם בהמה ילדה או השביחה — אין ללמוד מכאן שאינה טריפה. \u0003אמר אמימר: הני ביעי\u0004 \u0005[אותם ביצים של עוף]\u0006 \u0003טרפה,\u0004"],["\u0003שיחלא קמא אסירא\u0004 \u0005[קבוצת הביצים הראשונה\u0006 שהיתה במעיה בשעה שנעשתה טריפה \u0005אסורה],\u0006 משום שהיא חלק מן התרנגולת שנעשתה טריפה. אבל הביצים שנוצרו \u0003מכאן ואילך\u0004 — \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003זה וזה גורם,\u0004 שגם הזכר שותף ביצירתן, והוא אינו טריפה, \u0003ו\u0004כלל הוא שכל זה וזה (איסור והיתר) גורם לו — \u0003מותר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אשי לאמימר\u0004 ממה ששנינו: \u0003ושוין בביצת טריפה שאסורה, מפני ש\u0004הביצה \u0003גדלה באיסור.\u0004 הרי שגם ביצים שנוצרו בה לאחר שנעשתה טריפה — אסורות! אמר לו: \u0003התם בדספנא מארעא\u0004 \u0005[שם\u0006 מדובר בתרנגולת \u0005שמתחממת מהארץ],\u0006 כלומר, שלא הופרתה על ידי זכר, ונמצא שהגורם היחיד לביצה הוא התרנגולת, שהיא טריפה.","ושואלים: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]\u0006 באופן אחר, שמה שנאמר שביצת טריפה אסורה, הוא רק \u0003בשיחלא קמא\u0004 \u0005[בקבוצת הביצים הראשונה],\u0006 משום שהיתה חלק מגוף האם כשנטרפה! ומשיבים: \u0003אם כן\u0004 הלשון \u0003\"מפני ש\u0004\u0003גדלה\u0004 באיסור\", שמשמעה שכל גדילתה היתה באיסור, אינה נכונה, אלא \u0003\"גמרה\u0004 באיסור\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005].\u0006","ושואלים: \u0003אלא\u0004 כיון שאתה מניח שעובר במעי אמו נעשה טריפה כמוה, אם כן \u0003הא דתנן\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 במשנה\u0005]\u0006 בענין \u0003ולד\u0004 בהמה \u0003טרפה,\u0004 ש\u0003ר' אליעזר אומר: לא יקרב לגבי\u0004 (על) \u0003מזבח, ור' יהושע אומר: יקרב, במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003ב\u0004מקרה \u0003שנטרפה\u0004 האם \u0003ולבסוף\u0004 \u0003עיברה\u0004 (נתעברה), שיש שותפות לאב בולד, ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003זה וזה גורם\u0004 — \u0003אסור, ור' יהושע סבר\u0004 \u0005[סבור]:\u0006 \u0003זה וזה גורם\u0004 — \u0003מותר.\u0004 ואולם \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שבעיקרון זה הם חלוקים, \u0003אדמיפלגי\u0004 \u0005[עד שהם חלוקים]\u0006 האם להתיר את הולד \u0003לגבוה,\u0004 לקרבן — \u0003ליפלגו\u0004 \u0005[שיחלקו]\u0006 האם הוא מותר \u0003להדיוט,\u0004 האם ולד בהמה שנטרפה ואחר כך נתעברה מותר באכילה או לא!","ומשיבים: המחלוקת הובאה במקרה זה, כדי \u0003להודיעך כחו\u0004 של \u0003ר' יהושע,\u0004 ש\u0003אפילו לגבוה נמי שרי\u0004 \u0005[גם כן\u0006 הוא \u0005מתיר].\u0006","ומקשים: \u0003וליפלגו\u0004 \u0005[ושיחלקו]\u0006 בענין \u0003הדיוט,\u0004 כדי \u0003להודיעך כחו\u0004 של \u0003ר' אליעזר,\u0004 שלדעתו \u0003אפילו להדיוט נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור!\u0004 ומשיבים: \u0003כח דהיתרא עדיף ליה\u0004 \u0005[כח ההיתר עדיף לו],\u0006 להשמיע לנו עד היכן מגיע ההיתר.","ומסכמים: נמצא איפוא לדרך זו, שמה שנאמר: \u0003ומודים\u0004 שניהם \u0003בביצת טרפה שאסורה\u0004 — מדובר \u0003בדספנא מארעא\u0004 \u0005[ב\u0006תרנגולת \u0005שמתחממת מהאדמה]\u0006 ומטילה ביצים, ולא הופרתה על ידי זכר, והיא אסורה מפני \u0003דחד גורם\u0004 \u0005[שגורם אחד]\u0006 \u0003הוא,\u0004 הטריפה.","ומעירים: \u0003רב אחא סבר לה\u0004 \u0005[סבור היה]\u0006 \u0003כ\u0004שיטת \u0003רב אחא בר יעקב\u0004 בסוף העמוד הקודם, שטריפה מתעברת ויולדת, וכן שתרנגולת טריפה מתעברת ומטילה ביצים, \u0003ומתני לה\u0004 \u0005[והיה שונה]\u0006 את מה שאמר \u0003אמימר כדאמרן\u0004 \u0005[כמו שאמרנו],\u0006 שהביצים שהיו במעיה של התרנגולת כשנעשתה טריפה (\"שיחלא קמא\") — אסורות, ואלו שנוצרו לאחר מכן — מותרות.","ואילו \u0003רבינא לא סבר לה\u0004 \u0003כ\u0004דברי \u0003רב אחא בר יעקב,\u0004 אלא לשיטתו טריפה ודאית אינה יכולה להתעבר וללדת, או אם היה זה עוף — אינה יכולה להטיל ביצים, \u0003ו\u0004לכן מתני לה \u0005[היה שונה את שמועתו]\u0006 של \u0003אמימר בהאי לישנא\u0004 \u0005[בלשון זו],\u0006 \u0003אמר אמימר: הני ביעי\u0004 \u0005[אותן ביצים]\u0006 של תרנגולת שהיא \u0003ספק טרפה\u0004 (ולא טריפה ודאית), \u0003דשיחלא קמא משהינן להו\u0004 \u0005[\u0006אלו \u0005של הקבוצה הראשונה,\u0006 שהיו במעיה כשנעשתה טריפה, \u0005משהים אנו אותן],\u0006 \u0003אי הדרה וטענה\u0004 \u0005[אם היא חוזרת וטוענת\u0006 ביצים אחרות\u0005]\u0006 — \u0003שריין\u0004 \u0005[מותרות]\u0006 גם הראשונות, מפני שהוכח שאינה טריפה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003אסירן\u0004 \u0005[אסורות]\u0006 הראשונות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אשי לאמימר\u0004 ממה ששנינו: \u0003ומודים בביצת טרפה ש\u0004היא \u0003אסורה, מפני שגדלה באיסור.\u0004 הרי שייתכן שתטען ביצים לאחר שנטרפה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003התם בדשיחלא קמא\u0004 \u0005[שם מדובר בקבוצת הביצים הראשונה],\u0006 שכבר היו במעיה. הקשה לו רב אשי: \u0003אם כן\u0004 מהי הלשון \"ש \u0003גדלה\u0004 באיסור\", שמשמעה שכל גדילתה היתה באיסור? והרי \u0003\"גמרה\u0004 באיסור\" \u0003מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ענה לו, \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003גמרה.\u0004","הקשה לו: \u0003אלא\u0004 לפי זה, שאתה מניח שטריפה אינה טוענת ביצים, ואם היתה בהמה — אינה מתעברת, \u0003הא דתנן\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003ולד טרפה, ר' אליעזר אומר: לא יקרב לגבי\u0004 (על) \u0003מזבח, ר' יהושע אומר: יקרב, במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 — בהכרח \u0003כשעיברה\u0004 (כשנתעברה) תחילה \u0003ולבסוף נטרפה,\u0004 ובשאלה האם העובר כירך אמו, \u0003ש\u0004\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003עובר ירך אמו הוא\u0004 נחשב, ונעשה טריפה כמוה, \u0003ור' יהושע סבר\u0004 \u0005[סבור]:\u0006 \u0003עובר לאו\u0004 \u0005[לא]\u0006 \u0003ירך אמו הוא.\u0004 ואולם: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם בזה המחלוקת, \u0003אדמיפלגי\u0004 \u0005[עד שהם חלוקים]\u0006 בענין איסור הקרבה \u0003לגבוה, ליפלגו\u0004 \u0005[שיחלקו]\u0006 באיסור אכילה \u0003להדיוט!\u0004","ומשיבים: באמת נחלקו גם להדיוט, אלא נשנתה מחלוקת זו בקרבן — \u0003להודיעך כחו\u0004 של \u0003ר' יהושע,\u0004 שגם לגבוה אינו אוסר. ומקשים: \u0003וליפלגו\u0004 \u0005[ושיחלקו]\u0006 \u0003בהדיוט, להודיעך כחו\u0004 של \u0003ר' אליעזר\u0004 האוסר גם להדיוט מטעם זה! ומשיבים: \u0003כח דהיתירא עדיף ליה\u0004 \u0005[כח ההיתר עדיף לו],\u0006 להשמיע לנו עד היכן מגיע צד ההיתר.","ומסכמים: ולדרך זו, מה שנאמר: \u0003ומודים ודאי בביצת טריפה ש\u0004היא \u0003אסורה\u0004 — הוא \u0003בדשיחלא קמא\u0004 \u0005[ב\u0006ביצים \u0005של הקבוצה הראשונה],\u0006 שהיו חבמעיה כשנטרפה. שגם ר' יהושע, הסבור שעובר של בהמה טריפה אינו נחשב ירך אמו — מודה בביצת תרנגולת שהיא טריפה כמותה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 לדעתו, הביצה \u0003גופה\u0004 ממש של התרנגולת \u0003היא.\u0004","ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 פסוקה היא בספק טריפה: \u0003בזכר\u0004 — \u0003כל שנים עשר חדש\u0004 הוא אסור, ואם חי לאחר מכן — יצא מכלל ספק טריפה. \u0003בנקבה\u0004 — \u0003כל שאינה יולדת\u0004 לא יצאה מכלל ספק טריפה.","\u0003אמר רב הונא: כל בריה שאין בו עצם\u0004 — \u0003אינו מתקיים שנים עשר חדש. אמר רב פפא, שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דברי \u0003רב הונא,\u0004 לענין \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר שמואל: קישות שהתליע באיביה,\u0004 כלומר, בעוד שהיא צומחת על גבי הקרקע — \u0003אסורה\u0004 התולעת באכילה, משום \"שרץ השורץ על הארץ\" (ויקרא יא, מא),"],["כי \u0003הני תמרי דכדא\u0004 \u0005[אותם תמרים המונחות בכד],\u0006 \u0003לבתר תריסר ירחי שתא\u0004 \u0005[לאחר שנים עשר חודשי שנה\u0006 ששהו שם\u0005]\u0006 \u0003שריין\u0004 \u0005[מותרות],\u0006 שהואיל ואין לתולעים עצם — אינן מתקיימות שנים עשר חודש, ובוודאי התליעו לאחר שכבר נתלשו מן הקרקע, ותולעים שנוצרו בפרי לאחר שנתלש מן הקרקע אינן אסורות","\u0003.\u0004 \u0003אמר רב: לית בקא בר יומא\u0004 \u0005[אין יתוש בן יום],\u0006 שאינו חי יותר מכך. \u0003ולית דידבא בת שתא\u0004 \u0005[ואין זבוב בן שנה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: והא אמרי אינשי\u0004 \u0005[והרי אומרים אנשים],\u0006 כפתגם עממי: \u0003שב שני אימרא בקתא מבקא\u0004 \u0005[שבע שנים מרדה היתושה ביתוש],\u0006 ומדוע? \u0003דאמרה ליה\u0004 \u0005[שאמרה לו]:\u0006 \u0003חזיתיה לבר\u0004 \u0005[ראיתי\u0006 את \u0005בן\u0006 העיר] \u0003מחוזא דסחא במיא\u0004 \u0005[ששחה במים],\u0006 \u0003וסליק ואיכרך\u0004 \u0005[ועלה והתעטף]\u0006 \u0003בסדינין, ואותיבת עליה ומצת מיניה\u0004 \u0005[וישבת עליו ומצצת\u0006 דם \u0005ממנו],\u0006 \u0003ולא הודעת לי\u0004 \u0005[ולא הודעת לי],\u0006 הרי שיצורים שאין בהם עצם מתקיימים לפחות שבע שנים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003הא דאמרי אינשי\u0004 \u0005[מה שאומרים אנשים]\u0006 כפתגם עממי: \u0003שיתין מני פרזלא תלו ליה לבקא בקורנסיה\u0004 \u0005[\u0006משקל \u0005ששים מטבעות מנה,\u0006 מאה דינרים, \u0005ברזל תלויים לו ליתוש בקורנסו],\u0006 כלומר, באבר שהוא עוקץ בו, לומר שעקיצתו קשה, \u0003מי איכא\u0004 \u0005[האם ישנו,\u0006 שייך דבר כזה\u0005]?\u0006 והרי \u0003איהו גופיה כמה הוי\u0004 \u0005[הוא עצמו כמה הוא]\u0006 שוקל? \u0003אלא\u0004 צריכים לומר ש\u0003במני דידהו\u0004 \u0005[במנים שלהם]\u0006 של היתושים מדובר, \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 כשהוזכרו שבע שנים — \u0003בשני דידהו\u0004 \u0005[בשנים שלהם]\u0006 מדובר, וממילא אין להקשות מכך.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת בכורות: \u0003בהמה בעלת חמש רגלים, או שאין לה אלא שלש\u0004 — \u0003הרי זה מום\u0004 בבהמה, שאינה ראויה להקרבה. \u0003אמר רב הונא: לא שנו\u0004 דבר זה \u0003אלא שחסר ויתר ביד,\u0004 שחסרה אחת מרגליה הקדמיות, או שיש לה רגל קדמית יתרה. \u0003אבל חסר ויתר ברגל,\u0004 ברגלים האחוריות — \u0003טרפה נמי הויא\u0004 \u0005[הוא גם כן].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כל\u0004 שהוא \u0003יתר,\u0004 הרי \u0003כנטול דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ולכן בהמה זו שיש לה רגל יתירה, רואים אותה כאילו נשמטה ירכה, שהיא טריפה. אבל כיון שאם נשמטה אחת מרגליה הקדמיות — כשרה היא, הוא הדין אם היתה לה רגל קדמית יתירה או חסרה.","מסופר, \u0003ההיא חיותא דהוה לה תרתי סניא דיבי\u0004 \u0005[בהמה אחת היו לה שני מעי עיור],\u0006 \u0003אייתוה\u0004 \u0005[הביאו אותה]\u0006 \u0003לרבינא, וטרפה\u0004 \u0005[והטריפה]\u0006 \u0003מ\u0004תוך דברי \u0003רב הונא,\u0004 שכל היתר כנטול נחשב, וכאילו ניטל חלק מן המעיים, שדבר זה עושה טריפה. ומוסיפים: \u0003ואי שפכן להדדי\u0004 \u0005[ואם הם שופכים זה לזה],\u0006 כלומר, המזון עובר מזה לזה — הריהי \u0003כשרה,\u0004 שאבר אחד הוא.","מסופר, \u0003ההיא גובתא דהוה נפקא מבי כסי להובלילא\u0004 \u0005[\u0006מעשה ב\u0005שפופרת\u0006 של בשר, כעין מעי, \u0005שהיתה יוצאת מבית הכוסות להמסס],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב אשי למיטרפה\u0004 \u0005[להטריף אותה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא מר בר חייא לרב אשי: כל הני חיוי ברייתא הכי אית להו\u0004 \u0005[כל בהמות הבר כך יש להן],\u0006 כך היא ברייתן, ואין כאן חשש.","בהמשך לכך מסופר, \u0003ההוא גובתא דהוה מעברא מבי כסי לכרסא\u0004 \u0005[\u0006מעשה ב\u0005שפופרת שהיתה עוברת מבית הכוסות לכרס],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003מר בר רב אשי לאכשורה\u0004 \u0005[להכשיר אותה]\u0006 כמו במקרה הקודם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אושעיא: אטו כולהו בחדא מחיתא מחתינהו\u0004 \u0005[וכי את כולם באריגה אחת ארגו]?\u0006 \u0003היכא דאתמר אתמר\u0004 \u0005[במקום שנאמר\u0006 שכך דרכן של בהמות \u0005נאמר],\u0006 \u0003היכא דלא אתמר\u0004 \u0005[במקום שלא נאמר]\u0006 \u0003לא אתמר\u0004 \u0005[לא נאמר],\u0006 והריהי איפוא טריפה.","ובענין דומה מסופר, \u0003העיד נתן בר שילא רב טבחיא\u0004 \u0005[ראש הטבחים]\u0006 של \u0003ציפורי לפני רבי על שני בני מעים היוצאין מן הבהמה,\u0004 מן הקיבה שלה, \u0003כאחד\u0004 — \u0003שהיא טרפה,\u0004 \u0003וכנגדן בעוף\u0004 בכגון זה — \u0003כשרה,\u0004 שדבר זה מצוי בעוף. \u0003במה דברים אמורים\u0004 שטריפה בבהמה? \u0003שיוצאין בשני מקומות, אבל\u0004 אם \u0003יוצאין במקום אחד,\u0004 בסמוך זה לזה, \u0003וכלין\u0004 (ומסתיימים), כלומר, חוזרים ומתחברים למעי אחד \u0003עד כ\u0004שיעור \u0003אצבע\u0004 ממקום שיצאו — \u0003כשרה.\u0004","ומעירים: \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אמי ורב אסי\u0004 מתי היא כשרה כשיצאו ממקום אחד, \u0003חד\u0004 \u0005[אחד מהם]\u0006 \u0003אמר:\u0004 ו\u0003הוא דהדרי וערבי\u0004 \u0005[ש\u0006הם \u0005חוזרים ומתערבים],\u0006 כלומר, שהם הופכים להיות מעי אחד, \u0003וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003אמר: אף על גב דלא הדרי וערבי\u0004 \u0005[אף על פי שאינם חוזרים ומתערבים].\u0006","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח לדעת מי שאומר]:\u0006 \u0003הוא דהדרי וערבי\u0004 \u0005[שהם חוזרים ומתערבים],\u0006 והופכים למעי אחד — \u0003היינו דקתני\u0004 \u0005[זה שהוא שונה]\u0006 \u0003עד כאצבע,\u0004 שמיד לאחר שהם מתפצלים הריהם חוזרים ומתחברים בתוך כאצבע, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אף על גב דלא הדרי וערבי\u0004 \u0005[אף על פי שאינם חוזרים ומתערבים],\u0006 \u0003מאי\u0004 \u0005[מהי]\u0006 לשון \"וכלין \u0003עד כאצבע\"?\u0004 ומשיבים: \u0003עד כאצבע מלמטה,\u0004 שאם הם חוזרים ומתחברים עד מרחק של כאצבע מנקב הרעי — הרי זו כשרה.","שנינו במשנה, ש\u0003ר' יהודה אומר: אם ניטלה הנוצה\u0004 (הפלומה הצמודה לעור) של העוף — \u0003פסולה,\u0004 כלומר, טריפה, כמו בהמה שניטל עורה (גלודה). \u0003אמר ר' יוחנן: ר' יהודה ור' ישמעאל אמרו דבר אחד, ר' יהודה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שהוא רואה את הנוצה כחלק מן העור, שאם ניטל מן העוף הרי זו טריפה. \u0003ר' ישמעאל\u0004 — \u0003דתנן\u0004 \u0005[ששנינו]\u0006 בברייתא, לעניין מחשבת פיגול בחטאת העוף, \u0003ר' ישמעאל אומר: הנוצה מצטרפת,\u0004 שאם הכהן מלק את העוף על מנת לאכול כזית מן הבשר ומן הנוצה למחר — הרי זה פיגול. הרי שגם ר' יהודה וגם ר' ישמעאל מחשיבים את הנוצה כעורו של העוף.","\u0003אמר רבא: דילמא לא היא\u0004 \u0005[שמא אינו כן]!\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהודה הכא\u0004 \u0005[כאן]\u0006 שדינה של הנוצה כעור, \u0003אלא לענין טרפה,\u0004 מפני \u0003דליכא מידי דמגין עליה\u0004 \u0005[ש\u0006כשהיא ניטלת — \u0005אין דבר שמגין עליו]\u0006 על העוף, \u0003אבל לענין איפגולי\u0004 \u0005[להתפגל]\u0006 — \u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים הוא סבור],\u0006 שאין הנוצה נחשבת כעור, מפני שאינה ראויה לאכילה, ורק מחשבת פיגול בדבר שדרכו לאכול מפגלת \u0003ו\u0004להיפך, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' ישמעאל התם\u0004 \u0005[שם]\u0006 \u0003אלא לענין איפגולי\u0004 \u0005[להתפגל],\u0006 מפני שהנוצה נחשבת כחלק מן העור, והעור עצמו נאכל, \u0003אבל לענין טרפה\u0004 — \u0003אגוני לא מגין\u0004 \u0005[להגן אין\u0006 הנוצה \u0005מגינה]\u0006 על העוף, להחשיבו טריפה אם ניטלה.","בהמה שהיא \u0003אחוזת הדם\u0004 כלומר, שיש לה עודף דם, \u0003והמעושנת\u0004 שהזיק לה העשן, \u0003והמצוננת\u0004 שנתקררה וחלתה, \u0003ושאכלה הרדופני,\u0004 שיח רעיל לבעלי חיים, \u0003ושאכלה צואת תרנגולים, או ששתת מים הרעים\u0004 — בכל אלה \u0003כשרה,\u0004 למרות שחייה בסכנה. אבל אם \u0003אכלה סם המות, או שהכישה נחש\u0004 — \u0003מותרת משום טרפה,\u0004 אבל \u0003אסורה משום סכנת נפשות\u0004 לאוכל אותה, בגלל הרעל שנספג בגופה.","\u0003אמר שמואל:\u0004 אם \u0003הלעיטה\u0004 את בהמתו \u0003חלתית\u0004 שהיא עשב חריף מאד — הרי היא \u0003טרפה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דמינקבה להו למעיינה\u0004 \u0005[\u0006משום \u0005שהיא מנקבת את בני המעיים].\u0006","\u0003מתיב\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שיזבי\u0004 ממה ששנינו בברייתא: \u0003אחוזת הדם, והמעושנת, ושאכלה הרדופני, ושאכלה צואת תרנגולים, ושתת מים הרעים,\u0004 או \u0003הלעיטה תיעה\u0004 (שיבואר עניינה להלן), \u0003חלתית ופלפלין,\u0004 או \u0003אכלה סם המות\u0004 — הרי זו \u0003כשרה. הכישה נחש, או שנשכה כלב שוטה\u0004 — \u0003מותרת משום טרפה, ואסורה משום סכנת נפשות.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003חלתית\u0004 ששנינו שהיא כשרה, על מה שאמר שמואל שאם אכלה \u0003חלתית\u0004 הריהי טריפה, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 ממה ששנינו בברייתא זו שאם אכלה \u0003סם המות\u0004 הריהי כשרה, על מה ששנינו במשנה שאם אכלה \u0003סם המות\u0004 הריהי אסורה משום סכנה!","ומתרצים: מ\u0003חלתית\u0004 על \u0003חלתית לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003כאן\u0004 שאם אכלה חילתית היא כשרה — \u0003ב\u0004אוכלת \u0003עלין\u0004 של חילתית, שאינם מזיקים כל כך, \u0003כאן\u0004 שהיא טריפה — \u0003ב\u0004אוכלת \u0003קרטין\u0004 (חתיכות קטנות) של חילתית, שיש בהן חריפות יתירה. וכן מ\u0003סם המות\u0004 על ענין \u0003סם המות\u0004 גם כן \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא דידה\u0004 \u0005[זה\u0006 שהיא מותרת הרי זה בסם המוות \u0005שלה]\u0006 — שאכלה סם מוות שהורג רק בהמות, ואין בו סכנה לאדם. \u0003הא\u0004 \u0005[זה]\u0006 שהיא אסורה — בשאכלה סם שהורג \u0003אדם.\u0004 ושואלים על הברייתא: \u0003סם המות\u0004 של \u0003בהמה היינו\u0004 \u0005[הרי זה]\u0006 \u0003הרדופני,\u0004 ומדוע הוצרך להזכיר את שניהם? ומשיבים: \u0003תרי גווני\u0004 \u0005[שני סוגים]\u0006 של \u0003סם המות\u0004 שונה התנא, הרדופני וסם אחר.","אגב הבאת ברייתא זו שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003תיעה? אמר רב יהודה:\u0004"],["\u0003עיקרא דמרירתא\u0004 \u0005[השורש של ירק מר].\u0006","\u0003אמר רב יהודה: האי מאן דאכל תלתא תקלי חלתית אליבא ריקנא\u0004 \u0005[מי שאוכל\u0006 משקל \u0005שלושה שקלים חילתית על לב ריק,\u0006 קיבה ריקה\u0005]\u0006 \u0003—\u0004 \u0003מישתלח משכיה\u0004 \u0005[נפשט עורו]\u0006 מחמת החום שאוחז בו. \u0003אמר ר' אבהו: בדידי הוה עובדא\u0004 \u0005[בי\u0006 עצמי \u0005היה מעשה],\u0006 \u0003ואכלי חד תקלא חלתיתא\u0004 \u0005[ואכלתי\u0006 משקל \u0005שקל אחד חילתית],\u0006 \u0003ואי לא דיתבי במיא\u0004 \u0005[ואם לא שישבתי\u0006 מיד \u0005במים]\u0006 להצטנן — \u0003מישתלח משכאי\u0004 \u0005[היה עורי נפשט],\u0006 \u0003וקיימתי בעצמי\u0004 על ידי כך: \u0003\"החכמה תחיה בעליה\"\u0004 (קהלת ז, יב) שבזכות החכמה שלמדתי ניצלו חיי.","\u0003אמר רב יוסף: האי מאן דאכיל שיתסרי ביעי\u0004 \u0005[מי שאוכל שש עשרה ביצים],\u0006 \u0003וארבעי אמגוזי\u0004 \u0005[וארבעים אגוזים],\u0006 \u0003ושב בוטיתא דפרחי\u0004 \u0005[ושבע אביונות\u0006 פירות \u0005של הצלף],\u0006 \u0003ושתי רביעתא דדובשא\u0004 \u0005[ושותה רביעית דבש]\u0006 \u0003בתקופת תמוז, אליבא ריקנא\u0004 \u0005[על לב ריק,\u0006 קיבה ריקה\u0005]\u0006 — \u0003מתעקר תליא דליביה\u0004 \u0005[נעקר חיבור ליבו].\u0006","ובענין הכשת נחש ששנינו במשנתנו מסופר, \u0003ההוא בר טביא דאתא לבי ריש גלותא\u0004 \u0005[צבי אחד שהובא\u0006 לאחר שנשחט \u0005לבית ראש הגולה],\u0006 \u0003דהוה מפסק כרען בתרייתא\u0004 \u0005[שהיו חתוכות רגליו האחוריות],\u0006 \u0003בדקיה\u0004 \u0005[בדק אותו]\u0006 \u0003רב בצומת הגידין\u0004 שבתחתית השוק, וראה שלא נפגם, \u0003ואכשריה\u0004 \u0005[והכשיר אותו].\u0006 \u0003סבר למיכל מיניה באומצא\u0004 \u0005[סבור היה לאכול ממנו בצליה קלה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל:\u0004 וכי \u0003לא חייש מר לניקורי\u0004 \u0005[אין אדוני חושש שמא נשך אותו נחש]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב לשמואל: \u0003מאי תקנתא\u0004 \u0005[מה התקנה]\u0006 לברר את הדבר? אמר לו: \u0003נותביה בתנורא דאיהו בדיק נפשיה\u0004 \u0005[נשים אותו בתנור חם, והוא יבדוק את עצמו].\u0006 \u0003אותביה, נפל תילחי תילחי\u0004 \u0005[שם אותו\u0006 בתנור על שיפוד, \u0005ונפלו\u0006 ממנו \u0005חתיכות חתיכות],\u0006 שהוא סימן שהכישו נחש. \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003שמואל עליה\u0004 \u0005[על]\u0006 \u0003רב\u0004 את הכתוב: \u0003\"לא יאונה לצדיק כל און\"\u0004 (משלי יב, כא), שניצל בזכות צדקותו. \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב עליה\u0004 \u0005[על]\u0006 \u0003שמואל\u0004 את הכתוב: \u0003\"וכל רז לא אנס לך\"\u0004 (דניאל ד, ו), לא נסתר ממך, הכל אתה יודע, אפילו עניינים אלה.","\u0003סימני בהמה וחיה\u0004 הטהורים \u0003נאמרו מן התורה, וסימני העוף לא נאמרו\u0004 במפורש, \u0003אבל אמרו חכמים\u0004 בהם סימנים: \u0003כל עוף הדורס\u0004 שנועץ ציפורניו בטרפו ואוכל — \u0003טמא. כל שיש לו אצבע יתירה\u0004 מאחור, \u0003וזפק,\u0004 מעין כיס בצד הוושט שבו שוהה המזון קודם העיכול, \u0003וקורקבנו נקלף,\u0004 שעורו הפנימי הצהבהב של הקורקבן נקלף ממנו — \u0003טהור. ר' אלעזר בר' צדוק אומר: כל עוף החולק את רגליו,\u0004 שכאשר הוא עומד על חוט, שתים מאצבעותיו מצויות מלפנים ושתים מאחור — הרי הוא \u0003טמא.\u0004","\u0003ובחגבים,\u0004 שגם בהם לא ניתנו סימני טהרה מפורשים בתורה — גם בהם נתנו חכמים סימנים: \u0003כל שיש לו ארבע רגלים, וארבע כנפים,\u0004 שתים גדולות לעוף בהן, ושתים המכסות אותן בשעת המנוחה, \u0003וקרצולים,\u0004 כלומר, רגלי ניתור גבוהות, \u0003וכנפיו חופין את רובו. ר' יוסי אומר,\u0004 צריך להוסיף לכל אלה תנאי נוסף: \u0003ושמו חגב. ובדגים,\u0004 סימן טהרתם כתוב בתורה: \u0003כל שיש לו\u0004 על גופו \u0003סנפיר וקשקשת\u0004 (ויקרא יא, ט). \u0003ר' יהודה אומר:\u0004 צריכים שיהיו לו לפחות \u0003שני קשקשין וסנפיר אחד. ואלו הן קשקשין\u0004 — אותם \u0003הקבועין בו, וסנפירים\u0004 — \u0003הפורח בהן,\u0004 אלה שהוא שט בהם.","על מה ששנינו במשנה שסימני בהמה טהורה נאמרו מן התורה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אלו הן סימני בהמה\u0004 — ככתוב: \u0003\"כל בהמה מפרסת פרסה\u0004 ושוסעת שסע פרסות מעלת גרה\" (ראה ויקרא יא, ג). ומוסיפים: \u0003כל בהמה שמעלת גרה\u0004 — \u0003בידוע שאין לה שינים\u0004 חותכות \u0003למעלה\u0004 בקדמת הפה, \u0003וטהורה.\u0004","ותוהים: \u0003וכללא\u0004 \u0005[וכי כלל]\u0006 \u0003הוא\u0004 זה? \u0003והרי גמל\u0004 ש\u0003מעלה גרה הוא, ואין לו שינים למעלה, ו\u0004בכל זאת הריהו \u0003טמא\u0004 (שם ד)! ומשיבים: \u0003גמל ניבי אית ליה\u0004 \u0005[\u0006שני \u0005ניבים יש לו]\u0006 מלמעלה, שן מכאן ושן מכאן.","ושואלים: ועדיין כלל הוא? \u0003והרי בן גמל,\u0004 גמל צעיר, \u0003דניבי נמי לית ליה\u0004 \u0005[שניבים גם כן אין לו],\u0006 והוא טמא! \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הרי שפן וארנבת\u0004 ש\u0003מעלת גרה הן ויש להן שינים למעלה, ו\u0004בכל זאת הם \u0003טמאין\u0004 (שם ה—ו)! \u0003ועוד\u0004 יש לשאול, \u0003שינים מי כתיבי באורייתא\u0004 \u0005[האם הן כתובות בתורה]\u0006 כסימן טומאה? ומסיקים: \u0003אלא הכי קאמר\u0004 \u0005[כך אומר]\u0006 התנא, כך צריך להבין את הדברים: \u0003כל בהמה שאין לה שינים למעלה\u0004 — \u0003בידוע שהיא מעלת גרה ומפרסת פרסה, וטהורה.\u0004","\u0003ו\u0004שואלים: לשם מה לו לבדוק בשינים? \u0003ליבדוק בפרסותיה\u0004 \u0005[שיבדוק את פרסותיה]!\u0006 ומשיבים: \u0003כגון שהיו פרסותיה חתוכות,\u0004 ואינו יכול לבדוק דבר זה. \u0003וכ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: היה מהלך במדבר ומצא בהמה שפרסותיה חתוכות\u0004 — \u0003בודק בפיה, אם אין לה שינים למעלה\u0004 — \u0003בידוע שהיא טהורה, אם לאו\u0004 \u0005[לא]\u0006 — \u0003בידוע שהיא טמאה, ובלבד שיכיר גמל,\u0004 כלומר, שידע שאין זה גמל. ותוהים: מדוע צריך לדעת בבירור שאין זה גמל? והרי \u0003גמל ניבי אית ליה\u0004 \u0005[ניבים יש לו]!\u0006 \u0003אלא\u0004 צריך לומר: \u0003ובלבד שיכיר\u0004 שידע שאינו \u0003בן גמל,\u0004 שהרי לבן גמל אין ניבים. ומקשים על דברי רב חסדא: וכיצד ניתן לסמוך על כך להתיר בהמה כזו?","\u0003לאו אמרת איכא\u0004 \u0005[האם לא אמרת שיש]\u0006 \u0003בן גמל\u0004 שאין לו ניבים ובכל זאת הוא טמא? שמא \u0003איכא נמי מינא אחרינא דדמי\u0004 \u0005[\u0006שמא \u0005יש גם כן מין אחר\u0006 טמא, שאינו מפריס פרסה, \u0005שדומה]\u0006 \u0003לבן גמל,\u0004 שהוא מעלה גרה ואין לו שינים! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך\u0006 לומר כן\u0005],\u0006 \u0003דתני דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית מדרשו]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"ואת הגמל כי מעלה גרה הוא\"\u0004 (שם ד), הקדוש ברוך הוא, שהוא \u0003שליט בעולמו, יודע שאין לך דבר\u0004 שהוא \u0003מעלה גרה וטמא אלא גמל, לפיכך פרט בו הכתוב\u0004 \"מעלה גרה \u0003הוא\"\u0004 — הוא ולא אחר.","\u0003ואמר רב חסדא: היה מהלך בדרך ומצא בהמה שפיה גמום\u0004 (חתוך) ואינו יכול לדעת על פי שיניה — \u0003בודק בפרסותיה, אם פרסותיה סדוקות,\u0004 שיש בהן שסע באמצען — \u0003בידוע שהיא טהורה, אם לאו\u0004 \u0005[לא]\u0006 — \u0003בידוע שהיא טמאה, ובלבד שיכיר\u0004 וידע שאין זה \u0003חזיר,\u0004 שחזיר הוא שוסע שסע, וטמא. ושוב שואלים: וכיצד יועיל הדבר שידע שאין זה חזיר?","\u0003לאו אמרת איכא\u0004 \u0005[\u0006האם \u0005לא אמרת שיש]\u0006 \u0003חזיר\u0004 שהוא שוסע שסע וטמא? שמא \u0003איכא נמי מינא אחרינא דדמיא\u0004 \u0005[\u0006שמא \u0005יש גם כן מין אחר שדומה]\u0006 \u0003לחזיר\u0004 שהוא מפריס פרסה ואינו שוסע שסע! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית מדרשו]\u0006 של \u0003ר' ישמעאל: \"ואת החזיר כי מפריס פרסה הוא\"\u0004 (שם ז) — \u0003שליט בעולמו יודע שאין לך דבר שמפריס פרסה וטמא אלא חזיר, לפיכך פרט בו הכתוב\u0004 \"כי מפריס פרסה \u0003הוא\".\u0004","\u0003ואמר רב חסדא: היה מהלך במדבר, ומצא בהמה ש\u0004גם \u0003פיה גמום ו\u0004גם \u0003פרסותיה חתוכות\u0004 — \u0003בודק בבשרה, אם מהלך\u0004 (נמשך) הבשר \u0003שתי וערב,\u0004 שחלק ממנו נמשך מלמעלה למטה וחלק ממנו לרוחב — \u0003בידוע שהיא טהורה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003בידוע שהיא טמאה, ובלבד שיכיר\u0004 וידע שאין זה \u0003ערוד,\u0004 שגם בשרו של ערוד נמשך שתי וערב, והוא טמא.","ומקשים: וכיצד יועיל סימן זה? \u0003לאו אמרת איכא\u0004 \u0005[האם אין אתה אומר שיש]\u0006 \u0003ערוד\u0004 שבשרו שתי וערב, והוא טמא? שמא \u0003איכא נמי מינא אחרינא דדמיא\u0004 \u0005[יש גם כן מין אחר שדומה]\u0006 \u0003לערוד\u0004 בענין זה! ומשיב: \u0003גמירי דליכא\u0004 \u0005[למודים אנו\u0006 במסורת \u0005שאין מין אחר].\u0006 ושואלים: \u0003והיכא\u0004 \u0005[והיכן]\u0006 \u0003בודק\u0004 את הבשר? \u0003אמר אביי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב חסדא: בכנפי העוקץ,\u0004 בחלק העליון של הירך, מתחת לעצם האליה, שבקצה השדרה.","שנינו במשנה: \u0003סימני חיה\u0004 נאמרו מן התורה. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלו הן סימני חיה.\u0004 ותחלה תוהים: \u0003מדוע יש צורך בסימנים מיוחדים לחיה?\u0004 והרי \u0003חיה בכלל בהמה היא לסימנין,\u0004 שנאמר: \"זאת החיה אשר תאכלו מכל הבהמה... כל מפרסת פרסה\" וכו' (ויקרא יא, ב—ג)! \u0003אמר ר' זירא:\u0004"],["\u0003להתיר חלבה,\u0004 שכן בניגוד לבהמה טהורה, חלב חיה טהורה מותר באכילה. \u0003והכי קאמר\u0004 \u0005[וכך אומר\u0006 התנא\u0005]:\u0006 \u0003אלו הן סימני חיה\u0004 טהורה \u0003שחלבה מותר\u0004 — \u0003כל שיש לה קרנים, וטלפים,\u0004 שהן שתי צפורניים עבות ורחבות של מפריסי הפרסה.","\u0003ר' דוסא אומר:\u0004 אם \u0003יש לה קרנים\u0004 — בוודאי חיה טהורה היא, ו\u0003אי\u0004 (אין) \u0003אתה צריך לחזור על טלפים,\u0004 אבל אם \u0003יש לה טלפים\u0004 — אין זה סימן מובהק, ועדיין \u0003צריך אתה לחזור על קרנים. ו\u0004חיה הקרויה \u0003קרש, אף על פי שאין לו אלא קרן אחת\u0004 — חלבה \u0003מותר.\u0004","ותוהים: וכי \u0003כללא\u0004 \u0005[כלל]\u0006 קבוע \u0003הוא\u0004 זה, שכל שיש לו קרניים וטלפיים הוא חיה, שחלבה מותר? \u0003והרי עז יש לו קרנים וטלפים, וחלבו אסור,\u0004 שהוא מין בהמה טהורה! ומשיבים: קרניים \u0003כרוכות בעינן\u0004 \u0005[צריכים אנו],\u0006 שיהיו עשויות שכבות זו על גבי זו, כדי להתיר את חלבה. ומקשים: \u0003והרי שור,\u0004 שקרניו \u0003כרוכות, וחלבו אסור,\u0004 שהוא מין בהמה טהורה! ומשיבים: קרניים \u0003חרוקות בעינן\u0004 \u0005[צריכים אנו],\u0006 שיהיו בהם חריצים, ואינן חלקות כקרני השור.","ומקשים: \u0003והרי עז,\u0004 קרניו \u0003חרוקות, וחלבו אסור,\u0004 שאף הוא מין בהמה טהורה! ומשיבים: \u0003מפוצלות בעינן\u0004 \u0005[צריכים אנו],\u0006 שהקרניים מתפצלות כענפים לכאן ולכאן כדי להתיר את חלבה. ומקשים: \u0003והרי צבי,\u0004 ש\u0003אין\u0004 קרניו \u0003מפוצלות, וחלבו מותר!\u0004 ומשיבים: \u0003חדורות בעינן\u0004 \u0005[צריכים אנו],\u0006 שיהיו הקרנים מעוגלות, ולא רחבות כשל כבש.","ומסכמים: \u0003הלכך\u0004 \u0005[על כן],\u0006 \u0003היכא דמיפצלא\u0004 \u0005[במקום ש\u0006הקרניים \u0005מפוצלות]\u0006 — \u0003לא דינא ולא דיינא\u0004 \u0005[אין דין ואין דיין],\u0006 כלומר, אין מקום לדון בזה, שוודאי חיה היא, וחלבה מותר. \u0003היכא דלא מיפצלא\u0004 \u0005[במקום שאינן מפוצלות]\u0006 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003כרוכות\u0004 (שכבות שכבות) \u0003חדורות\u0004 (מעוגלות) \u0003וחרוקות\u0004 (מחורצות), כדי להתיר את חלבה. \u0003ו\u0004חרוקות שהזכרנו \u0003הוא\u0004 באופן \u0003דמיבלע חירקייהו\u0004 \u0005[שהחריצים שבהם מובלעים זה בתוך זה].\u0006","\u0003ו\u0004מקרה כעין זה \u0003היינו ספיקא\u0004 \u0005[וזהו הספק]\u0006 שהתעורר בבעל חיים שקוראים לו \u0003עיזא כרכוז,\u0004 האם יש לה דין חיה וחלבה מותר. שמסופר, \u0003ההיא\u0004 \u0005[אותה]\u0006 \u0003עיזא כרכוז דהואי בי ריש גלותא\u0004 \u0005[שהיתה בבית ראש הגולה],\u0006 \u0003דעקור מלא צנא דתרבא מינה\u0004 \u0005[שעקרו מלא הסל חלב ממנה],\u0006 \u0003רב אחאי אסר\u0004 את החלב, משום שהיה סבור שהוא מין בהמה, \u0003רב שמואל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו אכל מיניה\u0004 \u0005[ממנו],\u0006 \u0003קרי אנפשיה\u0004 \u0005[וקרא על עצמו]\u0006 פסוק זה: \u0003\"מפרי פי איש תשבע בטנו\"\u0004 (משלי יח, כ), שבזכות מה שלמד שהיא מותרת יכול היה לאכול ממנה.","\u0003שלחו מתם\u0004 \u0005[משם]\u0006 מארץ ישראל: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב\u0004 \u0003שמואל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו,\u0004 שעז זו מין חיה היא, וחלבה מותר. \u0003ו\u0004אולם, עם זאת, \u0003הזהרו ב\u0004כבודו של \u0003רבינו אחאי\u0004 שאסר, ואל תנהגו היתר בפניו, \u0003שמאיר עיני גולה הוא.\u0004","ושבים למה ששנינו בברייתא: \u0003וקרש אף על פי שאין לו אלא קרן אחד מותר. אמר רב יהודה: קרש\u0004 הוא \u0003טביא\u0004 \u0005[צבי]\u0006 החי במקום המכונה \u0003בי עילאי\u0004 \u0005[בית העליונים].\u0006 \u0003טגרס\u0004 שדיברו בו חכמים — הוא \u0003אריא\u0004 \u0005[אריה]\u0006 החי במקום המכונה \u0003בי עילאי\u0004 \u0005[בית העליונים].\u0006 \u0003אמר רב כהנא: תשע אמהתא הוי\u0004 \u0005[תשע אמות יש]\u0006 \u0003בין אונא לאונא דאריא\u0004 \u0005[בין אוזן לאוזן של\u0006 אותו \u0005אריה]\u0006 של \u0003בי עילאי. אמר רב יוסף: שיתסר אמהתא הוי משכיה דטביא\u0004 \u0005[שש עשרה אמות הוא אורכו של אותו צבי]\u0006 של \u0003בי עילאי.\u0004","ובענין אריה של בי עילאי מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר\u0004 רומי \u0003לר' יהושע בן חנניה:\u0004 מה ש\u0003אלהיכם כאריה מתיל\u0004 \u0005[נמשל],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אריה שאג מי לא יירא\"\u0004 (עמוס ג, ח), \u0003מאי רבותיה\u0004 \u0005[מה גדולתו]?\u0006 הלא \u0003פרשא קטיל אריא\u0004 \u0005[פרש הורג אריה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו כהאי אריא מתיל\u0004 \u0005[לא כאריה זה\u0006 שפרש מסוגל להרוג הוא \u0005נמשל],\u0006 אלא \u0003כאריא\u0004 של \u0003בי עילאי מתיל\u0004 \u0005[\u0006הוא \u0005נמשל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר: \u0003בעינא דמיחזית ליה ניהלי\u0004 \u0005[רצוני שתראה אותו לי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003לא מצית חזית ליה\u0004 \u0005[אינך יכול לראות אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איברא, חזינא ליה\u0004 \u0005[באמת, אראה אותו]!\u0006 הראהו לי! \u0003בעא רחמי\u0004 \u0005[ביקש\u0006 ר' יהושע \u0005רחמים,\u0006 התפלל\u0005],\u0006 \u0003אתעקר מדוכתיה\u0004 \u0005[נעקר\u0006 אותו אריה \u0005ממקומו,\u0006 לעבר רומי\u0005],\u0006","\u0003כי הוה מרחיק ארבע מאה פרסי ניהם חד קלא\u0004 \u0005[כאשר היה מרוחק ארבע מאות פרסות\u0006 מרומי \u0005נהם פעם אחת],\u0006 \u0003אפילו כל מעברתא\u0004 \u0005[הפילו כל\u0006 הנשים \u0005המעוברות],\u0006 \u0003ושורא דרומי נפל\u0004 \u0005[וחומת רומי נפלה].\u0006 \u0003אדמרחק תלת מאה פרסי ניהם קלא אחרינא\u0004 \u0005[כאשר היה מרוחק שלוש מאות פרסות נהם בקול אחר],\u0006 \u0003נתור ככי ושיני דגברי\u0004 \u0005[נשרו השיניים הקדמיות והשיניים הטוחנות של האנשים\u0006 מפחד\u0005],\u0006 \u0003ואף הוא\u0004 הקיסר \u0003נפל מכורסייא לארעא\u0004 \u0005[מהכסא לארץ].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' יהושע: \u0003במטותא מינך, בעי רחמי עליה דלהדר לדוכתיה\u0004 \u0005[בבקשה ממך, בקש רחמים עליו שיחזור למקומו].\u0006 \u0003בעא רחמי עליה\u0004 \u0005[ביקש\u0006 ר' יהושע \u0005רחמים עליו],\u0006 \u0003ואהדר ליה לאתריה\u0004 \u0005[והחזירו למקומו].\u0006","ועוד מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לר' יהושע בן חנניה: בעינא דאיחזי לאלהיכו\u0004 \u0005[רוצה אני לראות את אלהיכם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003לא מצית חזית ליה\u0004 \u0005[לא תוכל לראות אותו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איברא\u0004 \u0005[באמת],\u0006"],["\u0003חזינא ליה\u0004 \u0005[אראה אותו],\u0006 הראה לי אותו! \u0003אזל אוקמיה להדי יומא\u0004 \u0005[הלך\u0006 ר' יהושע \u0005העמיד אותו\u0006 את הקיסר \u0005אל מול השמש]\u0006 \u0003בתקופת תמוז,\u0004 כשהשמש יוקדת בעוז, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איסתכל ביה\u0004 \u0005[הבט בו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא מצינא\u0004 \u0005[איני יכול].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יומא, דחד משמשי דקיימי קמי דקודשא בריך הוא אמרת לא מצינא לאיסתכלא ביה\u0004 \u0005[השמש, שהוא אחד מהשמשים שעומדים לפני הקדוש ברוך הוא, אומר אתה איני יכול להסתכל בו],\u0006 \u0003שכינה\u0004 עצמה \u0003לא כל שכן!\u0004","מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לר' יהושע בן חנניה: בעינא דאיצבית ליה נהמא לאלהיכו\u0004 \u0005[רוצה אני לערוך לחם,\u0006 סעודה \u0005לאלוהיכם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003לא מצית\u0004 \u0005[לא תוכל].\u0006 שאל אותו: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 אמר לו: \u0003נפישי חילוותיה\u0004 \u0005[מרובים חילותיו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איברא\u0004 \u0005[באמת],\u0006 אעשה זאת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק צבית לגידא רביתא\u0004 \u0005[לך ערוך\u0006 סעודה \u0005על הים הגדול\u0006 הקרוי \u0005רביתא],\u0006 \u0003דרויחא עלמא\u0004 \u0005[ש\u0006שם \u0005יש מקום מרווח].\u0006 \u0003טרח שיתא ירחי קייטא\u0004 \u0005[טרח\u0006 הקיסר \u0005שישה חודשי הקיץ]\u0006 בדבר, \u0003אתא זיקא כנשיה לימא\u0004 \u0005[באה רוח וטאטאה הכל לים].\u0006","חזר ו\u0003טרח\u0004 בעריכת סעודה אחרת \u0003שיתא ירחי דסיתוא\u0004 \u0005[שישה חודשי החורף],\u0006 \u0003אתא מיטרא טבעיה בימא\u0004 \u0005[בא גשם\u0006 סחף מה שהכין \u0005וטיבע אותו בים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר לר' יהושע: \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 מדוע אירעו דברים אלה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני כנושאי זלוחאי דאתו קמיה\u0004 \u0005[אלה הם המטאטאים ושוטפי הרצפה שבאו לפניו],\u0006 והם אכלו הכל. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003לא מצינא\u0004 \u0005[איני יכול].\u0006","עוד מסופר, \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003בת קיסר לר' יהושע בן חנניה: אלהיכון נגרא\u0004 \u0005[אלוהיכם נגר]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"המקרה במים עליותיו\"\u0004 (תהלים קד, ג), הרי שהוא עושה תקרה, \u0003אימא ליה דנעביד לי חדא מסתוריתא\u0004 \u0005[אמור לי שיעשה לי מסתורית אחת],\u0006 מתקן פשוט להתרת פקעות צמר! \u0003אמר: לחיי\u0004 \u0005[בבקשה]!\u0006 \u0003בעא רחמי עלה ואינגעה\u0004 \u0005[ביקש רחמים,\u0006 התפלל \u0005עליה ונצטרעה],\u0006 \u0003אותבה בשוקא דרומי ויהבי לה מסתוריתא\u0004 \u0005[הושיבו אותה בשוק של רומי ונתנו לה מסתורית],\u0006 \u0003דהוו נהיגי דכל דמנגע ברומי יהבו ליה מסתוריתא\u0004 \u0005[שהיו נוהגים שכל שנעשה מנוגע ברומי נותנים לו מסתורית],\u0006 \u0003ויתיב בשוקא וסתר דוללי\u0004 \u0005[ויושב בשוק וסותר פקעות],\u0006 \u0003כי היכי דליחזו אינשי וליבעי רחמי עליה\u0004 \u0005[כדי שיראו אנשים ויבקשו רחמים,\u0006 יתפללו \u0005עליו].\u0006","\u0003יומא חד הוה קא חליף התם\u0004 \u0005[יום אחד היה עובר שם]\u0006 ר' יהושע, \u0003הות יתבא וסתרה דוללי בשוקא דרומאי\u0004 \u0005[היתה יושבת\u0006 בת הקיסר \u0005וסותרת פקעות בשוק הרומאים],\u0006 \u0003אמר לה: שפירתא מסתוריתא דיהב ליך אלהי\u0004 \u0005[יפה המסתורית שנתן לך אלוהי]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אימא ליה\u0004 \u0005[אמור לו]\u0006 \u0003לאלהיך לשקול מאי דיהב לי\u0004 \u0005[שיטול\u0006 בחזרה \u0005מה שנתן לי].\u0006 \u0003אמר לה: אלהא דידן מיהב יהיב, משקל לא שקיל\u0004 \u0005[אלוהים שלנו לתת הוא נותן, ליטול אינו נוטל].\u0006","אגב משנתנו העוסקת בסימני בהמה וחיה, מביאים מה ש\u0003אמר רב יהודה: שור\u0004 דרכו שיהיה \u0003כרסתן,\u0004 בעל כרס גדולה, \u0003ופרסתן,\u0004 גדול פרסות, \u0003רב רישיה ורב גנובתיה\u0004 \u0005[גדול ראשו וגדול זנבו],\u0006 \u0003וחילופא בחמרא\u0004 \u0005[וחילוף הדברים בחמור].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]?\u0006 למה משנה הדבר? ומשיבים: \u0003למקח וממכר,\u0004 שהמוכר סתם שור לחבירו צריך לתת לו שור כזה, והיפך הדבר בחמור.","\u0003ואמר רב יהודה: שור שהקריב אדם הראשון, קרן אחת היתה לו במצחו, שנאמר: \"ותיטב לה'\u0004 (תודתי) \u0003משור פר מקרין מפריס\"\u0004 (תהלים סט, לב) — מאותו שור שהקריב אדם הראשון. ותוהים: \u0003\"מקרין\"\u0004 הלוא \u0003תרתי משמע\u0004 \u0005[שתים,\u0006 שתי קרנים \u0005משמעו],\u0006 שמשמעות \"מקרין\" היא — בעל קרניים! \u0003אמר רב נחמן: \"מקרן\" כתיב\u0004 \u0005[כתוב],\u0006 כלומר, הכתוב החסר רומז לקרן אחת.","\u0003ואמר רב יהודה: שור שהקריב אדם הראשון,\u0004 השור הראשון שנוצר — \u0003קרניו קודמות לפרסותיו,\u0004 \u0003שלא נולד מפרה, אלא יצא בשלמותו מן הארץ, וכיון שראשו יצא תחילה היו קרניו קודמות לפרסותיו,\u0004 \u0003שנאמר: \"ותיטב לה' משור פר מקרין מפריס\"\u0004 — \u0003מקרין ברישא\u0004 \u0005[בתחילה],\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מפריס.\u0004","ודבר זה, שהשור הראשון יצאו קרניו תחילה, \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: כל מעשה בראשית בקומתן\u0004 השלימה \u0003נבראו, בדעתן\u0004 השלימה \u0003נבראו, בצביונם\u0004 (בשלמות צורתם ויופיים) \u0003נבראו, שנאמר \"ויכולו השמים והארץ וכל צבאם\"\u0004 (בראשית ב, א), \u0003אל תקרי \"צבאם\", אלא \"צביונם\".\u0004","ועוד במעשה הבריאה, \u0003דרש ר' חנינא בר פפא:\u0004 הכתוב \u0003\"יהי כבוד ה' לעולם ישמח ה' במעשיו\"\u0004 (תהלים קד, לא), \u0003פסוק זה, שר העולם,\u0004 המלאך הממונה על העולם, \u0003אמרו; בשעה שאמר הקדוש ברוך הוא \"למינהו\" באילנות,\u0004 שציוה: \"תדשא הארץ דשא עשב מזריע זרע, עץ פרי עושה פרי למינו\" (בראשית א, יא), \u0003נשאו דשאים,\u0004 שלא נאמר בהם \"למינו\", \u0003קל וחומר בעצמן:\u0004","\u0003אם רצונו של הקדוש ברוך הוא בערבוביא\u0004 של מינים, \u0003למה אמר \"למינהו\" באילנות? ועוד קל וחומר\u0004 הוא: \u0003ומה\u0004 ב\u0003אילנות שאין דרכן לצאת בערבוביא,\u0004 שגדולים הם, וכל אחד ניכר לעצמו — \u0003אמר הקדוש ברוך הוא \"למינהו\",\u0004 שיצאו כל אחד לעצמו, \u0003אנו,\u0004 הדשאים, שדרכנו להיות מעורבבים — \u0003על אחת כמה וכמה?\u0004","\u0003מיד כל אחד ואחד יצא למינו,\u0004 ולא בערבוביא, שנאמר \"ותוצא הארץ דשא עשב מזריע זרע למינהו\" (שם יב). \u0003פתח שר העולם ואמר: \"יהי כבוד ה' לעולם ישמח ה' במעשיו\",\u0004 שהם עושים את רצונו, אפילו כשאינו אומר ומפרש אותו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבינא:\u0004 אם \u0003הרכיב שני\u0004 מיני \u0003דשאים זה על גב זה,\u0004 כעין שעושים בעצים, שלוקחים ענף מעץ אחד ומרכיבים אותו על עץ ממין אחר,"],["\u0003לר' חנינא בר פפא\u0004 שדרש דרשה זו, \u0003מהו? כיון דלא כתב בהו\u0004 \u0005[שלא כתוב בהם\u0006 בציווי\u0005]\u0006 \u0003\"למינהו\"\u0004 — \u0003לא מיחייב\u0004 \u0005[אין אדם חייב]\u0006 על הרכבה של דשאים. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003הסכים\u0004 הקדוש ברוך הוא \u0003אידיהו\u0004 \u0005[על ידם],\u0006 כפי שדרש את הכתוב \"ישמח ה' במעשיו\" — \u0003כמאן דכתיב בהו\u0004 \u0005[כמי שכתוב בהם]\u0006 \u0003\"למינהו\" דמיא\u0004 \u0005[נחשב]\u0006 הדבר? שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד במקראות במעשה הבריאה הנראים כסותרים. \u0003ר' שמעון בן פזי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויעש אלהים את שני המאורות הגדולים\"\u0004 (בראשית א, טז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"את המאור הגדול ואת המאור הקטן\"\u0004 (שם), הרי שאחד מהם קטן! אלא כך היה המעשה: בתחילה נעשו השמש והירח שניהם גדולים, \u0003אמרה ירח לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 וכי \u0003אפשר לשני מלכים שישתמשו בכתר אחד?\u0004 ומוכרח הדבר שיהיה סדר דרגות של ראשון ושני לו! \u0003אמר לה: לכי ומעטי את עצמך,\u0004 ואז לא יהיו שנים משתמשים בכתר אחד!","\u0003אמרה לפניו: רבונו של עולם, הואיל ואמרתי לפניך דבר הגון\u0004 \u0003אמעיט את עצמי?! אמר לה\u0004 כדי לפייסה: \u0003לכי ומשול ביום ובלילה,\u0004 שתאירי לא רק בלילה אלא גם ביום, כשהשמש מאירה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מאי רבותיה\u0004 \u0005[מה גדולתו]\u0006 של דבר זה? \u0003דשרגא בטיהרא מאי אהני\u0004 \u0005[שנר בצהרים מה מועיל]?\u0006 \u0003אמר לה: זיל\u0004 \u0005[לכי],\u0006 \u0003לימנו\u0004 \u0005[שימנו]\u0006 \u0003בך ישראל ימים ושנים,\u0004 ובכך תהא חשיבותך. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003יומא נמי\u0004 \u0005[השמש גם כן],\u0006 \u0003אי אפשר דלא מנו ביה תקופותא\u0004 \u0005[שלא ימנו בו תקופות],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והיו לאותות ולמועדים ולימים ושנים\"\u0004 (שם יד)! אמר לה: \u0003זיל\u0004 \u0005[לכי],\u0006 \u0003ליקרו צדיקי בשמיך\u0004 \u0005[שייקראו צדיקים בשמך],\u0006 כמו שנאמר \u0003\"יעקב הקטן\", \"שמואל הקטן\", \"דוד הקטן\".\u0004","\u0003חזייה דלא קא מיתבא דעתה\u0004 \u0005[ראה אותה שאין דעתה מתיישבת],\u0006 \u0003אמר הקדוש ברוך הוא: הביאו כפרה עלי שמיעטתי את הירח! והיינו דאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003ר' שמעון בן לקיש: מה נשתנה שעיר של ראש חדש\u0004 משאר שעירי חטאת שבפרשת קרבנות המועדים, \u0003שנאמר בו\u0004 \"ושעיר עזים אחד לחטאת \u0003לה' \"\u0004(במדבר כח, טו)? \u0003אמר הקדוש ברוך הוא: שעיר זה יהא כפרה על שמיעטתי את הירח.\u0004","ועוד במקראות בפרשת הבריאה הנראים כסותרים. \u0003רב אסי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ותוצא הארץ דשא\"\u0004 (בראשית א, יב), ודבר זה נאמר \u0003בתלת בשבתא\u0004 \u0005[בשלישי בשבת],\u0006 \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכל שיח השדה טרם יהיה בארץ\"\u0004 (שם ב, ה) ודבר זה הוא \u0003במעלי שבתא\u0004 \u0005[בערב שבת,\u0006 ביום השישי\u0005],\u0006 קודם בריאת האדם. כיצד? \u0003מלמד שיצאו דשאים\u0004 ביום השלישי \u0003ועמדו על פתח קרקע,\u0004 אבל לא יצאו החוצה \u0003עד שבא אדם הראשון ובקש עליהם רחמים, וירדו גשמים וצמחו. ללמדך שהקדוש ברוך הוא מתאוה לתפלתן של צדיקים.\u0004","ובענין זה מסופר, \u0003רב נחמן בר פפא הויא ליה ההיא גינתא\u0004 \u0005[היתה לו גינה אחת],\u0006 \u0003שדי ביה ביזרני ולא צמח\u0004 \u0005[זרע בה זרעים ולא צמחו],\u0006 \u0003בעא רחמי אתא מיטרא\u0004 \u0005[ביקש רחמים\u0006 בתפילה \u0005בא הגשם]\u0006 \u0003וצמח, אמר: היינו\u0004 \u0005[הוא שאמר]\u0006 \u0003רב אסי,\u0004 שהקדוש ברוך הוא מתאוה לתפילתן של צדיקים.","בפרשת בעלי החיים הטהורים והטמאים שבספר דברים נאמר: \"אך את זה לא תאכלו ממעלי הגרה וממפריסי הפרסה השסועה את הגמל ואת הארנבת ואת השפן\" (דברים יד, ז). \u0003אמר רב חנן בר רבא: השסועה\u0004 אינו תיאור של הפרסה, שהיא מחולקת לשתים, אלא \u0003בריה בפני עצמה היא, שיש לה שני גבין ושני שדראות,\u0004 ונראית כמחולקת לשני בעלי חיים נפרדים. ויש לשאול: \u0003וכי משה רבינו\u0004 שציוה על כך \u0003קניגי\u0004 (צייד) \u0003היה או בליסטרי\u0004 (רובה קשת) \u0003היה,\u0004 ומכיר בכל מיני חיות שאינן מצויות? אלא \u0003מכאן תשובה לאומר אין תורה מן השמים,\u0004 שהרי רק משום שגילו לו מן השמים על חיה זו יכול היה לצוות עליה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב תחליפא בר אבינא:\u0004 \u0003זיל כתוב\u0004 \u0005[לך וכתוב]\u0006 אגדה זו של \u0003\"קניגי ובליסטרי\" באגדתיך\u0004 \u0005[בספר האגדה]\u0006 שלך, \u0003ופרשה\u0004 את המילים הללו שבה, שאינן ידועות לכל.","וכיוצא בזה מסופר, נאמר: \u0003\"ואת חמשת סרני פלשתים העזתי והאשדודי האשקלוני הגתי והעקרוני והעוים\"\u0004 (יהושע יג, ג), וקשה, ש\u0003אמר\u0004 תחילה \u0003חמשה\u0004 סרני פלשתים \u0003וחשיב שיתא\u0004 \u0005[ומנה שישה]!\u0006 \u0003אמר ר' יונתן\u0004 בטעם הדבר: באמת היו ששה, ואולם \u0003ארונקי שלהן,\u0004 החשובים שבהם, הם \u0003חמשה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לר' תחליפא בר אבינא: כתוב\u0004 דרשה זו של \u0003\"ארונקי\" באגדתיך\u0004 \u0005[באגדתך],\u0006 \u0003ופרשה\u0004 את המלה הזו. ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דרשה זו על שיטת \u0003רב,\u0004 ש\u0003אמר רב: עוים\u0004 אינם מן הפלישתים, אלא \u0003מתימן באו.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003עוים מתימן באו, ולמה נקרא שמן עוים\u0004 ולא \"תימנים\"? על שום \u0003שעיותו\u0004 והחריבו \u0003את מקומן\u0004 כשיצאו משם. \u0003דבר אחר: עוים\u0004 בחילוף ע' וא' — משום \u0003שאיוו לאלהות הרבה. דבר אחר: עוים\u0004 — שהיו מפחידים כל כך \u0003שכל הרואה אותם אוחזתו עוית. אמר רב יוסף: ואית להו שיתסרי דרי שיני לכל חד וחד\u0004 \u0005[ויש להם שש עשרה שורות שיניים לכל אחד ואחד].\u0006","ובענין העוים מביאים מה שאמר ר' שמעון בן לקיש: הרבה מקראות יש \u0003שראויין לשרוף כספרי מינין\u0004 (כופרים), שנראה שאין בהם צורך, ואינם ראויים להיכתב, \u0003ו\u0004אולם \u0003הן הן גופי\u0004 (עיקרי) \u0003תורה.\u0004 כגון האמור: \u0003\"והעוים היושבים בחצרים עד עזה\u0004 כפתורים היוצאים מכפתור השמידום וישבו תחתם\" (דברים ב, כג), ולכאורה, \u0003מאי נפקא לן מינה\u0004 \u0005[מה יוצא לנו מכאן]?\u0006 לשם מה נכתב?","אלא כך הוא טעמם של דברים: \u0003מדאשבעיה\u0004 \u0005[ממה שהשביע]\u0006 \u0003אבימלך\u0004 מלך פלשתים \u0003לאברהם \"אם תשקור לי ולניני ולנכדי\"\u0004 (בראשית כא, כג), נמצא שבני ישראל לא יוכלו לרשת את ארץ פלשתים עד לאחר ארבעה דורות, לכן \u0003אמר הקדוש ברוך הוא:\u0004 \u0003ליתו\u0004 \u0005[יבואו]\u0006 \u0003כפתורים, ליפקו\u0004 \u0005[יוציאו]\u0006 את הארץ \u0003מ\u0004ה\u0003עוים, דהיינו\u0004 \u0005[שהם]\u0006 מן ה\u0003פלשתים, וליתו\u0004 \u0005[ויבואו]\u0006 \u0003ישראל ליפקו\u0004 \u0005[יוציאו]\u0006 \u0003מ\u0004ה\u0003כפתורים.\u0004","\u0003כיוצא בדבר אתה אומר\u0004 על פסוק אחר הנראה כסיפור דברים שאין בו צורך. לאחר שתיארה התורה את כיבוש עבר הירדן מיד סיחון מלך האמורי, נאמר: \u0003\"כי חשבון עיר סיחון מלך האמורי היא, והוא נלחם במלך מואב\"\u0004 (במדבר כא, כו), ולכאורה \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]?\u0006 לשם מה נאמר שנלחם במלך מואב? אלא משום \u0003דאמר להו\u0004 \u0005[שאמר להם]\u0006 \u0003הקדוש ברוך הוא לישראל: \"אל תצר את מואב\"\u0004 (דברים ב, ט), \u0003אמר הקדוש ברוך הוא: ליתי\u0004 \u0005[יבוא]\u0006 \u0003סיחון ליפוק\u0004 \u0005[ויוציא]\u0006 \u0003ממואב\u0004 שטחים אלו, \u0003וליתו\u0004 \u0005[ו\u0006כך \u0005יבואו]\u0006 \u0003ישראל וליפקו\u0004 \u0005[ויוציאו]\u0006 אותם \u0003מ\u0004יד \u0003סיחון,\u0004 וכך לא יעברו על האיסור. ומעירים, \u0003והיינו דאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003רב פפא: עמון ומואב טיהרו בסיחון,\u0004 כלומר חלקים מארצם נעשו \u0003כשרים לכיבוש ישראל על ידי כיבושו של סיחון. ועוד\u0004","כתוב שאינו מובן: \u0003\"צידונים יקראו לחרמון שריון\u0004 והאמורי יקראו לו שניר\" (דברים ג, ט), ועל כך \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 והרי \u0003שניר ושריון\u0004 — \u0003מהרי ארץ ישראל\u0004 הם! אלא \u0003מלמד שכל אחד ואחד מאומות העולם הלך ובנה לו כרך גדול לעצמו, והעלה\u0004 (קרא) \u0003לו\u0004 שם \u0003על שם\u0004 אחד מ\u0003הרי ארץ ישראל. ללמדך, שאפילו הרי ארץ ישראל חביבין על האומות העולם.\u0004","\u0003כיוצא בו\u0004 מה שנאמר ביוסף \u0003במצרים: \"ואת העם העביר אותו לערים\"\u0004 (בראשית מז, כא), \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]?\u0006 מה בא ללמדנו? את אהבתו וכבודו של יוסף לאחיו, שהיגלה את כל המצרים ממקומם כדי \u0003דלא ליקרו לאחיו גלוותא\u0004 \u0005[שלא יקראו לאחיו\u0006 שבאו מארץ ישראל \u0005גולים].\u0006","שנינו במשנה: \u0003סימני העוף לא נאמרו\u0004 בתורה. ושואלים: \u0003ו\u0004כי \u0003לא\u0004 נאמרו? וכי אי אפשר ללמוד אותם מן הכתוב? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003נשר\u0004 (ויקרא יא, יג) נמנה בין רשימת העופות הטמאים, וממנו יש ללמוד:"],["\u0003מה נשר\u0004 שנזכר בכתוב הוא \u0003מיוחד\u0004 במה \u0003שאין לו אצבע יתרה, ו\u0004אין לו \u0003זפק, ואין קורקבנו נקלף, ו\u0004הוא \u0003דורס ואוכל\u0004 — \u0003טמא, אף כל כיוצא בו\u0004 שיש בו ארבע סימנים אלה — \u0003טמא.\u0004 ומצד אחר, מה \u0003תורין\u0004 (ובני יונה) \u0003שיש להן אצבע יתרה, וזפק, וקורקבן נקלף, ואין דורסין ואוכלין\u0004 — \u0003טהורין,\u0004 שהרי נבחרו להקרבה על גבי המזבח (ויקרא א, יד), \u0003אף כל כיוצא בהן,\u0004 שיש בהם ארבעה סימנים אלה — \u0003טהורין.\u0004 ואם כן, כיצד שנינו במשנה שסימני העוף לא נאמרו מן התורה? \u0003אמר אביי,\u0004 כך צריך להבין את לשון המשנה: סימני העוף \u0003לא נאמר פירושן,\u0004 כלומר, לא נתפרש מה הם \u0003מדברי תורה,\u0004 \u0003אלא מדברי סופרים,\u0004 שהם פירשו את הסימנים.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: עוף הבא\u0004 לפנינו \u0003בסימן אחד\u0004 בלבד של טהרה, ואינו מן העופות הטמאים שפירטה התורה — \u0003טהור, לפי שאין\u0004 זה \u0003דומה לנשר.\u0004 שמשום כך הזכיר הכתוב גם נשר ברשימת העופות הטמאים, אף שיכול היה איסורו להילמד מן העופות האחרים שאסרה התורה — כדי ללמדנו: \u0003נשר, דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003כלל\u0004 סימני טהרה — \u0003הוא דלא תיכול\u0004 \u0005[שלא תאכל],\u0006 \u0003הא איכא דאית ליה חד\u0004 \u0005[אבל\u0006 אם \u0005יש\u0006 עוף \u0005שיש לו\u0006 אפילו \u0005אחד]\u0006 מהסימנים — \u0003תיכול\u0004 \u0005[תאכל]\u0006 אותו.","ושואלים: ומדוע נלמד מנשר להכשיר? \u0003ולילף\u0004 \u0005[ונלמד]\u0006 להיפך \u0003מתורין\u0004 לאוסרו: \u0003מה תורין\u0004 שהכשיר הכתוב במפורש הם עופות \u0003דאיכא כולהו\u0004 \u0005[שיש\u0006 להם \u0005כל]\u0006 ה\u0003ארבעה\u0004 סימנים — \u0003אף הני נמי\u0004 \u0005[אלה גם כן],\u0006 שאר עופות שבאים לפנינו, אינם כשרים \u0003עד דאיכא כולהו\u0004 \u0005[שיש\u0006 להם \u0005כל]\u0006 \u0003ארבעה\u0004 סימני הטהרה!","ומשיבים: \u0003אם כן,\u0004 שאנו למדים דבר זה מתורים, \u0003שאר עופות טמאין דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שהם אסורים, \u0003למה לי\u0004 לכותבם? והרי אין בהם אחד שיש בו כל ארבעת סימני הטהרה, ואם כן ניתן היה ללמוד את איסורם מתורים! אלא מכאן שאין למדים דין זה מתורים.","ושואלים: ומדוע למדים מנשר שדי בסימן אחד של טהרה? \u0003ונילף מינייהו\u0004 \u0005[ונלמד מהם],\u0006 מרוב העופות הטמאים, שיש בהם שלושה סימנים טהרה: \u0003מה התם\u0004 \u0005[שם],\u0006 בעופות הללו, יש \u0003תלתא\u0004 \u0005[שלושה]\u0006 סימנים של טהרה, \u0003ולא אכלינן\u0004 \u0005[ו\u0006עם כל זה \u0005אין אנו אוכלים\u0006 אותם\u0005]\u0006 — \u0003אף כל\u0004 עוף שבא לפנינו, שיש לו \u0003תלתא\u0004 \u0005[שלושה]\u0006 סימני טהרה — טמא הוא, \u0003ולא ניכול\u0004 \u0005[ולא נאכל]\u0006 אותו, \u0003וכל שכן\u0004 אם יש בו רק \u0003תרי\u0004 \u0005[שני]\u0006 סימנים, או רק \u0003חד\u0004 \u0005[אחד]!\u0006","ומשיבים: \u0003אם כן, עורב,\u0004 שיש לו שני סימני טהרה, \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שהוא טמא, \u0003למה לי? השתא\u0004 \u0005[עכשיו]\u0006 שאתה אומר שעוף \u0003דאית ליה תלתא\u0004 \u0005[שיש לו שלושה]\u0006 סימני טהרה בלבד \u0003לא אכלינן\u0004 \u0005[אין אוכלים אנו אותו],\u0006 עורב \u0003דאית ליה תרי מיבעיא\u0004 \u0005[שיש לו שני סימני טהרה\u0006 בלבד \u0005נצרכה לומר]\u0006 שהוא אסור? אלא מכאן שלא התכוונה התורה שנלמד מהם, אלא דווקא אלה שנזכרו במפורש לאיסור הריהם אסורים, אבל שאר עופות שיש בהם שלושה סימני טהרה — מותרים."],["ושואלים: \u0003ולילף\u0004 \u0005[ונלמד]\u0006 \u0003מעורב\u0004 שנזכר ברשימת העופות הטמאים: \u0003מה התם\u0004 \u0005[שם]\u0006 \u0003תרי לא\u0004 \u0005[בשני\u0006 סימנים בלבד \u0005אינו]\u0006 טהור, \u0003אף כל\u0004 עוף שיש בו \u0003תרי\u0004 \u0005[שני\u0006 סימנים\u0005]\u0006 \u0003לא\u0004 טהור! ומשיבים: \u0003אם כן, פרס ועזניה\u0004 שיש בהם רק סימן אחד של טהרה, \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שהם טמאים, \u0003למה לי? השתא דאית ליה תרי לא אכלינן\u0004 \u0005[עכשיו,\u0006 הרי עורב \u0005שיש לו שני\u0006 סימני טהרה \u0005אין אנו אוכלים],\u0006 פרס ועזניה \u0003דאית ליה חד מיבעיא\u0004 \u0005[\u0006\u0005שיש לו רק סימן אחד נצרכה לומר]\u0006 שהוא טמא? אלא מכאן שעוף שיש בו שני סימני טהרה — טהור, חוץ מעורב שנאמר במפורש שהוא טמא.","ושואלים: \u0003וניגמר\u0004 \u0005[ונלמד]\u0006 \u0003מפרס ועזניה\u0004 שכל עוף שיש בו רק סימן אחד של טהרה טמא! ומשיבים: \u0003אם כן, נשר,\u0004 שאין בו אפילו סימן טהרה אחד, \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שהוא טמא, \u0003למה לי?\u0004 \u0003השתא דאית ליה חד\u0004 \u0005[עכשיו,\u0006 פרס ועזניה \u0005שיש לו סימן אחד]\u0006 \u0003לא אכלינן\u0004 \u0005[אין אנו אוכלים],\u0006 \u0003דלית ליה כלל מיבעיא\u0004 \u0005[\u0006נשר \u0005שאין לו כלל\u0006 סימני טהרה \u0005נצרכה לומר]\u0006 שהוא טמא? \u0003אלא\u0004 לכך הוזכר נשר — כדי ללמד: \u0003נשר דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003כלל\u0004 סימני טהרה — \u0003הוא דלא תיכול\u0004 \u0005[שלא תאכל],\u0006 \u0003הא דאית ליה חד\u0004 \u0005[אבל\u0006 עוף \u0005שיש לו\u0006 סימן טהרה \u0005אחד]\u0006 — \u0003אכול.\u0004","ושואלים: \u0003ואלא\u0004 לפי זה, \u0003טעמא\u0004 \u0005[הטעם],\u0006 דווקא משום \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003נשר\u0004 אתה למד כן, \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כן]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003לילף\u0004 \u0005[נלמד]\u0006 \u0003מפרס ועזניה,\u0004 שעוף הבא לפנינו בסימן אחד טמא? וכיצד היינו אומרים כן? והרי \u0003הוה ליה\u0004 \u0005[הרי הם]\u0006 \u0003פרס ועזניה שני כתובין הבאין כאחד,\u0004 ששניהם מלמדים אותו דבר, \u0003ו\u0004כלל הוא במדרש ההלכה ש\u0003שני כתובין הבאין כאחד\u0004 — \u0003אין מלמדין\u0004 לדינים אחרים!","ומשיבים: \u0003גמירי\u0004 \u0005[למודים אנו במסורת],\u0006 \u0003דאיכא בהאי ליכא בהאי\u0004 \u0005[\u0006שסימן הטהרה \u0005שיש בזה,\u0006 בפרס — \u0005אין בזה,\u0006 בעזניה\u0005],\u0006 \u0003ודאיכא בהאי ליכא בהאי\u0004 \u0005[ושיש בזה,\u0006 בעזניה — \u0005אין בזה,\u0006 בפרס\u0005],\u0006 ונמצא שאין הם שני כתובים הבאים כאחד, אלא כל אחד מלמד דבר אחר, וניתן היה, איפוא, ללמוד מהם שכל עוף שיש בו רק סימן טהרה אחד שהוא טמא. ולכן הוצרכה התורה לכתוב נשר, שאין בו אפילו סימן טהרה אחד, כדי ללמדנו שעוף הבא לפנינו, ויש בו סימן אחד — הריהו טהור.","ושואלים: ועדיין, \u0003מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003עשרים וארבעה עופות טמאים הוו\u0004 \u0005[הם]\u0006 שהוזכרו בכתוב, הרי \u0003אי אפשר דחד דאיכא בהנך ליכא בהני\u0004 \u0005[ש\u0006סימן \u0005אחד שיש באלה,\u0006 בפרס ובעזניה, \u0005אינו\u0006 נמצא גם \u0005באחרים],\u0006 \u0003ו\u0004אם כן ביחס לכל אחד מאותם שני סימנים \u0003הוו להו\u0004 \u0005[יש כאן]\u0006 \u0003שני כתובים הבאים כאחד,\u0004 ואם כן לא ניתן היה ללמוד על העוף הבא לפנינו בסימן טהרה של פרס או של עזניה שהוא טמא, ולא הוצרכנו ללימוד מן הנשר כדי להכשירו!","ומשיבים: \u0003גמירי\u0004 \u0005[למודים אנו]:\u0006 \u0003עשרים וארבעה עופות טמאים הוו\u0004 \u0005[הם]\u0006 המפורשים בתורה, \u0003וארבעה סימנין\u0004 של טהרה יש בעוף; \u0003תלתא הדרי בכולהו\u0004 \u0005[שלושה\u0006 סימני טהרה \u0005נמצאים בכולם],\u0006 כלומר, הסימנים הללו נמצאים, כולם או חלקם בעופות הטמאים המנויים במקרא. \u0003עשרים מהם\u0004 מן העופות — יש בהם \u0003שלשה שלשה\u0004 סימני טהרה, \u0003ותרי\u0004 \u0005[ושנים]\u0006 מתוך השלושה קיימים \u0003בעורב, חד\u0004 \u0005[\u0006סימן \u0005אחד]\u0006 \u0003בפרס, וחד\u0004 \u0005[ו\u0006סימן \u0005אחד]\u0006 \u0003בעזניה, דאיתיה בהא ליתיה בהא\u0004 \u0005[והסימן שיש בזה,\u0006 בפרס, \u0005אין בזה,\u0006 בעזניה\u0005],\u0006 ולהיפך. ונמצא שאחד הסימנים, של פרס או של עזניה, הוא הסימן הרביעי, שנמצא אך ורק בו ולא בעוף אחר מן העופות הטמאים; \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליליף מיניה\u0004 \u0005[נלמד ממנו],\u0006 שכל שיש לו רק סימן טהרה אחד כמוהו הריהו טמא — על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003נשר,\u0004 לומר: \u0003נשר דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003כלל\u0004 סימנים — \u0003הוא דלא תיכול\u0004 \u0005[שלא תאכל],\u0006 \u0003הא איכא דאית ליה חד\u0004 \u0005[אבל\u0006 אם \u0005יש\u0006 עוף \u0005שיש לו\u0006 סימן טהרה \u0005אחד]\u0006 \u0003אכול.\u0004","ואומרים: \u0003אלא,\u0004 מאחר שלמדנו מנשר שכל עוף שיש לו אפילו סימן טהרה אחד הריהו טהור, \u0003תורין\u0004 שיש בהם ארבעה סימני טהרה \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שהם טהורים \u0003למה לי? אמר רב עוקבא בר חמא:\u0004 לא לענין טהרתם נכתבו, ללמד שהם כשרים לאכילה, אלא \u0003לקרבן,\u0004 לומר שמצות קרבן היא באלה דווקא, ולא בעופות אחרים. \u0003אמר רב נחמן:\u0004"]]};
